///|
fn Progress::new(
  stage : String,
  environment? : Map[String, String],
) -> Progress {
  let secrets = []
  for name, value in environment.unwrap_or(@env.get_env_vars()) {
    if sensitive_name(name) && value != "" {
      secrets.push(value)
      // Multiline credentials must also be masked in line-oriented output.
      for part in value.split("\n") {
        if part.trim() != "" {
          secrets.push(part.to_owned())
        }
      }
    }
  }
  secrets.sort_by((a, b) => b.length().compare(a.length()))
  {
    stage,
    operations: {},
    builds: {},
    secrets,
    recording: environment
    .unwrap_or(@env.get_env_vars())
    .get("ORCA_ENV_DEVSY_RECORDING") !=
    Some("0"),
    phase_count: 0,
    private_key: false,
    classic_build: false,
    recent: [],
}

///|
fn Progress::safe_message(self : Progress, text : String) -> String? {
  guard terminal_text(text) is Some(text) else { return None }
  let lower = text.to_lower()
  if lower.contains("-----begin ") && lower.contains("private key-----") {
    self.private_key = REDACTED ")
    return Some("[private key redacted]")
  }
  if self.private_key {
    if lower.contains("-----end ") && lower.contains("private key-----") {
      self.private_key = false
    }
    return None
  }
  let mut safe = text
  for secret in self.secrets {
    safe = safe.replace_all(old=secret, new="[redacted]")
  }
  safe = redact_credentials(safe)
  if safe.length() > 1024 {
    safe = safe[:1024].to_owned() + "… [truncated]"
    self.details_truncated = true
  }
  Some(safe)
}
