///|
const WRITESPACE = -3

///|
const PADDING = -2

///|
const INVALID_CHAR = -1

///|
fn base64_value(code_unit : Int) -> Int {
  match code_unit {
    'A'..='Z' => code_unit - 'A'
    'a'..='z' => code_unit - 'a' + 26
    '0'..='9' => code_unit - '0' + 52
    '+' => 62
    '/' => 63
    ' ' | '\n' | '\r' | '\t' => WRITESPACE
    '=' => PADDING
    _ => INVALID_CHAR
  }
}
