///|
let recording_run_id : String = @env.now().to_string() +
  "_" +
  proxy_pid().to_string()

///|
fn diagnostic_error(
  error : Error,
  environment? : Map[String, String],
) -> String {
  let (message, omitted) = match error {
    AdapterError(detail) => (detail, false)
    InvalidConfig(detail) => (detail, false)
    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
    @json.InvalidNumber(position, _) =>
      (
        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
        true,
      )
    _ => (error.to_string(), false)
  }
  diagnostic_text(message, environment?, omitted~)
}

///|
fn diagnostic_text(
  message : String,
  environment? : Map[String, String],
  omitted~ : Bool = false,
  protected_values? : Array[String],
) -> String {
  let progress = Progress::new("diagnostic-error", environment?)
  if protected_values is Some(values) {
    for value in values {
      if value != "" {
        progress.secrets.push(value)
      }
    }
    progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
  }
  let lines = []
  let mut incomplete = omitted
  for line in message.split("\n") {
    if lines.length() == 8 {
      incomplete = true
      break
    }
    let bounded = if line.length() > 8192 {
      incomplete = true
      line[:8192].to_owned()
    } else {
      line.to_owned()
    }
    match progress.safe_message(bounded) {
      Some(safe) => lines.push(safe)
      None => {
        incomplete = true
        lines.push("[unavailable]")
      }
    }
  }
  if incomplete || progress.details_truncated {
    lines.push("[error details incomplete or truncated]")
  }
  lines.join("\n")
}

///|
priv struct DiagnosticProtectedValues {
  values : Array[String]
  mut visited : Int32
  mut incomplete : Bool
}

///|
fn diagnostic_protected_values(
  value : Json,
  result : DiagnosticProtectedValues,
) -> Unit {
  if result.visited >= 4096 || result.values.length() >= 512 {
    result.incomplete = true
    return
  }
  result.visited += 1
  match value {
    Json::String(text) if text.length() >= 4 => {
      result.values.push(text)
      for word in text.split(" ") {
        for part in word.split("=") {
          if part.length() >= 4 && part.length() < text.length() {
            if result.values.length() >= 512 {
              result.incomplete = true
              return
            }
            result.values.push(part.to_owned())
          }
        }
      }
      let escaped = Json::string(text).stringify()
      if escaped.length() > 2 {
        let encoded = escaped[1:escaped.length() - 1].to_owned()
        if encoded.length() >= 4 && encoded != text {
          result.values.push(encoded)
        }
      }
    }
    Json::Array(values) =>
      for item in values {
        diagnostic_protected_values(item, result)
      }
    Json::Object(values) =>
      for _, item in values {
        diagnostic_protected_values(item, result)
      }
    _ => ()
  }
}

///|
fn diagnostic_output(
  output : Bytes,
  environment : Map[String, String],
  protected_input? : String,
  omitted~ : Bool = false,
) -> String? {
  if output.length() == 0 {
    return None
  }
  let safeguards : DiagnosticProtectedValues = {
    values: [],
    visited: 0,
    incomplete: false,
  }
  if protected_input is Some(input) {
    diagnostic_protected_values(@json.parse(input), safeguards) catch {
      _ => safeguards.incomplete = true
    }
  }
  if safeguards.incomplete {
    return Some(
      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
    )
  }
  let limit = if output.length() > 8192 { 8192 } else { output.length() }
  Some(
    diagnostic_text(
      @utf8.decode_lossy(output[:limit]),
      environment~,
      omitted=omitted || limit < output.length(),
      protected_values=safeguards.values,
    ),
  )
}

///|
async fn diagnostic_capture(
  reader : @process.ReadFromProcess,
  limit : Int32,
) -> (Bytes, Bool) {
  let output = @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 })
  let mut truncated = false
  while reader.read_some(max_len=4096) is Some(chunk) {
    let remaining = limit - output.length()
    let count = if chunk.length() < remaining {
      chunk.length()
    } else {
      remaining
    }
    if count > 0 {
      output.write_bytes(chunk[:count])
    }
    if count < chunk.length() {
      truncated = true
    }
  }
  (output.to_bytes(), truncated)
}

///|
async fn diagnostic_process_output(
  program : String,
  args : Array[String],
  environment~ : Map[String, String],
  cwd? : StringView,
  stdin? : &@process.ProcessInput,
  stdout_limit~ : Int32,
  stderr_limit~ : Int32,
) -> (Int32, Bytes, Bool, Bytes, Bool) {
  let (out, stdout) = @process.read_from_process()
  defer out.close()
  let (err, stderr) = @process.read_from_process()
  defer err.close()
  @async.with_task_group(async fn(group) {
    let child = @process.spawn(
      group,
      program,
      args,
      extra_env=environment,
      inherit_env=false,
      cwd?,
      stdin?,
      stdout~,
      stderr~,
    )
    let output = group.spawn(async fn() {
      diagnostic_capture(out, stdout_limit)
    })
    let errors = group.spawn(async fn() {
      diagnostic_capture(err, stderr_limit)
    })
    let status = child.wait()
    let (output, output_truncated) = output.wait()
    let (errors, errors_truncated) = errors.wait()
    (status, output, output_truncated, errors, errors_truncated)
  })
}

///|
async fn save_command_failure(
  stage : String,
  error : Error,
  recording? : Bool,
  phase? : String,
) -> Unit {
  if !recording.unwrap_or(
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
    ) {
    return
  }
  let cancelled = @async.is_being_cancelled()
  let timeout = error is @async.TimeoutError
  save_diagnostic(
    stage,
    if cancelled {
      "cancelled"
    } else if timeout {
      "timeout"
    } else {
      "failed"
    },
    error_type=if cancelled {
      "cancelled"
    } else if timeout {
      "timeout"
    } else if error is InvalidConfig(_) {
      "invalid_config"
    } else if error is AdapterError(_) {
      "adapter_error"
    } else if error is @os_error.OSError(_, ..) {
      "os_error"
    } else {
      "unexpected_error"
    },
    os_errno?=match error {
      @os_error.OSError(code, ..) => Some(code)
      _ => None
    },
    phase?,
    error_message=diagnostic_error(error),
    recording?,
  )
}

///|
fn process_error_type(output : String) -> String {
  let text = output.to_lower()
  if text.contains("out of memory") || text.contains("cannot allocate memory") {
    "memory_exhausted"
  } else if text.contains("no space left on device") {
    "disk_exhausted"
  } else if text.contains("address already in use") ||
    text.contains("addrinuse") {
    "address_in_use"
  } else if text.contains("permission denied (publickey") ||
    text.contains("authentication failed") {
    "authentication_failed"
  } else if text.contains("host key verification failed") {
    "host_key_failed"
  } else if text.contains("connection refused") {
    "connection_refused"
  } else if text.contains("connection timed out") ||
    text.contains("operation timed out") {
    "connection_timeout"
  } else if text.contains("could not resolve hostname") {
    "name_resolution"
  } else if text.contains("controlsocket") || text.contains("control socket") {
    "control_socket"
  } else if text.contains("build_vm:") {
    "vm_boot"
  } else if text.contains("create microsandbox vm") && text.contains("network:") {
    "vm_network"
  } else if text.contains("create microsandbox vm") && text.contains("mount:") {
    "vm_mount"
  } else if text.contains("ensure microsandbox final image") ||
    text.contains("prepare microsandbox final image") {
    "vm_image"
  } else if text.contains("create microsandbox vm") {
    "vm_create"
  } else if text.contains("start microsandbox vm") {
    "vm_start"
  } else if text.contains("no such file or directory") ||
    text.contains("not found") {
    "missing_resource"
  } else if text.contains("permission denied") {
    "permission_denied"
  } else if text.contains("database is locked") ||
    text.contains("database locked") {
    "database_locked"
  } else if text.contains("too many open files") {
    "file_limit"
  } else {
    "process_exit"
  }
}

///|
async fn tunnel_errors(
  reader : @process.ReadFromProcess,
  environment : Map[String, String],
) -> (String, String, Bool) {
  defer reader.close()
  let progress = Progress::new("ssh-tunnel", environment~)
  let tail = progress.read_output(reader, capture=false, raw_messages=true)
  (
    process_error_type(tail),
    progress.failure_detail(),
    progress.details_truncated,
  )
}

///|
priv struct CreateRecording {
