///|
priv struct DiagnosticRecordingHealth {
  mut dropped : Int32
  mut first_dropped : UInt64
  mut last_dropped : UInt64
  mut reason : String
  mut warned : Bool
}

///|
let diagnostic_recording_health : DiagnosticRecordingHealth = {
  dropped: 0,
  first_dropped: 0,
  last_dropped: 0,
  reason: "",
  warned: false,
}

///|
async fn diagnostic_recording_failed(reason : String) -> Unit {
  let now = @env.now()
  if diagnostic_recording_health.dropped == 0 {
    diagnostic_recording_health.first_dropped = now
  }
  diagnostic_recording_health.dropped += 1
  diagnostic_recording_health.last_dropped = now
  diagnostic_recording_health.reason = reason
  if !diagnostic_recording_health.warned {
    diagnostic_recording_health.warned = true
    @async.with_timeout(100, async fn() {
      @stdio.stderr.write(
        "orca-env-devsy: warning: diagnostic recording is unavailable (" +
        reason +
        ")\n",
      )
    }) catch {
      _ => ()
    }
  }
}

///|
fn diagnostic_recording_event(status : String, reason : String) -> Json {
  {
    "stage": "diagnostic-recording",
    "status": status,
    "errorType": reason,
    "completeness": "partial",
    "time": @env.now().to_string(),
    "runId": recording_run_id,
    "adapterVersion": version,
  }
}

///|
async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  timeout_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
  error_message? : String,
  details_truncated~ : Bool = false,
  tunnel_directory? : String,
  expected_workspace_uid? : String,
  observed_workspace_uid? : String,
  evidence? : Json,
  recording? : Bool,
