///|
async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  timeout_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
  error_message? : String,
