  for mode in ["rotation", "incomplete"] {
    let (directory, env) = fixture()
    defer cleanup_fixture(directory)
    let root = directory + "/.local/state/orca-env-devsy"
    @fs.mkdir(root, recursive=true)
    let path = root + "/events.jsonl"
    if mode == "rotation" {
      @fs.write_file(path, "{\"stage\":\"old\"}\n".repeat(20000))
    } else {
      @fs.write_file(path, "{\"stage\":\"old\"}\n{\"stage\":\"partial\"")
    }
    let (status, _, errors) = bulk_fixture_run(
      ["status", "--provider", "fixture-provider"],
      env,
    )
    assert_eq(status, 0, msg=errors)
    let events = fixture_events(directory)
    let markers = events.filter(event => {
      field(event, "stage") == Some(Json::string("diagnostic-recording"))
    })
    assert_eq(markers.length(), 1)
    assert_eq(field(markers[0], "completeness"), Some(Json::string("partial")))
    assert_eq(
      field(markers[0], "errorType"),
      Some(
        Json::string(
          if mode == "rotation" {
            "retention_limit"
          } else {
            "incomplete_record"
          },
        ),
      ),
    )
    assert_eq(
      events
      .iter()
      .any(event => field(event, "stage") == Some(Json::string("old"))),
      mode == "incomplete",
    )
    assert_true(
      events
      .iter()
      .any(event => {
        field(event, "stage") == Some(Json::string("bulk")) &&
        field(event, "status") == Some(Json::string("success"))
      }),
    )
  }
}

///|
async test "diagnostic recording reports loss and resumes without changing the result" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  @fs.write_file(
    directory + "/orca.yaml",
    "devsy: {connection: ssh, buildRef: refs/heads/main}\nenvironmentRecipes: [{id: test}]\n",
  )
  let root = directory + "/.local/state/orca-env-devsy"
  @fs.mkdir(root + "/events.jsonl", recursive=true)
  @fs.rename(directory + "/bin/devsy", directory + "/bin/devsy-original")
  let wrapper =
    #|#!/bin/sh
    #|case "$*" in *'context list'*) rmdir "$XDG_STATE_HOME/orca-env-devsy/events.jsonl" ;; esac
    #|exec "$HOME/bin/devsy-original" "$@"
  @fs.write_file(directory + "/bin/devsy", wrapper + "\n", permission=0o700)
  let (status, output, errors) = invoke("create", env, directory)
  assert_eq(status, 0, msg=errors)
  assert_true(
    errors.contains("diagnostic recording is unavailable (invalid_store)"),
  )
  let events = fixture_events(directory)
  let markers = events.filter(event => {
    field(event, "errorType") == Some(Json::string("invalid_store"))
  })
  assert_eq(markers.length(), 1)
  assert_eq(field(markers[0], "completeness"), Some(Json::string("partial")))
  assert_true(
    field(markers[0], "droppedEvents") is Some(Json::Number(n, ..)) && n > 0,
  )
  assert_true(field(markers[0], "missingFromTime") is Some(Json::String(_)))
  let payload : Json = {
    "schemaVersion": 1,
    "recipeResult": @json.parse(output),
  }
  let (destroyed, _, destroy_error) = invoke(
    "destroy",
    env,
    directory,
    payload~,
  )
  assert_eq(destroyed, 0, msg=destroy_error)
}

