async test "settings transport errors retain cause without profile values" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  with_fake_tunnel(directory, async fn() {
    @fs.write_file(
      directory + "/orca.yaml",
      "devsy: {connection: orca-server, buildRef: refs/heads/main}\nenvironmentRecipes: [{id: test}]\n",
    )
    settings_fixture(directory, env)
    let source : Json = {
      "sourceControlAi": {
        "actions": {
          "branchName": { "agentArgs": "--opaque fixture-profile-private" },
          "conversationName": {},
        },
      },
    }
    @fs.write_file(directory + "/orca-host/settings.json", source.stringify())
    @fs.write_file(directory + "/fail-settings-transport", "")
    let (status, _, errors) = invoke("create", env, directory)
    assert_true(status != 0)
    assert_false(errors.contains("fixture-profile-private"))
    assert_false(errors.contains("fixture-wire-secret"))
    let events = fixture_events(directory)
    let failures = events.filter(event => {
      field(event, "stage") == Some(Json::string("orca-settings")) &&
      field(event, "status") == Some(Json::string("failed"))
    })
    assert_eq(failures.length(), 1)
    let failure = failures[0]
    assert_eq(field(failure, "phase"), Some(Json::string("remote/process")))
    assert_eq(field(failure, "exitCode"), Some(Json::number(255)))
    assert_eq(field(failure, "detailsTruncated"), Some(Json::boolean(true)))
    let detail = required(failure, "errorMessage")
    assert_true(detail.contains("settings transport refused"), msg=detail)
    assert_false(detail.contains("fixture-profile-private"), msg=detail)
    assert_false(detail.contains("fixture-wire-secret"), msg=detail)
  })
}

