async test "diagnostic lock contention is bounded and loss is recorded after recovery" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  let root = directory + "/.local/state/orca-env-devsy"
  @fs.mkdir(root, recursive=true)
  let lock = @fs.open(
    root + "/events.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
  )
  defer lock.close()
  assert_true(lock.try_lock(Exclusive))
  @async.with_timeout(10000, async fn() {
    @async.with_task_group(async fn(group) {
      let (reader, stderr) = @process.read_from_process()
      defer reader.close()
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      let child = @process.spawn(
        group,
        integration_binary(),
        ["status", "--provider", "fixture-provider"],
        extra_env=env,
        stdout=sink,
        stderr~,
      )
      let mut errors = ""
      while !errors.contains(
              "diagnostic recording is unavailable (lock_busy, phase=lock)",
            ) {
        guard reader.read_some(max_len=4096) is Some(chunk) else {
          fail("diagnostic warning was not emitted: " + errors)
        }
        errors += @utf8.decode_lossy(chunk)
      }
      lock.unlock()
      assert_eq(child.wait(), 0, msg=errors)
    })
  })
  let events = fixture_events(directory)
  let markers = events.filter(event => {
    field(event, "errorType") == Some(Json::string("lock_busy"))
  })
  assert_eq(markers.length(), 1)
  assert_eq(field(markers[0], "completeness"), Some(Json::string("partial")))
}

