async test "recover failure respects the workspace recording opt out" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  @fs.write_file(
    directory + "/orca.yaml",
    "devsy: {connection: ssh, buildRef: refs/heads/main}\nenvironmentRecipes: [{id: test}]\n",
  )
  let (created, output, errors) = invoke("create", env, directory)
  assert_eq(created, 0, msg=errors)
  let creation = @json.parse(output)
  let state = field(creation, "userData").unwrap()
  let worker = required(state, "tunnelDirectory")
  let workspace_id = required(state, "workspaceId")
  let environment = @json.parse(
    @fs.read_file(worker + "/environment.json").text(),
  )
  set_field(environment, "ORCA_ENV_DEVSY_RECORDING", Json::string("0"))
  @fs.write_file(worker + "/environment.json", environment.stringify())
  @fs.write_file(directory + "/fail-status", "")
  let before = fixture_events(directory).length()
  let (status, _, errors) = invoke("recover", env, directory)
  assert_true(status != 0)
  assert_true(errors.contains(workspace_id + ": failed"), msg=errors)
  let events = fixture_events(directory)
  for index in before..<events.length() {
    assert_false(
      field(events[index], "stage") == Some(Json::string("recover")) &&
      field(events[index], "status") == Some(Json::string("failed")) &&
      field(events[index], "tunnelDirectory") == Some(Json::string(worker)),
    )
  }
  @fs.remove(directory + "/fail-status")
  let payload : Json = { "schemaVersion": 1, "recipeResult": creation }
  let (destroyed, _, destroy_error) = invoke(
    "destroy",
    env,
    directory,
    payload~,
  )
  assert_eq(destroyed, 0, msg=destroy_error)
}

