///|
priv struct Progress {
  stage : String
  operations : Map[String, UInt64]
  builds : Map[String, String]
  secrets : Array[String]
  recording : Bool
  mut phase_count : Int32
  mut private_key : Bool
  mut classic_build : Bool
  recent : Array[String]
  failures : Array[String]
  mut details_truncated : Bool
}

///|
fn sensitive_name(name : String) -> Bool {
  let name = name.to_lower()
  [
    "password", "passwd", "token", "secret", "api_key", "apikey", "auth", "credential",
    "private_key", "access_key", "cookie", "fnox_age_key",
  ]
  .iter()
  .any(marker => name.contains(marker))
}

///|
fn Progress::new(
  stage : String,
  environment? : Map[String, String],
  recording_override? : Bool,
) -> Progress {
  let secrets = []
  for name, value in environment.unwrap_or(@env.get_env_vars()) {
    if sensitive_name(name) && value != "" {
      secrets.push(value)
      // Multiline credentials must also be masked in line-oriented output.
      for part in value.split("\n") {
        if part.trim() != "" {
          secrets.push(part.to_owned())
        }
      }
    }
  }
  secrets.sort_by((a, b) => b.length().compare(a.length()))
  {
    stage,
    operations: {},
    builds: {},
    secrets,
    recording: recording_override.unwrap_or(
      environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
      Some("0"),
    ),
    phase_count: 0,
    private_key: false,
    classic_build: false,
    recent: [],
    failures: [],
    details_truncated: false,
  }
}

///|
fn terminal_text(text : String) -> String? {
  let output = @buffer.Buffer(size_hint=256)
  let mut state = 0
  for c in text.iter() {
    match state {
      0 =>
        if c == '\u001b' {
          state = 1
        } else if c.to_int() < 32 && c != '\t' {
          return None
        } else {
          output.write_char_utf8(c)
        }
      1 =>
        if c == '[' {
          state = 2
        } else if c == ']' {
          state = 3
        } else {
          return None
        }
      2 => if c >= '@' && c <= '~' { state = 0 }
      3 => if c == '\u0007' { state = 0 } else if c == '\u001b' { state = 4 }
      _ => if c == '\\' { state = 0 } else { state = 3 }
    }
  }
  if state != 0 {
    None
  } else {
    Some(@utf8.decode_lossy(output.to_bytes()))
  }
}

///|
fn Progress::remember(
  self : Progress,
  message : String,
  warning~ : Bool,
) -> Unit {
  let lines = if warning { self.failures } else { self.recent }
  if lines.last() == Some(message) {
    return
  }
  if lines.length() == 8 {
    ignore(lines.remove(0))
    self.details_truncated = true
  }
  lines.push(message)
}

///|
fn Progress::failure_detail(self : Progress) -> String {
  let lines = self.failures +
    self.recent.filter(line => !self.failures.contains(line))
  let detail = if lines.is_empty() {
    "no readable error message from subprocess"
  } else {
    lines.join("\n")
  }
  detail +
  (if self.details_truncated {
    "\n[error details incomplete or truncated]"
  } else {
    ""
  })
}

///|
async fn Progress::status(self : Progress, event : Json) -> Unit {
  guard field(event, "phase") is Some(Json::String(phase)) &&
    phase_label(phase) is Some(label) &&
    field(event, "state") is Some(Json::String(state)) &&
    ["started", "succeeded", "failed", "skipped"].contains(state) else {
    return
  }
  if self.phase_count < 128 {
    self.phase_count += 1
    save_diagnostic(
      self.stage,
      state,
      phase~,
      error_type?=if state == "failed" { Some("backend_phase") } else { None },
      recording=self.recording,
    )
  } else if self.phase_count == 128 {
    self.phase_count += 1
    save_diagnostic(
      self.stage,
      "diagnostics-truncated",
      error_type="phase_limit",
      recording=self.recording,
    )
  }
  let key = ["pipeline", "operationId", "phase", "step"]
    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
    .join(":")
  if state == "started" {
    if self.operations.length() >= 256 {
      self.operations.clear()
    }
    self.operations.set(key, @env.now())
    progress_message(label + ": running…")
  } else {
    let duration = match field(event, "durationMs") {
      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
        Some(seconds(value.to_uint64()))
      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
    }
    self.operations.remove(key)
    let timing = duration.map(value => value + ", ").unwrap_or("") +
      "elapsed " +
      seconds(@env.now() - progress_started)
    progress_message(
      label +
      ": " +
      (if state == "succeeded" { "done" } else { state }) +
      " (" +
      timing +
      ")",
    )
  }
}

///|
fn classic_build_step(text : String) -> Bool {
  guard text.has_prefix("Step ") &&
    text[5:].split_once("/") is Some((step, rest)) &&
    rest.split_once(" ") is Some((total, detail)) else {
    return false
  }
  step.length() > 0 &&
  total.length() > 0 &&
  step.iter().all(c => c >= '0' && c <= '9') &&
  total.iter().all(c => c >= '0' && c <= '9') &&
  detail.trim().has_prefix(":")
}

///|
async fn Progress::message(
  self : Progress,
  text : String,
  debug~ : Bool,
  warning~ : Bool,
  emit~ : Bool = true,
) -> Unit {
  for line in text.split("\n") {
    let text = line.trim().to_owned()
    if text == "" {
      continue
    }
    guard self.safe_message(text) is Some(safe) else {
      self.details_truncated = true
      continue
    }
    if !debug || warning {
      self.remember(safe, warning~)
    }
    if !emit {
      continue
    }
    if safe.has_prefix("#") {
      guard safe.split_once(" ") is Some((id, rest)) &&
        id.length() > 1 &&
        id[1:].iter().all(c => c >= '0' && c <= '9') else {
        continue
      }
      let detail = rest.trim().to_owned()
      guard detail.has_prefix("[") ||
        detail.has_prefix("DONE") ||
        detail.has_prefix("ERROR") ||
        detail.has_prefix("CACHED") else {
        continue
      }
      if detail.has_prefix("ERROR") && debug && !warning {
        self.remember(safe, warning=true)
      }
      if self.builds.get(id.to_owned()) == Some(detail) {
        continue
      }
      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
        self.builds.set(id.to_owned(), detail)
      }
      progress_message("Build " + id.to_owned() + ": " + detail)
    } else if classic_build_step(safe) {
      // Classic RUN output has no prefix. Only its own completion marker
      // ends this mode; phase events on another pipe can arrive ahead of it.
      self.classic_build = true
      progress_message("Build " + safe)
    } else if safe.has_prefix("Successfully built ") ||
      safe.has_prefix("Successfully tagged ") {
      self.classic_build = false
      progress_message("Build: " + safe)
    } else if self.classic_build && !warning {
      continue
    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
      progress_message(self.stage + ": " + safe)
    } else if !debug && safe.has_prefix("[credential") {
      progress_message(self.stage + ": " + safe)
    }
  }
}

///|
async fn Progress::line(
  self : Progress,
  line : String,
  statuses~ : Bool,
  messages~ : Bool,
) -> Unit {
  if line.trim() == "" {
    return
  }
  let event = @json.parse(line) catch { _ => Json::null() }
  if field(event, "kind") == Some(Json::string("status")) {
    if field(event, "state") == Some(Json::string("failed")) &&
      field(event, "error") is Some(error) {
      for name in ["message", "hint"] {
        if field(error, name) is Some(Json::String(text)) {
          self.message(
            text,
            debug=false,
            warning=true,
            emit=messages || statuses,
          )
        }
      }
    }
    if statuses || messages {
      self.status(event)
    }
    return
  }
  // Result envelopes and arbitrary structured responses are never log text.
  if field(event, "kind") == Some(Json::string("result")) {
    return
  }
  if event is Json::Object(_) {
    let kind = field(event, "kind")
    guard kind == None ||
      kind == Some(Json::string("log")) ||
      kind == Some(Json::string("error")) else {
      return
    }
    let message = match field(event, "msg") {
      Some(value) => Some(value)
      None => field(event, "message")
    }
    guard message is Some(Json::String(text)) else { return }
    let level = field(event, "level")
    self.message(
      text,
      debug=level == Some(Json::string("debug")) ||
        level == Some(Json::string("trace")),
      warning=kind == Some(Json::string("error")) ||
        level == Some(Json::string("warn")) ||
        level == Some(Json::string("error")),
      emit=messages || (statuses && kind != None),
    )
  } else {
    if event != Json::null() {
      return
    }
    // Malformed JSON and binary output are not a safe free-text fallback.
    let text = line.trim().to_owned()
    if text.has_prefix("{") || text.has_prefix("[") {
      self.details_truncated = true
      return
    }
    self.message(
      text,
      debug=text.contains(" DEBUG ") ||
        text.contains(" TRACE ") ||
        text.has_prefix("DEBUG ") ||
        text.has_prefix("TRACE "),
      warning=text.contains(" WARN ") ||
        text.contains(" ERROR ") ||
        text.has_prefix("WARN ") ||
        text.has_prefix("ERROR "),
      emit=messages,
    )
  }
}

///|
async fn Progress::read_output(
  self : Progress,
  reader : @process.ReadFromProcess,
  capture~ : Bool,
  statuses~ : Bool = false,
  messages~ : Bool = false,
  raw_messages~ : Bool = false,
) -> String {
  let output = @buffer.Buffer(size_hint=4096)
  let pending = @buffer.Buffer(size_hint=4096)
  let mut oversized = false
  let mut tail = ""
  while reader.read_some(max_len=4096) is Some(chunk) {
    if capture {
      output.write_bytes(chunk)
    } else {
      tail += @utf8.decode_lossy(chunk)
      if tail.length() > 8192 {
        tail = tail[tail.length() - 8192:].to_owned()
      }
    }
    for byte in chunk {
      if byte == b'\n' || byte == b'\r' {
        if !oversized && pending.length() > 0 {
          let line = @utf8.decode(pending.to_bytes()) catch {
            _ => {
              self.details_truncated = true
              ""
            }
          }
          if raw_messages {
            self.message(line, debug=false, warning=true, emit=false)
          } else {
            self.line(line, statuses~, messages~)
          }
        }
        pending.reset()
        oversized = false
      } else if !oversized {
        if pending.length() == 65536 {
          pending.reset()
          oversized = true
          self.details_truncated = true
        } else {
          pending.write_byte(byte)
        }
      }
    }
  }
  if !oversized && pending.length() > 0 {
    let line = @utf8.decode(pending.to_bytes()) catch {
      _ => {
        self.details_truncated = true
        ""
      }
    }
    if raw_messages {
      self.message(line, debug=false, warning=true, emit=false)
    } else {
      self.line(line, statuses~, messages~)
    }
  }
  if capture {
    @utf8.decode(output.to_bytes())
  } else {
    tail
  }
}

///|
priv struct DiagnosticRecordingHealth {
  mut dropped : Int32
  mut first_dropped : UInt64
  mut last_dropped : UInt64
  mut reason : String
  mut phase : String
  mut os_errno : Int32?
  mut warned : Bool
}

///|
let diagnostic_recording_health : DiagnosticRecordingHealth = {
  dropped: 0,
  first_dropped: 0,
  last_dropped: 0,
  reason: "",
  phase: "",
  os_errno: None,
  warned: false,
}

///|
async fn diagnostic_recording_failed(
  reason : String,
  phase~ : String = "",
  os_errno? : Int32,
) -> Unit {
  let now = @env.now()
  if diagnostic_recording_health.dropped == 0 {
    diagnostic_recording_health.first_dropped = now
  }
  diagnostic_recording_health.dropped += 1
  diagnostic_recording_health.last_dropped = now
  diagnostic_recording_health.reason = reason
  diagnostic_recording_health.phase = phase
  diagnostic_recording_health.os_errno = os_errno
  if !diagnostic_recording_health.warned {
    diagnostic_recording_health.warned = true
    @async.with_timeout(10, async fn() {
      @stdio.stderr.write(
        "orca-env-devsy: warning: diagnostic recording is unavailable (" +
        reason +
        (if phase == "" { "" } else { ", phase=" + phase }) +
        os_errno.map(code => ", errno=" + code.to_string()).unwrap_or("") +
        ")\n",
      )
    }) catch {
      _ => ()
    }
  }
}

///|
fn diagnostic_recording_event(status : String, reason : String) -> Json {
  {
    "stage": "diagnostic-recording",
    "status": status,
    "errorType": reason,
    "completeness": "partial",
    "time": @env.now().to_string(),
    "runId": recording_run_id,
    "adapterVersion": version,
  }
}

///|
fn diagnostic_json(
  value : Json,
  environment : Map[String, String],
  truncated : Ref[Bool],
  depth : Int32,
) -> Json {
  if depth >= 64 {
    truncated.val = true
    return Json::string("[nested evidence omitted]")
  }
  match value {
    Json::Object(values) => {
      let result = Json::empty_object()
      for name, item in values {
        let key = name.to_lower().replace_all(old="_", new="")
        set_field(
          result,
          name,
          if credential_field(name) || key == "pairingcode" {
            Json::string("[redacted]")
          } else {
            diagnostic_json(item, environment, truncated, depth + 1)
          },
        )
      }
      result
    }
    Json::Array(values) =>
      Json::array(
        values.map(item => {
          diagnostic_json(item, environment, truncated, depth + 1)
        }),
      )
    Json::String(text) => {
      let safe = diagnostic_text(text, environment~)
      if safe.has_suffix("\n[error details incomplete or truncated]") {
        truncated.val = true
      }
      Json::string(safe)
    }
    _ => value
  }
}

///|
async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
  let length = if size > 262144L { 262144 } else { size.to_int() }
  let bytes = FixedArray::make(length, b'\x00')
  let read = file.read_at(bytes, position=size - length.to_int64())
  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
  let lines = text.split("\n").to_array()
  let kept = FixedArray::make(lines.length(), false)
  let mut remaining = 65536
  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
    if i == 0 && size > length.to_int64() {
      continue
    }
    let length = lines[i].length() + 1
    if length <= remaining {
      kept[i] = true
      remaining -= length
    }
  }
  remaining = 65536
  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
    if kept[i] || (i == 0 && size > length.to_int64()) {
      continue
    }
    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
    let failed = field(event, "errorType") is Some(_) ||
      (match field(event, "status") {
        Some(Json::String(status)) =>
          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
            status,
          )
        _ => false
      })
    let length = lines[i].length() + 1
    if failed && length <= remaining {
      kept[i] = true
      remaining -= length
    }
  }
  let result = @buffer.Buffer(size_hint=131072)
  for i in 0..<lines.length() {
    if kept[i] {
      result.write_string_utf8(lines[i].to_owned() + "\n")
    }
  }
  @utf8.decode_lossy(result.to_bytes())
}

///|
async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  timeout_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
  error_message? : String,
  details_truncated~ : Bool = false,
  tunnel_directory? : String,
  expected_workspace_uid? : String,
  observed_workspace_uid? : String,
  evidence? : Json,
  recording? : Bool,
) -> Unit {
  if !recording.unwrap_or(
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
    ) {
    return
  }
  let mut failure_phase = "directory"
  @async.with_timeout(50, async fn() {
    let dir = adapter_state_home()
    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
    @fs.chmod(dir, 0o700)
    let path = dir + "/events.jsonl"
    let lock_path = dir + "/events.lock"
    failure_phase = "lock"
    if @fs.exists(lock_path) &&
      @fs.kind(lock_path, follow_symlink=false) != @fs.FileKind::Regular {
      diagnostic_recording_failed("invalid_lock", phase=failure_phase)
      return
    }
    let lock = @fs.open(
      lock_path,
      mode=ReadWrite,
      create_mode=OpenOrCreate,
      permission=0o600,
    )
    defer lock.close()
    if !lock.try_lock(Exclusive) {
      diagnostic_recording_failed("lock_busy", phase=failure_phase)
      return
    }
    failure_phase = "inspect"
    if @fs.exists(path) &&
      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
      diagnostic_recording_failed("invalid_store", phase=failure_phase)
      return
    }
    let event : Json = {
      "stage": stage,
      "status": status,
      "time": @env.now().to_string(),
      "runId": recording_run_id,
      "adapterVersion": version,
    }
    if create_recording.attempt > 0 {
      set_field(
        event,
        "createAttempt",
        Json::number(create_recording.attempt.to_double()),
      )
      set_field(event, "createPhase", Json::string(create_recording.phase))
    }
    if error_message is Some(message) {
      set_field(event, "errorMessage", Json::string(message))
      set_field(
        event,
        "detailsTruncated",
        Json::boolean(
          details_truncated ||
          message.has_suffix("\n[error details incomplete or truncated]"),
        ),
      )
    }
    if tunnel_directory is Some(directory) {
      set_field(event, "tunnelDirectory", Json::string(directory))
    }
    for
      pair in [
        ("expectedWorkspaceUid", expected_workspace_uid),
        ("observedWorkspaceUid", observed_workspace_uid),
      ] {
      if pair.1 is Some(value) {
        set_field(event, pair.0, Json::string(redact_credentials(value)))
      }
    }
    let evidence_truncated : Ref[Bool] = { val: false, }
    let environment = @env.get_env_vars()
    if source is Some(evidence) {
      set_field(
        event,
        "source",
        diagnostic_json(evidence.to_json(), environment, evidence_truncated, 0),
      )
    }
