///|
fn diagnostic_error(
  error : Error,
  environment? : Map[String, String],
) -> String {
  let (message, omitted) = match error {
    AdapterError(detail) => (detail, false)
    InvalidConfig(detail) => (detail, false)
    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
    @json.InvalidNumber(position, _) =>
      (
        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
        true,
      )
    _ => (error.to_string(), false)
  }
  diagnostic_text(message, environment?, omitted~)
}

///|
fn diagnostic_text(
  message : String,
  environment? : Map[String, String],
  omitted~ : Bool = false,
  protected_values? : Array[String],
  incomplete_final_line~ : Bool = false,
) -> String {
  let progress = Progress::new("diagnostic-error", environment?)
  if protected_values is Some(values) {
    for value in values {
      if value != "" {
        progress.secrets.push(value)
      }
    }
    progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
  }
  let lines = []
  let mut incomplete = omitted
  let source_lines = message.split("\n").to_array()
  for index in 0..<source_lines.length() {
    let line = source_lines[index]
    if lines.length() == 8 {
      incomplete = true
      ignore(lines.remove(1))
    }
    let truncated = line.length() > 1024
    let bounded = if truncated {
      incomplete = true
      line[:1024].to_owned()
    } else {
      line.to_owned()
    }
    let bounded = if truncated ||
      (incomplete_final_line && index == source_lines.length() - 1) {
      diagnostic_partial_secret(bounded, progress.secrets)
    } else {
      bounded
    }
    match progress.safe_message(bounded) {
      Some(safe) => lines.push(safe)
      None => {
        incomplete = true
        lines.push("[unavailable]")
      }
    }
  }
  if (incomplete || progress.details_truncated) &&
    lines.last() != Some("[error details incomplete or truncated]") {
    lines.push("[error details incomplete or truncated]")
  }
  lines.join("\n")
}

///|
fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
  let chars = text.iter().to_array()
  let mut boundary = chars.length()
  for secret in secrets {
    let value = secret.iter().to_array()
    if value.length() == 0 || text.has_suffix(secret) {
      continue
    }
    let limit = if value.length() - 1 < boundary {
      value.length() - 1
    } else {
      boundary
    }
    if limit == 0 {
      continue
    }
    let prefixes = FixedArray::make(limit, 0)
    let mut matched = 0
    for index in 1..<limit {
      while matched > 0 && value[matched] != value[index] {
        matched = prefixes[matched - 1]
      }
      if value[matched] == value[index] {
        matched += 1
      }
      prefixes[index] = matched
    }
    matched = 0
    for index in 0..<boundary {
      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
        matched = prefixes[matched - 1]
      }
      if matched < limit && value[matched] == chars[index] {
        matched += 1
      }
    }
    boundary -= matched
  }
  if boundary == chars.length() {
    text
  } else {
    character_text(chars, 0, boundary) + "[redacted]"
  }
}

///|
priv struct DiagnosticProtectedValues {
  values : Array[String]
  mut visited : Int32
  mut incomplete : Bool
}

///|
fn diagnostic_protected_values(
  value : Json,
  result : DiagnosticProtectedValues,
) -> Unit {
  if result.visited >= 4096 || result.values.length() >= 512 {
    result.incomplete = true
    return
  }
  result.visited += 1
  match value {
    Json::String(text) if text != "" => {
      result.values.push(text)
      for line in text.split("\n") {
        if line != "" && line.length() < text.length() {
          if result.values.length() >= 512 {
            result.incomplete = true
            return
          }
          result.values.push(line.to_owned())
        }
        for word in line.split(" ") {
          for part in word.split("=") {
            if part == "" || part.length() >= text.length() {
              continue
            }
            if result.values.length() >= 512 {
              result.incomplete = true
              return
            }
            result.values.push(part.to_owned())
          }
        }
      }
      let escaped = Json::string(text).stringify()
      if escaped.length() > 2 {
        let encoded = escaped[1:escaped.length() - 1].to_owned()
        if encoded != "" && encoded != text {
          if result.values.length() >= 512 {
            result.incomplete = true
            return
          }
          result.values.push(encoded)
        }
      }
    }
    Json::Array(values) =>
      for item in values {
        diagnostic_protected_values(item, result)
      }
    Json::Object(values) =>
      for _, item in values {
        diagnostic_protected_values(item, result)
      }
    _ => ()
  }
}

///|
fn diagnostic_output(
  output : Bytes,
  environment : Map[String, String],
  protected_input? : String,
  omitted~ : Bool = false,
) -> String? {
  if output.length() == 0 {
    return None
  }
  let safeguards : DiagnosticProtectedValues = {
    values: [],
    visited: 0,
    incomplete: false,
  }
  if protected_input is Some(input) {
    diagnostic_protected_values(@json.parse(input), safeguards) catch {
      _ => safeguards.incomplete = true
    }
  }
  if safeguards.incomplete {
    return Some(
      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
    )
  }
  let limit = if output.length() > 8192 { 8192 } else { output.length() }
  let incomplete = omitted || limit < output.length()
  Some(
    diagnostic_text(
      @utf8.decode_lossy(output[:limit]),
      environment~,
      omitted=incomplete,
      protected_values=safeguards.values,
      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
    ),
  )
}

///|
async fn diagnostic_capture(
  reader : @process.ReadFromProcess,
  limit : Int32,
) -> (Bytes, Bool) {
  let output = @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 })
  let mut truncated = false
  while reader.read_some(max_len=4096) is Some(chunk) {
    let remaining = limit - output.length()
    let count = if chunk.length() < remaining {
      chunk.length()
    } else {
      remaining
    }
    if count > 0 {
      output.write_bytes(chunk[:count])
    }
    if count < chunk.length() {
      truncated = true
    }
  }
///|
fn credential_field(name : String) -> Bool {
  let name = name
    .trim_start(chars="-")
    .to_owned()
    .to_lower()
    .replace_all(old="-", new="_")
  [
    "auth", "authorization", "proxy_authorization", "cookie", "set_cookie", "password",
    "passwd", "token", "access_token", "accesstoken", "refresh_token", "refreshtoken",
    "id_token", "api_key", "apikey", "x_api_key", "credential", "credentials", "secret",
    "client_secret", "clientsecret", "private_key", "privatekey", "aws_secret_access_key",
    "azure_storage_key", "docker_auth_config", "signature", "sig", "x_amz_signature",
    "x_amz_security_token", "x_goog_signature",
  ].contains(name) ||
  [
    "_auth", "_password", "_passwd", "_token", "_secret", "_api_key", "_private_key",
  ]
  .iter()
  .any(suffix => name.has_suffix(suffix))
}

///|
fn credential_word(c : Char) -> Bool {
  (c >= 'a' && c <= 'z') ||
  (c >= 'A' && c <= 'Z') ||
  (c >= '0' && c <= '9') ||
  c == '_' ||
  c == '-'
}

///|
fn credential_space(c : Char) -> Bool {
  c == ' ' || c == '\t'
}

///|
fn credential_end(c : Char) -> Bool {
  credential_space(c) ||
  [',', ';', '&', '#', '"', '\'', '}', ']', '<', '>'].contains(c)
}

///|
fn character_text(chars : Array[Char], start : Int32, end : Int32) -> String {
  let buffer = @buffer.Buffer(size_hint=end - start)
  for i in start..<end {
    buffer.write_char_utf8(chars[i])
  }
  @utf8.decode_lossy(buffer.to_bytes())
}

///|
fn credential_hex(c : Char) -> Int32? {
  match c {
    '0'..<='9' => Some(c.to_int() - '0'.to_int())
    'a'..<='f' => Some(c.to_int() - 'a'.to_int() + 10)
    'A'..<='F' => Some(c.to_int() - 'A'.to_int() + 10)
    _ => None
  }
}

///|
fn credential_parameter(name : String) -> String {
  let chars = name.iter().to_array()
  let buffer = @buffer.Buffer(size_hint=name.length())
  let mut i = 0
  while i < chars.length() {
    if chars[i] == '%' &&
      i + 2 < chars.length() &&
      credential_hex(chars[i + 1]) is Some(hi) &&
      credential_hex(chars[i + 2]) is Some(lo) {
      buffer.write_char_utf8((hi * 16 + lo).unsafe_to_char())
      i += 3
    } else {
      buffer.write_char_utf8(chars[i])
      i += 1
    }
  }
  @utf8.decode_lossy(buffer.to_bytes())
}

///|
fn redact_credentials(text : String) -> String {
  let chars = text.iter().to_array()
  let buffer = @buffer.Buffer(size_hint=text.length())
  let mut i = 0
  let mut url = false
  while i < chars.length() {
    if credential_space(chars[i]) || ['"', '\''].contains(chars[i]) {
      url = false
    }
    if chars[i] == ':' &&
      i + 2 < chars.length() &&
      chars[i + 1] == '/' &&
      chars[i + 2] == '/' {
      url = true
      buffer.write_string_utf8("://")
      i += 3
      let mut end = i
      let mut user_end = None
      while end < chars.length() &&
            !credential_end(chars[end]) &&
            !['/', '?'].contains(chars[end]) {
        if chars[end] == '@' {
          user_end = Some(end)
        }
        end += 1
      }
      if user_end is Some(end) {
        buffer.write_string_utf8("[redacted]@")
        i = end + 1
      }
      continue
    }
    if url && ['?', '&'].contains(chars[i]) {
      let start = i
      i += 1
      while i < chars.length() && !credential_end(chars[i]) && chars[i] != '=' {
        i += 1
      }
      let name = credential_parameter(character_text(chars, start + 1, i))
      if i < chars.length() && chars[i] == '=' {
        i += 1
        buffer.write_string_utf8(character_text(chars, start, i))
        if credential_field(name) || name.to_lower() == "key" {
          while i < chars.length() && !credential_end(chars[i]) {
            i += 1
          }
          buffer.write_string_utf8("[redacted]")
          if i < chars.length() &&
            chars[i] == ']' &&
            i >= 9 &&
            character_text(chars, i - 9, i + 1) == "[redacted]" {
            i += 1
          }
        }
      } else {
        buffer.write_string_utf8(character_text(chars, start, i))
      }
      continue
    }
    if credential_word(chars[i]) && (i == 0 || !credential_word(chars[i - 1])) {
      let start = i
      let mut end = i
      while end < chars.length() && credential_word(chars[end]) {
        end += 1
      }
      let word = character_text(chars, start, end)
      let lower = word.to_lower()
      if [
          "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "sk-", "age-secret-key-",
        ]
        .iter()
        .any(prefix => lower.has_prefix(prefix)) ||
        (word.has_prefix("eyJ") && end < chars.length() && chars[end] == '.') {
        while end < chars.length() && !credential_end(chars[end]) {
          end += 1
        }
        buffer.write_string_utf8("[redacted]")
        i = end
        continue
      }
      let mut separator = end
      if separator < chars.length() && ['"', '\''].contains(chars[separator]) {
        separator += 1
      }
      while separator < chars.length() && credential_space(chars[separator]) {
        separator += 1
      }
      let mut previous = start
      while previous > 0 && credential_space(chars[previous - 1]) {
        previous -= 1
      }
      let field_start = previous == 0 ||
        [';', ',', '{', '"', '\'', '?', '&'].contains(chars[previous - 1])
      let option = word.has_prefix("--")
      let prose_credential = ["credential", "credentials"].contains(lower) &&
        !field_start
      let assignment = separator < chars.length() &&
        (
          chars[separator] == '=' ||
          (chars[separator] == ':' && !prose_credential)
        )
      if credential_field(word) && (assignment || (option && separator > end)) {
        let mut value = if assignment { separator + 1 } else { separator }
        while value < chars.length() && credential_space(chars[value]) {
          value += 1
        }
        buffer.write_string_utf8(character_text(chars, start, value))
        let quoted_key = start > 0 &&
          end < chars.length() &&
          ['"', '\''].contains(chars[start - 1]) &&
          chars[start - 1] == chars[end]
        if ["cookie", "set-cookie", "--cookie"].contains(lower) && !quoted_key {
          buffer.write_string_utf8("[redacted]")
          i = chars.length()
        } else if value + 10 <= chars.length() &&
          character_text(chars, value, value + 10) == "[redacted]" {
          buffer.write_string_utf8("[redacted]")
          i = value + 10
        } else if value < chars.length() && ['"', '\''].contains(chars[value]) {
          let quote = chars[value]
          buffer.write_char_utf8(quote)
          value += 1
          while value < chars.length() && chars[value] != quote {
            if chars[value] == '\\' && value + 1 < chars.length() {
              value += 1
            }
            value += 1
          }
          buffer.write_string_utf8("[redacted]")
          i = value
        } else {
          let mut value_end = value
          while value_end < chars.length() && !credential_end(chars[value_end]) {
            value_end += 1
          }
          let scheme = character_text(chars, value, value_end).to_lower()
          if scheme == "bearer" || scheme == "basic" {
            while value_end < chars.length() &&
                  credential_space(chars[value_end]) {
              value_end += 1
            }
            buffer.write_string_utf8(character_text(chars, value, value_end))
            value = value_end
            while value_end < chars.length() &&
                  !credential_end(chars[value_end]) {
              value_end += 1
            }
          }
          if value + 10 <= chars.length() &&
            character_text(chars, value, value + 10) == "[redacted]" {
            value_end = value + 10
          }
          if value_end > value {
            buffer.write_string_utf8("[redacted]")
          }
          i = value_end
        }
        continue
      }
      buffer.write_string_utf8(word)
      i = end
      continue
    }
    buffer.write_char_utf8(chars[i])
    i += 1
  }
  @utf8.decode_lossy(buffer.to_bytes())
}

///|
fn Progress::safe_message(self : Progress, text : String) -> String? {
  guard terminal_text(text) is Some(text) else { return None }
  let lower = text.to_lower()
  if lower.contains("-----begin ") && lower.contains("private key-----") {
    self.private_key = REDACTED ")
    return Some("[private key redacted]")
  }
  if self.private_key {
    if lower.contains("-----end ") && lower.contains("private key-----") {
      self.private_key = false
    }
    return None
  }
  let mut safe = text
  for secret in self.secrets {
    safe = if secret.length() < 4 {
      redact_short_secret(safe, secret)
    } else {
      safe.replace_all(old=secret, new="[redacted]")
    }
  }
  safe = redact_credentials(safe)
  if safe.length() > 1024 {
    safe = safe[:1024].to_owned() + "… [truncated]"
    self.details_truncated = true
  }
  Some(safe)
}

///|
fn redact_short_secret(text : String, secret : String) -> String {
  let chars = text.iter().to_array()
  let value = secret.iter().to_array()
  let result = @buffer.Buffer(size_hint=text.length())
  let mut i = 0
  while i < chars.length() {
    let mut matches = value.length() > 0 && i + value.length() <= chars.length()
    if matches {
      for j in 0..<value.length() {
        if chars[i + j] != value[j] {
          matches = false
          break
        }
      }
    }
    if matches &&
      (i == 0 || !credential_word(chars[i - 1])) &&
      (
        i + value.length() == chars.length() ||
        !credential_word(chars[i + value.length()])
      ) {
      result.write_string_utf8("[redacted]")
      i += value.length()
    } else {
      result.write_char_utf8(chars[i])
      i += 1
    }
  }
  @utf8.decode_lossy(result.to_bytes())
}

///|
priv suberror SettingsProcessError {
  SettingsProcessError(String, String, Int32, String?)
}

///|
#borrow(buffer)
extern "C" fn process_executable(
  pid : Int32,
  buffer : Bytes,
  capacity : Int32,
) -> Int32 = "orca_process_executable"

///|
async fn settings_executable(pid : Int32) -> String {
  if @async.platform is Linux {
    return @fs.realpath("/proc/\{pid}/exe")
  }
  let buffer = Bytes::make(4096, 0)
  let length = process_executable(pid, buffer, buffer.length())
  guard length > 0 && length < buffer.length() else {
    raise AdapterError("Cannot locate the running host Orca executable")
  }
  @utf8.decode(buffer[:length])
}

///|
fn settings_parent(path : String) -> String {
  let parts = path.split("/").to_array()
  parts[:parts.length() - 1].join("/")
}

///|
async fn host_orca_location() -> (String, String, String) {
  let home = environment("HOME")
  let user_data = @env.get_env_var("ORCA_USER_DATA_PATH")
    .filter(p => p != "")
    .unwrap_or(
      if @async.platform is MacOS {
        home + "/Library/Application Support/orca"
      } else {
        @env.get_env_var("XDG_CONFIG_HOME")
        .filter(p => p != "")
        .unwrap_or(home + "/.config") +
        "/orca"
      },
    )
  let metadata = @json.parse(
    @fs.read_file(user_data + "/orca-runtime.json").text(),
  )
  let pid = match field(metadata, "pid") {
    Some(Json::Number(value, ..)) if value > 1 && value == value.trunc() =>
      value.to_int()
    _ => raise AdapterError("Invalid host Orca runtime PID")
  }
  let executables = [settings_executable(pid)]
  if @async.platform is Linux {
    let args = @fs.read_file("/proc/\{pid}/cmdline")
      .text()
      .split("\u0000")
      .to_array()
    for i = 0; i + 1 < args.length(); i = i + 1 {
      if args[i] == "--spawner-exec-path" {
        executables.push(args[i + 1].to_owned())
      }
    }
  }
  for executable in executables {
    let parent = settings_parent(executable)
    for
      resources in [
        parent + "/resources",
        settings_parent(parent) + "/Resources",
      ] {
      if @fs.exists(
          resources +
          "/app.asar.unpacked/out/main/persistence/profile-state/profile-state-domain-reader.js",
        ) {
        return (executable, resources, user_data)
      }
    }
  }
  raise AdapterError("Cannot locate the running host Orca resources")
}

///|
async fn host_orca_settings() -> String {
  let (executable, resources, user_data) = host_orca_location()
  let env = @env.get_env_vars()
  env.set("ELECTRON_RUN_AS_NODE", "1")
  env.remove("NODE_OPTIONS")
  env.remove("NODE_REPL_EXTERNAL_MODULE")
  settings_process(
    executable,
    ["-e", orca_settings_script(), "--", "export", resources, user_data],
    environment=env,
  )
}

///|
async fn settings_process(
  program : String,
  args : Array[String],
  environment~ : Map[String, String],
  input? : String,
) -> String {
  let (stdin, writer) = @process.write_to_process()
  defer writer.close()
  @async.with_task_group(async fn(group) {
    let output = group.spawn(async fn() {
      diagnostic_process_output(
        program,
        args,
        environment~,
        stdin~,
        stdout_limit=4194304,
        stderr_limit=8192,
      )
    })
    if input is Some(value) {
      writer.write(value)
    }
    writer.close()
    let (status, stdout, stdout_truncated, stderr, stderr_truncated) = output.wait()
    guard status == 0 else {
      let mut phase = "process"
      let mut code = "process_exit"
      let mut detail = diagnostic_output(
        stderr,
        environment,
        protected_input?=input,
        omitted=stderr_truncated,
      )
      if !stderr_truncated {
        try {
          let error = @json.parse(@utf8.decode(stderr))
          let reported_phase = required(error, "phase")
          let reported_code = required(error, "code")
          if [
              "load", "read", "normalize", "input", "profile", "write", "verify",
            ].contains(reported_phase) &&
            ["EACCES", "ENOENT", "EBUSY", "ENOSPC", "INCOMPATIBLE", "INVALID"].contains(
              reported_code,
            ) {
            phase = reported_phase
            code = reported_code
            let kind = match field(error, "kind") {
              Some(Json::String(value)) if [
                  "Error", "TypeError", "SyntaxError", "ReferenceError", "RangeError",
                  "AssertionError", "URIError",
                ].contains(value) => Some(value)
              _ => None
            }
            let native_code = match field(error, "nativeCode") {
              Some(Json::String(value)) if value.length() > 0 &&
                value.length() <= 64 &&
                value
                .iter()
                .all(c => {
                  (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
                }) => Some(value)
              _ => None
            }
            detail = if kind is Some(kind) {
              Some(
                kind +
                native_code.map(value => " (" + value + ")").unwrap_or(""),
              )
            } else {
              None
            }
          }
        } catch {
          _ => ()
        }
      }
      raise SettingsProcessError(phase, code, status, detail)
    }
    guard !stdout_truncated else {
      raise AdapterError("Orca settings result exceeds size limit")
  )
  progress_message("orca-settings: done")
}

