///|
fn missing_shallow_commit(output : String, commit : String) -> Bool {
  output
  .split("\n")
  .iter()
  .any(line => {
    if line.trim() == "" {
      return false
    }
    let event = @json.parse(line.to_owned())
    let missing = match
      field(field(event, "error").unwrap_or(Json::null()), "message") {
      Some(Json::String(message)) =>
        message.contains("Could not parse object '" + commit + "'")
      _ => false
    }
    field(event, "kind") == Some(Json::string("status")) &&
    field(event, "phase") == Some(Json::string("cloning_repository")) &&
    field(event, "state") == Some(Json::string("failed")) &&
    missing
  }) catch {
    _ => false
  }
}

///|
fn workspace_recording(state : Json) -> Bool {
  match field(state, "diagnosticRecording") {
    Some(value) if value == Json::boolean(false) => return false
    Some(value) if value == Json::boolean(true) => return true
    _ => ()
  }
  match field(state, "executionEnvironment") {
    Some(environment) =>
      field(environment, "ORCA_ENV_DEVSY_RECORDING") != Some(Json::string("0"))
    None => @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0")
  }
}

///|
async fn snapshot_workspace_recording(state : Json, directory : String) -> Unit {
  let enabled = if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
    false
  } else {
    try {
      let environment = @json.parse(
        @fs.read_file(directory + "/environment.json").text(),
      )
      match environment {
        Json::Object(values) =>
          match values.get("ORCA_ENV_DEVSY_RECORDING") {
            None => true
            Some(Json::String(value)) => value != "0"
            _ => false
          }
        _ => false
      }
    } catch {
      error => if @async.is_being_cancelled() { raise error } else { false }
    }
  }
  set_field(state, "diagnosticRecording", Json::boolean(enabled))
}

///|
fn operation_recording(state : Json) -> Bool {
  @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0") &&
  workspace_recording(state)
}

///|
fn state_recording(state : Json) -> Bool {
  match @env.args() {
    [_, "--supervisor" | "--ssh-proxy", ..] => workspace_recording(state)
    _ => operation_recording(state)
  }
}
}

///|
fn monitor_delay(attempt : Int32) -> Int32 {
  match attempt {
    0 => 15000
    1 => 30000
    2 => 60000
    3 => 120000
    _ => 300000
  }
}

///|
async fn monitor_wait(directory : String, delay : Int32) -> Unit {
  for elapsed = 0
      elapsed < delay && @fs.exists(directory + "/enabled")
      elapsed = elapsed + 100 {
    if @fs.exists(directory + "/probe-request") ||
      @fs.exists(directory + "/paused") {
      return
    }
    @async.sleep(100)
  }
}

///|
async fn recover_connection(
  state : Json,
  restart~ : Bool = false,
  deadline? : UInt64,
  saved_environment~ : Bool = false,
) -> Unit {
  let operation = connection_operation_lock(state, validate=false)
  defer operation.close()
  let directory = required(state, "tunnelDirectory")
  if saved_environment {
    let environment = @json.parse(
      @fs.read_file(directory + "/environment.json").text(),
    )
    guard environment is Json::Object(_) else {
      raise AdapterError("Invalid saved workspace environment")
    }
    set_field(state, "executionEnvironment", environment)
  }
  let deadline = deadline.unwrap_or(connection_deadline())
  connection_timeout(deadline, async fn() {
    let current = workspace(state)
    guard current is Some(current) &&
      field(current, "uid") == field(state, "workspaceUid") else {
      save_diagnostic(
        "recover",
        "ownership-error",
        tunnel_directory=directory,
        recording=state_recording(state),
      )
      raise AdapterError("Tunnel workspace ownership changed")
    }
    let status = workspace_status(state)
    save_diagnostic(
      "recover-workspace",
      status,
      tunnel_directory=directory,
      recording=state_recording(state),
    )
    match status {
      "Running" => ()
      "Stopped" => {
        progress_message(
          required(state, "workspaceId") +
          ": workspace stopped; recovery skipped",
        )
        return
      }
      "Busy" =>
        raise AdapterError(
          "Workspace is Busy; wait for workspace up to finish before recover",
        )
      _ => raise AdapterError("Workspace is missing")
    }
    @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
    let lock = @fs.open(
      directory + "/recovery.lock",
      mode=ReadWrite,
      create_mode=OpenOrCreate,
      permission=0o600,
    )
    defer lock.close()
    @async.with_timeout(30000, async fn() {
      while !lock.try_lock(Exclusive) {
        @async.sleep(100)
      }
    })
    let port = match field(state, "localPort") {
      Some(Json::Number(value, ..)) if value >= 1 &&
        value <= 65535 &&
        value == value.to_int().to_double() => Some(value.to_int())
      None if field(state, "connection") == Some(Json::string("ssh")) => None
      _ => raise AdapterError("Invalid saved tunnel port")
    }
    save_diagnostic(
      "recover-worker",
      if restart {
        "restart"
      } else if worker_alive(directory) {
        "reuse"
      } else {
        "restore"
      },
      tunnel_directory=directory,
      recording=state_recording(state),
    )
    ensure_ssh_worker(state, port, deadline~, restart~)
    if required(state, "connection") == "orca-server" {
      ignore(recover_server(state))
    }
    save_diagnostic(
      "recover",
      "success",
      tunnel_directory=directory,
      recording=state_recording(state),
    )
  })
}

