fn diagnostic_json(
  value : Json,
  environment : Map[String, String],
  truncated : Ref[Bool],
  depth : Int32,
) -> Json {
  if depth >= 64 {
    truncated.val = true
    return Json::string("[nested evidence omitted]")
  }
  match value {
    Json::Object(values) => {
      let result = Json::empty_object()
      for name, item in values {
        let key = name.to_lower().replace_all(old="_", new="")
        set_field(
          result,
          name,
          if credential_field(name) || key == "pairingcode" {
            Json::string("[redacted]")
          } else {
            diagnostic_json(item, environment, truncated, depth + 1)
          },
        )
      }
      result
    }
    Json::Array(values) =>
      Json::array(
        values.map(item => {
          diagnostic_json(item, environment, truncated, depth + 1)
        }),
      )
    Json::String(text) => {
      let safe = diagnostic_text(text, environment~)
      if safe.has_suffix("\n[error details incomplete or truncated]") {
        truncated.val = true
      }
      Json::string(safe)
    }
    _ => value
  }
}

