///|
test "diagnostic output protects short and multiline values at truncation boundaries" {
  let environment : Map[String, String] = { "PRIVATE_TOKEN": "abcdefgh" }
  let detail = diagnostic_output(
    @utf8.encode("host rejected xy and abc and pq"),
    environment,
    protected_input="{\"short\":\"xy\",\"multiline\":\"abc\\npq\"}",
  ).unwrap()
  assert_true(detail.contains("host rejected"), msg=detail)
  assert_false(detail.contains("xy"), msg=detail)
  assert_false(detail.contains("abc"), msg=detail)
  assert_false(detail.contains("pq"), msg=detail)
  let short = diagnostic_output(
    @utf8.encode("authentication failed for branch a"),
    environment,
    protected_input="{\"branchPrefixCustom\":\"a\"}",
  ).unwrap()
  assert_true(short.contains("authentication failed"), msg=short)
  assert_true(short.contains("branch [redacted]"), msg=short)
  let long_line = diagnostic_output(
    @utf8.encode("connection refused: " + "z".repeat(9000)),
    environment,
  ).unwrap()
  assert_true(long_line.contains("connection refused"), msg=long_line)
  assert_true(long_line.contains("incomplete or truncated"), msg=long_line)
  let truncated = diagnostic_output(
    @utf8.encode("first line\npartial abc"),
    environment,
    omitted=true,
  ).unwrap()
  assert_true(truncated.contains("first line"), msg=truncated)
  assert_false(truncated.contains("partial abc"), msg=truncated)
  assert_true(truncated.contains("incomplete or truncated"), msg=truncated)
  let oversized = diagnostic_text("cause " + "a".repeat(9000), environment={
    "PRIVATE_TOKEN": "a".repeat(9000),
  })
  assert_false(oversized.contains("a".repeat(100)), msg=oversized)
  assert_true(oversized.contains("incomplete or truncated"), msg=oversized)
}

