///|
priv struct DiagnosticRecordingHealth {
  mut dropped : Int32
  mut first_dropped : UInt64
  mut last_dropped : UInt64
  mut reason : String
  mut phase : String
  mut os_errno : Int32?
  mut warned : Bool
}

///|
let diagnostic_recording_health : DiagnosticRecordingHealth = {
  dropped: 0,
  first_dropped: 0,
  last_dropped: 0,
  reason: "",
  phase: "",
  os_errno: None,
  warned: false,
}

///|
let diagnostic_workspace_environments : Map[String, Map[String, String]] = Map([])

///|
async fn diagnostic_recording_failed(
  reason : String,
  phase~ : String = "",
  os_errno? : Int32,
) -> Unit {
  let now = @env.now()
  if diagnostic_recording_health.dropped == 0 {
    diagnostic_recording_health.first_dropped = now
  }
  diagnostic_recording_health.dropped += 1
  diagnostic_recording_health.last_dropped = now
  diagnostic_recording_health.reason = reason
  diagnostic_recording_health.phase = phase
  diagnostic_recording_health.os_errno = os_errno
  if !diagnostic_recording_health.warned {
    diagnostic_recording_health.warned = true
    @async.with_timeout(10, async fn() {
      @stdio.stderr.write(
        "orca-env-devsy: warning: diagnostic recording is unavailable (" +
        reason +
        (if phase == "" { "" } else { ", phase=" + phase }) +
        os_errno.map(code => ", errno=" + code.to_string()).unwrap_or("") +
        ")\n",
      )
    }) catch {
      _ => ()
    }
  }
}

///|
fn diagnostic_recording_event(status : String, reason : String) -> Json {
  {
    "stage": "diagnostic-recording",
    "status": status,
    "errorType": reason,
    "completeness": "partial",
    "time": @env.now().to_string(),
    "runId": recording_run_id,
    "adapterVersion": version,
  }
}

///|
fn diagnostic_json(
  value : Json,
  environment : Map[String, String],
  protected_secrets : Array[String],
  truncated : Ref[Bool],
  depth : Int32,
) -> Json {
  if depth >= 64 {
    truncated.val = true
    return Json::string("[nested evidence omitted]")
  }
  match value {
    Json::Object(values) => {
      let result = Json::empty_object()
      for name, item in values {
        let key = name.to_lower().replace_all(old="_", new="")
        let safe_name = diagnostic_text(name, environment~, protected_secrets~)
        if field(result, safe_name) is Some(_) {
          truncated.val = true
          continue
        }
        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
          truncated.val = true
        }
        set_field(
          result,
          safe_name,
          if credential_field(name) || key == "pairingcode" {
            Json::string("[redacted]")
          } else {
            diagnostic_json(
              item,
              environment,
              protected_secrets,
              truncated,
              depth + 1,
            )
          },
        )
      }
      result
    }
    Json::Array(values) =>
      Json::array(
        values.map(item => {
          diagnostic_json(
            item,
            environment,
            protected_secrets,
            truncated,
            depth + 1,
          )
        }),
      )
    Json::String(text) => {
      let safe = diagnostic_text(text, environment~, protected_secrets~)
      if safe.has_suffix("\n[error details incomplete or truncated]") {
        truncated.val = true
      }
      Json::string(safe)
    }
    _ => value
  }
}

///|
async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
  let length = if size > 262144L { 262144 } else { size.to_int() }
  let bytes = FixedArray::make(length, b'\x00')
  let read = file.read_at(bytes, position=size - length.to_int64())
  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
  let lines = text.split("\n").to_array()
  let kept = FixedArray::make(lines.length(), false)
  let mut remaining = 65536
  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
    if i == 0 && size > length.to_int64() {
      continue
    }
    let length = lines[i].length() + 1
    if length <= remaining {
      kept[i] = true
      remaining -= length
    }
  }
  remaining = 65536
  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
    if kept[i] || (i == 0 && size > length.to_int64()) {
      continue
    }
    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
    let failed = field(event, "errorType") is Some(_) ||
      (match field(event, "status") {
        Some(Json::String(status)) =>
          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
            status,
          )
        _ => false
      })
    let length = lines[i].length() + 1
    if failed && length <= remaining {
      kept[i] = true
      remaining -= length
    }
  }
  let result = @buffer.Buffer(size_hint=131072)
  for i in 0..<lines.length() {
    if kept[i] {
      result.write_string_utf8(lines[i].to_owned() + "\n")
    }
  }
  @utf8.decode_lossy(result.to_bytes())
}

