priv struct DiagnosticRecordingHealth {
  mut dropped : Int32
  mut first_dropped : UInt64
  mut last_dropped : UInt64
  mut reason : String
  mut phase : String
  mut os_errno : Int32?
  mut warned : Bool
}

///|
let diagnostic_recording_health : DiagnosticRecordingHealth = {
  dropped: 0,
  first_dropped: 0,
  last_dropped: 0,
  reason: "",
  phase: "",
  os_errno: None,
  warned: false,
}

