async test "diagnostic lock contention is bounded and loss is recorded after recovery" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  @fs.write_file(
    directory + "/orca.yaml",
    "devsy: {connection: ssh, buildRef: refs/heads/main}\nenvironmentRecipes: [{id: test}]\n",
  )
  @fs.rename(directory + "/bin/devsy", directory + "/bin/devsy-original")
  let wrapper =
    #|#!/bin/sh
    #|case "$*" in *'context list'*) touch "$HOME/context-waiting"; while test ! -f "$HOME/release-context"; do sleep 0.01; done ;; esac
    #|exec "$HOME/bin/devsy-original" "$@"
  @fs.write_file(directory + "/bin/devsy", wrapper + "\n", permission=0o700)
  let root = directory + "/.local/state/orca-env-devsy"
  @fs.mkdir(root, recursive=true)
  let lock = @fs.open(
    root + "/events.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
  )
  defer lock.close()
  assert_true(lock.try_lock(Exclusive))
  let output : Ref[String] = { val: "", }
  @async.with_timeout(15000, async fn() {
    @async.with_task_group(async fn(group) {
      let (reader, stderr) = @process.read_from_process()
      defer reader.close()
      let (stdout_reader, stdout) = @process.read_from_process()
      defer stdout_reader.close()
      let child = @process.spawn(
        group,
        integration_binary(),
        ["recipe", "create"],
        extra_env=env,
        stdout~,
        stderr~,
      )
      let captured = group.spawn(async fn() {
        let capture = DiagnosticCapture::new(65536)
        capture.read(stdout_reader)
        (capture.output.to_bytes(), capture.truncated)
      })
      let mut errors = ""
      while !errors.contains(
              "diagnostic recording is unavailable (lock_busy, phase=lock)",
            ) {
        guard reader.read_some(max_len=4096) is Some(chunk) else {
          fail("diagnostic warning was not emitted: " + errors)
        }
        errors += @utf8.decode_lossy(chunk)
      }
      group.spawn_bg(no_wait=true, async fn() {
        while reader.read_some(max_len=4096) is Some(_) {

        }
      })
      @async.with_timeout(5000, async fn() {
        while !@fs.exists(directory + "/context-waiting") {
          @async.sleep(10)
        }
      })
      lock.unlock()
      @fs.write_file(directory + "/release-context", "")
      assert_eq(child.wait(), 0, msg=errors)
      let (bytes, truncated) = captured.wait()
      assert_false(truncated)
      output.val = @utf8.decode(bytes)
    })
  })
  let events = fixture_events(directory)
  let markers = events.filter(event => {
    field(event, "errorType") == Some(Json::string("lock_busy"))
  })
  assert_true(markers.length() > 0)
  for marker in markers {
    assert_eq(field(marker, "completeness"), Some(Json::string("partial")))
    assert_eq(field(marker, "phase"), Some(Json::string("lock")))
    assert_true(
      field(marker, "droppedEvents") is Some(Json::Number(n, ..)) && n > 0,
    )
  }
  let payload : Json = {
    "schemaVersion": 1,
    "recipeResult": @json.parse(output.val),
  }
  let (destroyed, _, destroy_error) = invoke(
    "destroy",
    env,
    directory,
    payload~,
  )
  assert_eq(destroyed, 0, msg=destroy_error)
}

