async test "settings helper distinguishes load errors without profile contents" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  settings_fixture(directory, env)
  let host = directory + "/orca-host"
  let reader = host +
    "/resources/app.asar.unpacked/out/main/persistence/profile-state/profile-state-domain-reader.js"
  let original_reader = @fs.read_file(reader).text()
  for kind in ["module", "syntax", "missing-one", "missing-two"] {
    @fs.write_file(
      reader,
      if kind == "module" {
        "throw Object.assign(new Error('fixture-profile-private'), {code:'MODULE_NOT_FOUND'});"
      } else if kind == "syntax" {
        "throw new SyntaxError('fixture-profile-private');"
      } else {
        "require('./" + kind + ".js');"
      },
    )
    let failure = try {
      ignore(
        settings_process(
          host + "/orca-ide",
          [
            "-e",
            orca_settings_script(),
            "--",
            "export",
            host + "/resources",
            host,
          ],
          environment=env,
        ),
      )
      None
    } catch {
      SettingsProcessError(phase, code, status, detail) =>
        Some((phase, code, status, detail))
      error => raise error
    }
    guard failure is Some((phase, code, status, detail)) else {
      fail("settings helper unexpectedly succeeded")
    }
    assert_eq(phase, "load")
    assert_eq(code, "INVALID")
    assert_eq(status, 1)
    let detail = detail.unwrap_or("")
    assert_true(
      detail.contains(
        if kind != "syntax" {
          "MODULE_NOT_FOUND"
        } else {
          "SyntaxError"
        },
      ),
      msg=detail,
    )
    if kind.has_prefix("missing-") {
      assert_true(detail.contains(kind + ".js"), msg=detail)
      assert_true(detail.contains("profile-state-domain-reader.js"), msg=detail)
    }
    assert_false(detail.contains("fixture-profile-private"))
  }
  @fs.write_file(reader, original_reader)
  let shared = host + "/resources/app.asar.unpacked/out/shared/"
  let first = shared + "source-control-ai-settings.js"
  let second = shared + "auto-rename-branch-from-work-settings.js"
  let original_first = @fs.read_file(first).text()
  let original_second = @fs.read_file(second).text()
  for target in [first, second] {
    @fs.write_file(first, original_first)
    @fs.write_file(second, original_second)
    @fs.write_file(target, "throw new SyntaxError('fixture-profile-private');")
    let failure = try {
      ignore(
        settings_process(
          host + "/orca-ide",
          [
            "-e",
            orca_settings_script(),
            "--",
            "export",
            host + "/resources",
            host,
          ],
          environment=env,
        ),
      @fs.remove(saved + "/enabled")
      assert_eq(child.wait(), 0)
    })
  })
