          fail("expected recording warning: " + errors)
        }
        errors += @utf8.decode_lossy(chunk)
      }
      lock.unlock()
      group.spawn_bg(no_wait=true, async fn() {
        while reader.read_some(max_len=4096) is Some(_) {}
      })
      assert_true(child.wait() != 0)
