async test "diagnostic buffer retains the terminal failure when full" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  @fs.write_file(
    directory + "/orca.yaml",
    "devsy: {connection: ssh, buildRef: refs/heads/main}\nenvironmentRecipes: [{id: test}]\n",
  )
  @fs.rename(directory + "/bin/devsy", directory + "/bin/devsy-original")
  let wrapper =
    #|#!/bin/sh
    #|case "$*" in
    #| *'workspace up'*)
    #|   i=0
    #|   while test "$i" -lt 80; do
    #|     printf '%s\n' '{"kind":"status","phase":"building_image","state":"failed"}'
    #|     i=$((i+1))
    #|   done
    #|   printf 'fixture-buffer-terminal-cause\n' >&2
    #|   exit 9 ;;
    #|esac
    #|exec "$HOME/bin/devsy-original" "$@"
  @fs.write_file(directory + "/bin/devsy", wrapper + "\n", permission=0o700)
  let root = directory + "/.local/state/orca-env-devsy"
  @fs.mkdir(root, recursive=true)
  let lock = @fs.open(root + "/events.lock", mode=ReadWrite, create_mode=OpenOrCreate)
  defer lock.close()
  assert_true(lock.try_lock(Exclusive))
  @async.with_timeout(15000, async fn() {
    @async.with_task_group(async fn(group) {
      let stdout = @process.redirect_to_file("/dev/null", shared=true)
      defer stdout.close()
      let stderr = @process.redirect_to_file(directory + "/buffer-stderr", shared=true)
      defer stderr.close()
      let child = @process.spawn(
        group,
        integration_binary(),
        ["recipe", "create"],
        extra_env=env,
        stdout~,
        stderr~,
      )
      idle_wait_for(async fn() {
        @fs.read_file(directory + "/buffer-stderr").text().contains("workspace-create: failed (exit 9)")
      })
      lock.unlock()
      assert_true(child.wait() != 0)
    })
  })
  let events = fixture_events(directory)
  assert_true(events.iter().any(event => {
    field(event, "stage") == Some(Json::string("diagnostic-recording")) &&
    field(event, "errorType") == Some(Json::string("buffer_full")) &&
    field(event, "droppedEvents") is Some(Json::Number(count, ..)) && count > 0
  }))
  assert_true(events.iter().any(event => {
    field(event, "stage") == Some(Json::string("create")) &&
    field(event, "status") == Some(Json::string("failed")) &&
    field(event, "errorMessage") is Some(Json::String(message)) &&
    message.contains("fixture-buffer-terminal-cause")
  }))
}
