                value.length() > 0 &&
                value.length() <= 1024 &&
                diagnostic_output(
                  @utf8.encode(value),
                  environment,
                  protected_input?=input,
                )
                is Some(safe) {
                detail = Some(
                  detail.unwrap_or("Error") + " " + name + "=" + safe,
                )
              }
            }
