cat >> src/diagnostics_wbtest.mbt <<'EOF'

///|
async test "disabled recording skips special diagnostic files" {
  for name in ["environment.json", "pairing-code"] {
    let (directory, env, state) = idle_fixture(3600000)
    defer cleanup_fixture(directory)
    let worker = required(state, "tunnelDirectory")
    @fs.remove(worker + "/idle-enabled")
    @fs.write_file(directory + "/stopped", "")
    @fs.remove(worker + "/" + name)
    assert_eq(@process.run("mkfifo", [worker + "/" + name]), 0)
    env.set("ORCA_ENV_DEVSY_RECORDING", "0")
    let (code, result, errors) = @async.with_timeout(3000, async fn() {
      bulk_fixture_run(["status", "--provider", "fixture-provider"], env)
    })
    assert_eq(code, 0, msg=errors)
    assert_eq(field(bulk_first(result), "vmStatus"), Some(Json::string("Stopped")))
    assert_false(errors.contains("diagnostic recording is unavailable"), msg=errors)
  }
}

///|
async test "unrecognized stderr formats retain their redacted causes" {
  let environment : Map[String, String] = {
    "PATH": "/usr/bin:/bin",
    "SERVICE_ACCESS_TOKEN": "fixture-unstructured-secret",
  }
  for text in [
    "[ERROR] provider temporarily unavailable fixture-unstructured-secret",
    "{\"error\":\"provider temporarily unavailable fixture-unstructured-secret\"}",
  ] {
    let (status, _, detail) = command_result(
      "/bin/sh", ["-c", "printf '%s\\n' " + quote(text) + " >&2; exit 7"],
      "fixture-stderr", environment~, recording_override=false,
    )
    assert_eq(status, 7)
    assert_true(detail.contains("provider temporarily unavailable"), msg=detail)
    assert_false(detail.contains("fixture-unstructured-secret"), msg=detail)
  }
}
EOF
