  defer cleanup_fixture(directory)
  settings_fixture(directory, env)
  env.set("SYNTHETIC_ACCESS_TOKEN", "fixture-settings-secret")
  let host = directory + "/orca-host"
  let reader = host +
    "/resources/app.asar.unpacked/out/main/persistence/profile-state/profile-state-domain-reader.js"
  for target in ["one.json", "two.json"] {
    @fs.write_file(
      reader,
      "throw Object.assign(new Error('cannot open " + target + " token=fixture-settings-secret'), {code:'ENOENT',path:'/profile/" + target + "'});",
    )
    let detail = try {
      ignore(settings_process(
        host + "/orca-ide",
        ["-e", orca_settings_script(), "--", "export", host + "/resources", host],
        environment=env,
      ))
      fail("settings helper unexpectedly succeeded")
    } catch {
      SettingsProcessError(_, _, _, Some(detail)) => detail
      error => raise error
    }
    assert_true(detail.contains("/profile/" + target), msg=detail)
    assert_true(detail.contains("cannot open " + target), msg=detail)
    assert_false(detail.contains("fixture-settings-secret"), msg=detail)
  }
  for target in ["missingAlpha", "missingBeta"] {
    @fs.write_file(reader, "throw new TypeError('" + target + " is not a function');")
    let detail = try {
      ignore(settings_process(
        host + "/orca-ide",
        ["-e", orca_settings_script(), "--", "export", host + "/resources", host],
        environment=env,
      ))
      fail("settings helper unexpectedly succeeded")
    } catch {
      SettingsProcessError(_, _, _, Some(detail)) => detail
      error => raise error
    }
    assert_true(detail.contains(target + " is not a function"), msg=detail)
  }
}
