    protected_input="{\"branchPrefixCustom\":\"a\"}",
  ).unwrap()
  assert_true(short.contains("authentication failed"), msg=short)
  assert_true(short.contains("branch a"), msg=short)
  let credential = diagnostic_output(
    @utf8.encode("authentication failed prefixQ7suffix"),
    environment,
    protected_input="{\"nested\":{\"access_token\":\"Q7\"}}",
