///|
fn Progress::remember(
  self : Progress,
  message : String,
  warning~ : Bool,
) -> Unit {
  let lines = if warning { self.failures } else { self.recent }
  if lines.last() == Some(message) {
    return
  }
  if lines.length() == 8 {
    ignore(lines.remove(0))
    self.details_truncated = true
  }
  lines.push(message)
}

///|
fn Progress::failure_detail(self : Progress) -> String {
  let lines = self.failures +
    self.recent.filter(line => !self.failures.contains(line))
  let detail = if lines.is_empty() {
    "no readable error message from subprocess"
  } else {
    lines.join("\n")
  }
  detail +
  (if self.details_truncated {
    "\n[error details incomplete or truncated]"
  } else {
    ""
  })
}

///|
async fn Progress::status(self : Progress, event : Json) -> Unit {
  guard field(event, "phase") is Some(Json::String(phase)) &&
    phase_label(phase) is Some(label) &&
    field(event, "state") is Some(Json::String(state)) &&
    ["started", "succeeded", "failed", "skipped"].contains(state) else {
    return
  }
  if self.phase_count < 128 {
    self.phase_count += 1
    save_diagnostic(
      self.stage,
      state,
      phase~,
      error_type?=if state == "failed" { Some("backend_phase") } else { None },
      evidence?=self.context,
      protected_secrets=self.secrets,
      recording=self.recording,
    )
  } else if self.phase_count == 128 {
    self.phase_count += 1
    save_diagnostic(
      self.stage,
      "diagnostics-truncated",
      error_type="phase_limit",
      evidence?=self.context,
      protected_secrets=self.secrets,
      recording=self.recording,
    )
  }
  let key = ["pipeline", "operationId", "phase", "step"]
    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
    .join(":")
  if state == "started" {
    if self.operations.length() >= 256 {
      self.operations.clear()
    }
    self.operations.set(key, @env.now())
    progress_message(label + ": running…")
  } else {
    let duration = match field(event, "durationMs") {
      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
        Some(seconds(value.to_uint64()))
          diagnostic_text(name, environment~, protected_secrets~)
        }
        if field(result, safe_name) is Some(_) {
          truncated.val = true
          continue
        }
        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
          truncated.val = true
        }
        set_field(
          result,
          safe_name,
          if credential_field(name) || key == "pairingcode" {
            Json::string("[redacted]")
          } else if stable_activity &&
            name == "activity" &&
            (
              item == Json::string("idle") ||
              item == Json::string("active") ||
              item == Json::string("unknown")
            ) {
            item
          } else {
            diagnostic_json(
              item,
              environment,
              protected_secrets,
              truncated,
              depth + 1,
              stable_activity~,
            )
          },
        )
      }
      result
    }
    Json::Array(values) =>
      Json::array(
        values.map(item => {
          diagnostic_json(
            item,
            environment,
            protected_secrets,
            truncated,
            depth + 1,
            stable_activity~,
          )
        }),
      )
    Json::String(text) => {
      let safe = diagnostic_text(text, environment~, protected_secrets~)
      if safe.has_suffix("\n[error details incomplete or truncated]") {
        truncated.val = true
      }
      Json::string(safe)
    }
    _ => value
  }
}

///|
async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
  let length = if size > 262144L { 262144 } else { size.to_int() }
  let bytes = FixedArray::make(length, b'\x00')
  let read = file.read_at(bytes, position=size - length.to_int64())
  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
  let lines = text.split("\n").to_array()
  let kept = FixedArray::make(lines.length(), false)
  let mut remaining = 65536
  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
    if i == 0 && size > length.to_int64() {
      continue
    }
    let length = lines[i].length() + 1
    if length <= remaining {
      kept[i] = true
      remaining -= length
    }
  }
  remaining = 65536
  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
    if kept[i] || (i == 0 && size > length.to_int64()) {
      continue
    }
    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
    let failed = field(event, "errorType") is Some(_) ||
      (match field(event, "status") {
        Some(Json::String(status)) =>
          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
            status,
          )
        _ => false
      })
    let length = lines[i].length() + 1
    if failed && length <= remaining {
      kept[i] = true
      remaining -= length
    }
  }
  let result = @buffer.Buffer(size_hint=131072)
  for i in 0..<lines.length() {
    if kept[i] {
      result.write_string_utf8(lines[i].to_owned() + "\n")
    }
  }
  @utf8.decode_lossy(result.to_bytes())
}

///|
async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  timeout_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
  error_message? : String,
  details_truncated~ : Bool = false,
  tunnel_directory? : String,
  expected_workspace_uid? : String,
  observed_workspace_uid? : String,
  evidence? : Json,
  evidence_incomplete~ : Bool = false,
  evidence_stable_activity~ : Bool = false,
  recording? : Bool,
  environment? : Map[String, String],
  protected_secrets? : Array[String],
) -> Unit {
  if !recording.unwrap_or(
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
    ) {
    return
  }
  let event_time = @env.now()
  let event : Json = {
    "stage": stage,
    "status": status,
    "time": event_time.to_string(),
    "runId": recording_run_id,
    "adapterVersion": version,
  }
  if create_recording.attempt > 0 {
    set_field(
      event,
      "createAttempt",
      Json::number(create_recording.attempt.to_double()),
    )
    set_field(event, "createPhase", Json::string(create_recording.phase))
  }
  let process_environment = @env.get_env_vars()
  let secrets = [] + protected_secrets.unwrap_or([])
  if environment is Some(environment) {
    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
      secrets.push(secret)
    }
  }

