  defer cleanup_fixture(directory)
  let root = directory + "/.local/state/orca-env-devsy"
  @fs.mkdir(root, recursive=true)
  @fs.write_file(root + "/events.jsonl", "{\"stage\":\"old\"}\n".repeat(20000))
  let warnings : Ref[Int32] = { val: 0, }
  @async.with_task_group(async fn(group) {
    let pending = []
    for _ in 0..<8 {
      pending.push(
        group.spawn(async fn() {
          let (status, _, errors) = bulk_fixture_run(
            ["status", "--provider", "fixture-provider"],
            env,
          )
          assert_eq(status, 0, msg=errors)
          if errors.contains("diagnostic recording is unavailable") {
            warnings.val += 1
          }
        }),
      )
    }
    for task in pending {
      task.wait()
    }
  })
  let events = fixture_events(directory)
  let starts = events.filter(event => {
    field(event, "stage") == Some(Json::string("bulk")) &&
    field(event, "status") == Some(Json::string("started"))
  })
  let ends = events.filter(event => {
    field(event, "stage") == Some(Json::string("bulk")) &&
    field(event, "status") == Some(Json::string("success"))
  })
  assert_true(starts.length() + warnings.val >= 8)
  assert_true(ends.length() + warnings.val >= 8)
  assert_eq(
    events
    .filter(event => {
      field(event, "errorType") == Some(Json::string("retention_limit"))
    })
    .length(),
    1,
  )
  let ids : Map[String, Bool] = Map([])
  for start in starts {
    ids.set(required(start, "runId"), true)
  }
  assert_eq(ids.length(), starts.length())
  let mut unmatched = 0
  for end in ends {
    if !ids.contains(required(end, "runId")) {
      unmatched += 1
    }
  }
  assert_true(unmatched <= warnings.val)
}

///|
async test "invalid command options retain a redacted failure unless recording is disabled" {
  for command in ["status", "update"] {
    for enabled in [true, false] {
        ["idle", "active", "unknown"].contains(required(value, "activity")) else {
        raise AdapterError("Invalid activity response")
      }
      value
    })
  })
}

///|
fn activity_command(state : Json) -> String {
  (if field(state, "orcaVolume") is Some(_) {
    "ORCA_USER_DATA_PATH=/worktrees/.orca "
  } else {
    ""
  }) +
  "ELECTRON_RUN_AS_NODE=1 \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" -e " +
  quote(activity_probe_source())
}

///|
fn unknown_activity(reason : String) -> Json {
  { "activity": "unknown", "reason": redact_credentials(reason) }
}

///|
async fn bulk_context(state : Json) -> String {
  let selection = @json.parse(state.stringify())
  if selection is Json::Object(fields) {
    fields.remove("context")
  }
  let contexts = @json.parse(
    devsy(
      selection,
      ["--result-format", "json", "context", "list"],
      "bulk-context",
    ),
  )
  guard contexts is Json::Array(items) else {
    raise AdapterError("Invalid context list")
  }
  let selected = items.filter(item => {
    field(item, "default") == Some(Json::boolean(true))
  })
  guard selected.length() == 1 else {
    raise AdapterError("No unique effective Devsy context")
  }
  required(selected[0], "name")
}

///|
async fn bulk_identity(state : Json, provider : String) -> (Bool, Bool) {
  let current = workspace(state)
  match current {
    None => (true, false)
    Some(value) => {
      let actual_provider = field(value, "provider").bind(p => field(p, "name"))
      let in_scope = actual_provider == Some(Json::string(provider)) &&
        field(value, "context")
        .map(c => c == field(state, "context").unwrap())
        .unwrap_or(true)
      if !in_scope {
        let secrets = saved_workspace_secrets(state)
        if secrets is None {
          suppress_workspace_recording(state)
        }
        save_diagnostic(
          "bulk-workspace",
          "excluded",
          evidence={
            "id": required(state, "workspaceId"),
            "context": required(state, "context"),
            "observedContext": field(value, "context").unwrap_or(Json::null()),
            "requestedProvider": provider,
            "observedProvider": actual_provider.unwrap_or(Json::null()),
            "reason": "outside_scope",
          },
          protected_secrets?=secrets,
          environment=workspace_environment(state),
          recording=state_recording(state) && secrets is Some(_),
        )
      }
      (
        in_scope,
        in_scope && field(value, "uid") == field(state, "workspaceUid"),
      )
    }

