  set_field(saved, "ORCA_ENV_DEVSY_RECORDING", Json::string("0"))
  @fs.write_file(worker + "/environment.json", saved.stringify())
  let before = fixture_events(directory).length()
  let (status, result, errors) = bulk_fixture_run(
    ["status", "--provider", "fixture-provider"],
    env,
