///|
async fn invoke(
  mode : String,
  env : Map[String, String],
  directory : String,
  payload? : Json,
) -> (Int32, String, String) {
  if mode == "create" &&
    @fs.exists(directory + "/orca.yaml") &&
    @fs.read_file(directory + "/orca.yaml").text().contains("orca-server") {
    settings_fixture(directory, env)
  }
  let executable = integration_binary()
  let input = if payload is Some(value) {
    @fs.write_file(directory + "/stdin.json", value.stringify())
    Some(@process.redirect_from_file(directory + "/stdin.json"))
  } else {
    None
  }
  let (status, stdout, stderr) = @process.collect_output(
    executable,
    if (mode == "recover" || mode == "restart") && payload is None {
      [mode]
    } else {
      ["recipe", mode]
    },
    extra_env=env,
    stdin?=input,
  )
  let diagnostics = if status != 0 { fixture_process_errors(env) } else { "" }
  (status, stdout.text(), stderr.text() + diagnostics)
}

///|
async fn fixture_process_errors(env : Map[String, String]) -> String {
  let diagnostics = []
  try {
    let path = env.get("XDG_STATE_HOME").unwrap() +
      "/orca-env-devsy/events.jsonl"
    for line in @fs.read_file(path).text().split("\n") {
      if line == "" {
        continue
      }
      let event = @json.parse(line.to_owned())
      if field(event, "status") != Some(Json::string("process-error")) {
        continue
      }
      let safe = Json::empty_object()
      for name in ["process_os", "process_utf8", "process_api"] {
        if field(event, "errorType") == Some(Json::string(name)) {
          set_field(safe, "errorType", Json::string(name))
        }
      }
      for name in ["read"] {
        if field(event, "phase") == Some(Json::string(name)) {
          set_field(safe, "phase", Json::string(name))
        }
      }
      if field(event, "osErrno") is Some(Json::Number(code, ..)) &&
        code > 0 &&
        code < 4096 &&
        code == code.to_int().to_double() {
        set_field(safe, "osErrno", Json::number(code))
      }
      diagnostics.push(safe.stringify())
    }
  } catch {
    _ => ()
  }

///|
fn credential_field(name : String) -> Bool {
  let chars = name.trim_start(chars="-").iter().to_array()
  let normalized = @buffer.Buffer(size_hint=name.length())
  for i in 0..<chars.length() {
    let c = chars[i]
    if i > 0 &&
      c >= 'A' &&
      c <= 'Z' &&
      (
        (chars[i - 1] >= 'a' && chars[i - 1] <= 'z') ||
        (chars[i - 1] >= '0' && chars[i - 1] <= '9')
      ) {
      normalized.write_char_utf8('_')
    }
    normalized.write_char_utf8(if c == '-' { '_' } else { c })
  }
  let name = @utf8.decode_lossy(normalized.to_bytes()).to_lower()
  [
    "auth", "authorization", "proxy_authorization", "cookie", "set_cookie", "password",
    "passwd", "token", "access_token", "accesstoken", "refresh_token", "refreshtoken",
    "id_token", "api_key", "apikey", "x_api_key", "credential", "credentials", "secret",
    "client_secret", "clientsecret", "private_key", "privatekey", "aws_secret_access_key",
    "azure_storage_key", "docker_auth_config", "signature", "sig", "x_amz_signature",
    "x_amz_security_token", "x_goog_signature",
  ].contains(name) ||
  name
  .split("_")
  .iter()
  .any(part => {
    [
      "auth", "authorization", "cookie", "password", "passwd", "passphrase", "token",
      "secret", "apikey", "credential", "credentials", "signature", "pairingcode",
      "privatekey", "clientsecret", "accesstoken", "refreshtoken", "proxyauthorization",
      "setcookie",
    ].contains(part.to_owned())
  }) ||
  name.contains("_api_key_") ||
  name.has_prefix("api_key_") ||
  name.has_suffix("_api_key") ||
  name.contains("_private_key_") ||
  name.has_prefix("private_key_") ||
  name.has_suffix("_private_key") ||
  name == "pairing_code" ||
  name.contains("_pairing_code_") ||
  name.has_prefix("pairing_code_") ||
  name.has_suffix("_pairing_code")
}

///|
fn credential_word(c : Char) -> Bool {
  (c >= 'a' && c <= 'z') ||
  (c >= 'A' && c <= 'Z') ||
  (c >= '0' && c <= '9') ||
  c == '_' ||
  c == '-'
}

///|
fn credential_space(c : Char) -> Bool {
  c == ' ' || c == '\t'
}

///|
fn credential_end(c : Char) -> Bool {
  credential_space(c) ||
  [',', ';', '&', '#', '"', '\'', '}', ']', '<', '>'].contains(c)
}

