        let health = @json.parse(
          @fs.read_file(root + "/diagnostic-health.json").text(),
        )
        assert_eq(field(health, "status"), Some(Json::string("degraded")))
        previous_ids.push(required(health, "runId"))
        @fs.remove(root + "/shutdown")
      }
      lock.unlock()
      let replacement = @process.spawn(
        group,
        integration_binary(),
        ["--supervisor", root],
        extra_env=env,
        stdout=sink,
        stderr=sink,
        no_wait=true,
