async test "supervisor carries unflushed recording loss across restarts" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  let root = env.get("XDG_STATE_HOME").unwrap() + "/orca-env-devsy"
  @fs.mkdir(root, recursive=true)
  let lock = @fs.open(
    root + "/events.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
  )
  defer lock.close()
  assert_true(lock.try_lock(Exclusive))
  @async.with_timeout(20000, async fn() {
    @async.with_task_group(async fn(group) {
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      let previous_ids : Array[String] = []
      for _ in 0..<2 {
        let child = @process.spawn(
          group,
          integration_binary(),
          ["--supervisor", root],
          extra_env=env,
          stdout=sink,
          stderr=sink,
          no_wait=true,
        )
        idle_wait_for(async fn() { @fs.exists(root + "/supervisor.json") })
        @fs.write_file(root + "/shutdown", "")
        assert_eq(child.wait(), 0)
        let health = @json.parse(
          @fs.read_file(root + "/diagnostic-health.json").text(),
        )
        assert_eq(field(health, "status"), Some(Json::string("degraded")))
        previous_ids.push(required(health, "runId"))
        @fs.remove(root + "/shutdown")
      }
      lock.unlock()
      let replacement = @process.spawn(
        group,
        integration_binary(),
        ["--supervisor", root],
        extra_env=env,
        stdout=sink,
        stderr=sink,
        no_wait=true,
      )
      idle_wait_for(async fn() {
        @fs.exists(root + "/events.jsonl") &&
        fixture_events(directory)
        .iter()
        .any(event => {
          field(event, "errorType") ==
          Some(Json::string("previous_run_unflushed")) &&
          field(event, "runId") == Some(Json::string(previous_ids[0]))
        })
      })
      let events = fixture_events(directory)
      for id in previous_ids {
        let loss = events.filter(event => {
          field(event, "errorType") ==
          Some(Json::string("previous_run_unflushed")) &&
          field(event, "runId") == Some(Json::string(id)) &&
          field(event, "completeness") == Some(Json::string("partial"))
        })
        assert_eq(loss.length(), 1)
        assert_eq(
          field(loss[0], "missingRange"),
          Some(Json::string("observed")),
        )
        assert_true(
          @string.parse_int64(required(loss[0], "missingFromTime")) <=
          @string.parse_int64(required(loss[0], "missingThroughTime")),
        )
        assert_eq(
          field(loss[0], "previousReason"),
          Some(Json::string("lock_busy")),
        )
      }
      idle_wait_for(async fn() { !@fs.exists(root + "/diagnostic-health.json") })
      @fs.write_file(root + "/shutdown", "")
      assert_eq(replacement.wait(), 0)
    })
  })
}

