import os, pathlib, signal, subprocess, tempfile, time
with tempfile.TemporaryDirectory(prefix='orca-signal-probe-') as d:
 for name in ('TERM','INT','HUP'):
  ready=pathlib.Path(d)/('ready-'+name); got=pathlib.Path(d)/('got-'+name)
  js='const fs=require("fs"); const [ready,got]=process.argv.slice(1); for (const s of ["SIGTERM","SIGINT","SIGHUP"]) process.on(s,()=>{fs.writeFileSync(got,s);process.exit(0)}); fs.writeFileSync(ready,"ready");setInterval(()=>{},1000);'
  shell='child=; pending=; forward() { pending=$1; if test -n "$child"; then kill -s "$pending" "$child" 2>/dev/null || :; fi; }; trap "forward TERM" TERM; trap "forward INT" INT; trap "forward HUP" HUP; printf x | node -e "$1" "$2" "$3" & child=$!; if test -n "$pending"; then kill -s "$pending" "$child" 2>/dev/null || :; fi; wait "$child"; result=$?; if test -n "$pending"; then wait "$child" 2>/dev/null || :; exit 1; fi; exit "$result"'
