  let body = "trap 'rmdir \"$HOME/.local/share/orca-env-devsy/orca/update-active\"' EXIT; " +
    shell_wait_with_signals("sh -c " + quote(script))
  "marker=\"$HOME/.local/share/orca-env-devsy/orca/update-active\"; mkdir \"$marker\" 2>/dev/null || { printf 'Another update may be running or its marker needs inspection\\n' >&2; exit 1; }; " +
  shell_wait_with_signals("sh -c " + quote(body))
}

