    )
    settings_fixture(directory, env)
    let source : Json = {
      "sourceControlAi": {
        "actions": {
          "branchName": {
            "agentArgs": "--access-token fixture-profile-private",
          },
          "conversationName": {},
        },
      },
    }
    @fs.write_file(directory + "/orca-host/settings.json", source.stringify())
    @fs.write_file(directory + "/fail-settings-transport", "")
    let (status, _, errors) = invoke("create", env, directory)
    assert_true(status != 0)
    assert_false(errors.contains("fixture-profile-private"))
    assert_false(errors.contains("fixture-wire-secret"))
    let events = fixture_events(directory)
    let failures = events.filter(event => {
      field(event, "stage") == Some(Json::string("orca-settings")) &&
      field(event, "status") == Some(Json::string("failed"))
    })
    assert_eq(failures.length(), 1)
