    assert_eq(field(failure, "exitCode"), Some(Json::number(255)))
    assert_eq(field(failure, "detailsTruncated"), Some(Json::boolean(true)))
    let detail = required(failure, "errorMessage")
    assert_true(detail.contains("settings transport refused"), msg=detail)
    assert_false(detail.contains("fixture-profile-private"), msg=detail)
    assert_false(detail.contains("fixture-wire-secret"), msg=detail)
  })
}

