///|
pub suberror ConfigError {
  InvalidConfig(String)
} derive(Debug)

///|
pub impl Show for ConfigError with fn output(self, logger) {
  logger.write_string(diagnostic_error(self))
}

///|
pub extend ConfigError with Show::{to_string, output}

///|
pub enum Connection {
  Server
  Ssh
} derive(Eq, Debug)

///|
pub struct Settings {
  connection : Connection
  command : Array[String]
  home : String?
  context : String?
  build_ref : String?
  up_args : Array[String]
  codex_auth : Bool
  server_env : Json
  idle_timeout_ms : Int64?
  idle_timeout_source : String?
} derive(Eq, Debug)

///|
fn string_field(
  value : Json,
  name : String,
  location : String,
) -> String? raise ConfigError {
  match field(value, name) {
    None => None
    Some(Json::String(text)) => Some(text)
    _ => raise InvalidConfig("\{location}.\{name} must be a string")
  }
}

///|
fn object_field(
  value : Json,
  name : String,
  location : String,
) -> Json raise ConfigError {
  match field(value, name) {
    None => Json::empty_object()
    Some(Json::Object(_) as object) => object
    _ => raise InvalidConfig("\{location}.\{name} must be a mapping")
  }
}

///|
fn args_field(
  value : Json,
  location : String,
) -> Array[String] raise ConfigError {
  match field(value, "upArgs") {
    None => []
    Some(Json::Array(items)) =>
      items.map(item => {
        match item {
          Json::String(text) => text
          _ => raise InvalidConfig("\{location}.upArgs must contain strings")
        }
      })
    _ => raise InvalidConfig("\{location}.upArgs must be an array")
  }
}

///|
fn command_field(
  value : Json,
  location : String,
) -> Array[String]? raise ConfigError {
  match field(value, "command") {
    None => None
    Some(Json::Array(items)) => {
      guard items.length() > 0 else {
        raise InvalidConfig("\{location}.command must be a nonempty array")
      }
      let command = items.mapi((index, item) => {
        match item {
          Json::String(text) => {
            guard !text.contains("\u0000") && (index != 0 || text != "") else {
              raise InvalidConfig(
                "\{location}.command[\{index}] must not contain NUL or have an empty executable",
              )
            }
            text
          }
          _ =>
            raise InvalidConfig(
              "\{location}.command[\{index}] must be a string",
            )
        }
      })
      Some(command)
    }
    _ => raise InvalidConfig("\{location}.command must be an array of strings")
  }
}

///|
fn valid_env_name(name : String) -> Bool {
  let characters = name.to_array()
  characters.length() > 0 &&
  !(characters[0] >= '0' && characters[0] <= '9') &&
  characters
  .iter()
  .all(char => {
    char == '_' ||
    (char >= 'a' && char <= 'z') ||
    (char >= 'A' && char <= 'Z') ||
    (char >= '0' && char <= '9')
  })
}

///|
pub fn interpolate(
  value : String,
  lookup : (String) -> String?,
  location : String,
) -> String raise ConfigError {
  let output = StringBuilder()
  let mut remaining = value
  while remaining.split_once("${") is Some((prefix, expression)) {
    output.write_string(prefix.to_owned())
    guard expression.split_once("}") is Some((variable, suffix)) else {
      raise InvalidConfig("\{location}: unterminated environment variable")
    }
    let text = variable.to_owned()
    let required = text.has_suffix("?")
    let name = if required { text[:text.length() - 1].to_owned() } else { text }
    guard valid_env_name(name) else {
      raise InvalidConfig("\{location}: invalid environment variable reference")
    }
    match lookup(name) {
      Some(resolved) => output.write_string(resolved)
      None if required =>
        raise InvalidConfig(
          "\{location}: environment variable \{name} is not defined",
        )
      None => ()
    }
    remaining = suffix.to_owned()
  }
  output.write_string(remaining)
  output.to_string()
}

///|
pub fn resolve_settings(
  document : Json,
  recipe_id : String,
  lookup : (String) -> String?,
) -> Settings raise ConfigError {
  let common = object_field(document, "devsy", "orca.yaml")
  let recipes = match field(document, "environmentRecipes") {
    Some(Json::Array(items)) => items
    _ => raise InvalidConfig("orca.yaml.environmentRecipes must be an array")
  }
  let selected = recipes.filter(recipe => {
    field(recipe, "id") == Some(Json::string(recipe_id))
  })
  guard selected.length() == 1 else {
    raise InvalidConfig(
      "Expected exactly one environment recipe named \{recipe_id}",
    )
  }
  let specific = object_field(
    selected[0],
    "devsy",
    "environmentRecipes.\{recipe_id}",
  )
  let profile_name = match string_field(specific, "profile", "recipe.devsy") {
    Some(name) => Some(name)
    None => string_field(common, "profile", "devsy")
  }
  let profiles = object_field(common, "profiles", "devsy")
  let mut profile_location = "devsy.profiles"
  let profile = match profile_name {
    Some(raw_name) => {
      let name = interpolate(raw_name, lookup, "devsy.profile")
      profile_location = "devsy.profiles." + name
      match field(profiles, name) {
        Some(Json::Object(_) as value) => value
        _ => raise InvalidConfig("Unknown devsy profile")
      }
    }
    None => Json::empty_object()
  }
  let layers = [common, profile, specific]
  let mut command = ["devsy"]
  let mut home = None
  let mut context = None
  let mut build_ref = None
  let mut connection = None
  let mut codex_auth = false
  let mut idle_timeout_ms = None
  let mut idle_timeout_source = None
  let args = []
  let server_env = Json::empty_object()
  for index, layer in layers {
    let location = [
        "devsy",
        profile_location,
        "environmentRecipes." + recipe_id + ".devsy",
      ][index]
    if command_field(layer, location) is Some(raw) {
      let expanded = raw.mapi((argument_index, argument) => {
        interpolate(argument, lookup, "\{location}.command[\{argument_index}]")
      })
      let value = Json::empty_object()
      set_field(value, "command", Json::array(expanded.map(Json::string)))
      command = command_field(value, location).unwrap()
    }
    for
      pair in [
        ("home", string_field(layer, "home", location)),
        ("context", string_field(layer, "context", location)),
        ("buildRef", string_field(layer, "buildRef", location)),
        ("connection", string_field(layer, "connection", location)),
      ] {
      let (name, value) = pair
      if value is Some(raw) {
        let expanded = interpolate(raw, lookup, "\{location}.\{name}")
        match name {
          "home" => home = Some(expanded)
          "context" => context = Some(expanded)
          "buildRef" => build_ref = Some(expanded)
          _ => connection = Some(expanded)
        }
      }
    }
    for argument_index, argument in args_field(layer, location) {
      args.push(
        interpolate(argument, lookup, "\{location}.upArgs[\{argument_index}]"),
      )
    }
    let server = object_field(layer, "orca-server", location)
    let configured_env = object_field(server, "env", location + ".orca-server")
    if configured_env is Json::Object(values) {
      for name, value in values {
        let setting_location = location + ".orca-server.env." + name
        guard valid_env_name(name) else {
          raise InvalidConfig(setting_location + " has an invalid name")
        }
        ignore(interpolate("${" + name + "}", _ => None, setting_location))
        guard value is Json::String(text) && !text.contains("\u0000") else {
          raise InvalidConfig(
            setting_location + " must be a string without NUL",
          )
        }
        let literal = interpolate(text, _ => Some(""), setting_location)
        guard !(credential_field(name) && literal != "") &&
          redact_credentials(text) == text else {
          raise InvalidConfig(
            setting_location + ": credential values must use remote references",
          )
        }
        set_field(server_env, name, value)
      }
    }
    let addons = object_field(layer, "addons", location)
    if string_field(layer, "idleTimeout", location) is Some(raw) {
      idle_timeout_ms = Some(
        parse_idle_timeout(interpolate(raw, lookup, "\{location}.idleTimeout")) catch {
          InvalidConfig(message) =>
            raise InvalidConfig("\{location}.idleTimeout: " + message)
        },
      )
      idle_timeout_source = Some(location + ".idleTimeout")
    }
    match field(addons, "codexAuth") {
      None => ()
      Some(Json::True) => codex_auth = true
      Some(Json::False) => codex_auth = false
      _ => raise InvalidConfig("\{location}.addons.codexAuth must be a boolean")
    }
  }
  let connection = match connection {
    Some("orca-server") => Server
    Some("ssh") => Ssh
    _ =>
      raise InvalidConfig(
        "devsy.connection must explicitly select orca-server or ssh",
      )
  }
  {
    connection,
    command,
    home,
    context,
    build_ref,
    up_args: args,
    codex_auth,
    server_env,
    idle_timeout_ms,
    idle_timeout_source,
  }
}

///|
fn field(value : Json, name : String) -> Json? {
  if value is Json::Object(object) {
    object.get(name)
  } else {
    None
  }
}

///|
pub extend Connection with Eq::{equal, not_equal}

///|
pub extend Settings with Eq::{equal, not_equal}

///|
pub extend ConfigError with @moonbitlang/core/debug.Debug::{to_repr}

///|
pub extend Connection with @debug.Debug::{to_repr}

///|
pub extend Settings with @debug.Debug::{to_repr}

///|
suberror AdapterError {
  AdapterError(String)
} derive(@debug.Debug)

///|
impl Show for AdapterError with fn output(self, logger) {
  logger.write_string(diagnostic_error(self))
}

///|
fn required(value : Json, name : String) -> String raise {
  match field(value, name) {
    Some(Json::String(text)) if text != "" => text
    _ => raise AdapterError("Missing or invalid \{name}")
  }
}

///|
fn environment(name : String) -> String raise {
  match @env.get_env_var(name) {
    Some(value) if value != "" => value
    _ => raise AdapterError("Missing \{name}")
  }
}

///|
fn quote(text : String) -> String {
  let escaped_quote =
    #|'"'"'
  "'" + text.replace_all(old="'", new=escaped_quote) + "'"
}

///|
async fn command_result(
  program : String,
  args : Array[String],
  stage : String,
  environment? : Map[String, String],
  cwd? : StringView,
  target? : String,
  recording_override? : Bool,
  protected_secrets? : Array[String],
  protection_incomplete~ : Bool = false,
) -> (Int32, String, String) {
  let recording = recording_override.unwrap_or(
    environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
    Some("0"),
  )
  let context : Json? = if recording {
    diagnostic_operation_counter.val += 1
    let value : Json = {
      "operationId": recording_run_id +
      ":" +
      diagnostic_operation_counter.val.to_string(),
    }
    if target is Some(id) {
      set_field(value, "workspaceId", Json::string(id))
    }
    Some(value)
  } else {
    None
  }
  save_diagnostic(
    stage,
    "started",
    evidence?=context,
    evidence_stable_operation=true,
    environment?,
    protected_secrets?,
    recording~,
  )
  let started = @env.now()
  let progress = Progress::new(
    stage,
    environment?,
    context?,
    recording_override=recording,
    protected_secrets?,
    protection_incomplete~,
  )
  let label = target.map(value => value + ": " + stage).unwrap_or(stage)
  progress_message(label + ": running…")
  let mut failure_kind = "process_api"
  let mut failure_errno = None
  let mut failure_phase = None
  let (status, output, errors) = {
    errdefer {
      save_diagnostic(
        stage,
        if @async.is_being_cancelled() {
          "cancelled"
        } else {
          "process-error"
        },
        error_type=failure_kind,
        os_errno?=failure_errno,
        phase?=failure_phase,
        error_message=progress.failure_detail(),
        details_truncated=progress.details_truncated,
        evidence?=context,
        evidence_stable_operation=true,
        environment?,
        protected_secrets?,
        recording~,
      )
      progress_message(label + ": failed (" + progress_timing(started) + ")")
    }
    try {
      let (out, stdout) = @process.read_from_process()
      defer out.close()
      let (err, stderr) = @process.read_from_process()
      defer err.close()
      @async.with_task_group(async fn(group) {
        let child = @process.spawn(
          group,
          program,
          args,
          extra_env?=environment,
          inherit_env=environment is None,
          cwd?,
          stdout~,
          stderr~,
        )
        let output = group.spawn(async fn() {
          progress.read_output(
            out,
            capture=true,
            statuses=devsy_progress_stage(stage),
            messages=stage == "orca-install" || stage == "checkout-workspace",
          )
        })
        let errors = group.spawn(async fn() {
          progress.read_output(
            err,
            capture=false,
            messages=devsy_progress_stage(stage) ||
              stage == "orca-install" ||
              stage == "checkout-workspace",
          )
        })
        (child.wait(), output.wait(), errors.wait())
      })
    } catch {
      @os_error.OSError(code, ..) as error => {
        failure_kind = "process_os"
        failure_errno = Some(code)
        let message = if protection_incomplete {
          progress.details_truncated = true
          "subprocess OS error \{code}; workspace protection values unavailable"
        } else {
          progress
          .safe_message(program + ": " + error.to_string())
          .unwrap_or("subprocess OS error \{code}")
        }
        progress.remember(message, warning=true)
        raise AdapterError(
          "\{stage} failed (OS error \{code}); diagnostic run \{recording_run_id}:\n" +
          message,
        )
      }
      @utf8.Malformed(_) => {
        failure_kind = "process_utf8"
        failure_phase = Some("read")
        progress.remember("subprocess output is not valid UTF-8", warning=true)
        raise AdapterError(
          "\{stage} failed: subprocess output is not valid UTF-8; diagnostic run \{recording_run_id}",
        )
      }
      error => {
        if !@async.is_being_cancelled() {
          let detail = if protection_incomplete {
            progress.details_truncated = true
            "error detail unavailable because workspace protection values could not be read"
          } else {
            diagnostic_text(
              diagnostic_error(error, environment?),
              environment?,
              protected_secrets=progress.secrets,
            )
          }
          for line in detail.split("\n") {
            progress.remember(line.to_owned(), warning=true)
          }
        }
        raise error
      }
    }
  }
  let output_secrets = [] + progress.secrets
  let mut output_protection_incomplete = false
  if stage == "orca-serve" {
    for line in output.split("\n") {
      let result = @json.parse(line.to_owned()) catch { _ => Json::null() }
      let connection = field(result, "connection").unwrap_or(result)
      if field(connection, "pairingCode") is Some(Json::String(pairing)) && pairing != "" {
        if pairing.length() > 65536 {
          output_protection_incomplete = true
        } else {
          add_protected_secret(output_secrets, pairing)
        }
      }
    }
  }
  let detail = if output_protection_incomplete {
    progress.details_truncated = true
    "error detail unavailable because server protection values exceed the limit\n[error details incomplete or truncated]"
  } else {
    diagnostic_text(
      progress.failure_detail(),
      environment?,
      protected_secrets=output_secrets,
    )
  }
  let observed_status = if stage == "orca-serve" &&
    status > 128 && status <= 255 &&
    detail.contains("Orca server terminated by SIG") {
    128 - status
  } else {
    status
  }
  progress_message(
    label +
    ": " +
    (if observed_status == 0 { "done" } else { "failed (exit \{observed_status})" }) +
    " (" +
    progress_timing(started) +
    ")",
  )
  if status == 0 &&
    (
      !progress.failures.is_empty() ||
      progress.details_truncated ||
      (stage == "orca-serve" && !progress.recent.is_empty())
    ) {
    save_diagnostic(
      stage,
      if stage == "orca-serve" { "stderr" } else { "warning" },
      error_message=detail,
      details_truncated=progress.details_truncated,
      evidence?=context,
      evidence_stable_operation=true,
      environment?,
      protected_secrets=output_secrets,
      recording~,
    )
  }
  save_diagnostic(
    stage,
    if status == 0 {
      "success"
    } else {
      "exit-error"
    },
    exit_code=observed_status,
    duration_ms=(@env.now() - started).to_double(),
    error_message?=if status == 0 {
      None
    } else {
      Some(detail)
    },
    details_truncated=progress.details_truncated,
    evidence?=context,
    evidence_stable_operation=true,
    environment?,
    protected_secrets=output_secrets,
    error_type?=if status == 0 || !recording {
      None
    } else if observed_status < 0 {
      Some("signal")
    } else {
      Some(process_error_type(output + "\n" + errors))
    },
    recording~,
  )
  (observed_status, output, detail)
}

///|
fn command_failure(stage : String, status : Int32, detail : String) -> String {
  "\{stage} failed (exit \{status}); diagnostic run \{recording_run_id}:\n" +
  detail
}

///|
async fn command(
  program : String,
  args : Array[String],
  stage : String,
  environment? : Map[String, String],
  cwd? : StringView,
  target? : String,
  recording_override? : Bool,
  protected_secrets? : Array[String],
  protection_incomplete~ : Bool = false,
) -> String {
  let (status, output, detail) = command_result(
    program,
    args,
    stage,
    environment?,
    cwd?,
    target?,
    recording_override?,
    protected_secrets?,
    protection_incomplete~,
  )
  guard status == 0 else {
    raise AdapterError(command_failure(stage, status, detail))
  }
  output
}

