///|
async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  timeout_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
  error_message? : String,
  details_truncated~ : Bool = false,
  tunnel_directory? : String,
  expected_workspace_uid? : String,
  observed_workspace_uid? : String,
  evidence? : Json,
  evidence_incomplete~ : Bool = false,
  evidence_stable_activity~ : Bool = false,
  evidence_stable_operation~ : Bool = false,
  run_completeness? : String,
  recording? : Bool,
  environment? : Map[String, String],
  protected_secrets? : Array[String],
) -> Unit {
  if !recording.unwrap_or(
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
    ) {
    return
  }
  diagnostic_run_has_events.val = true
  let event_time = @env.now()
  let event : Json = {
    "stage": stage,
    "status": status,
    "time": event_time.to_string(),
    "runId": recording_run_id,
    "adapterVersion": version,
  }
  if create_recording.attempt > 0 {
    set_field(
      event,
      "createAttempt",
      Json::number(create_recording.attempt.to_double()),
    )
    set_field(event, "createPhase", Json::string(create_recording.phase))
  }
  let process_environment = @env.get_env_vars()
  let secrets = [] + protected_secrets.unwrap_or([])
  if environment is Some(environment) {
    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
      secrets.push(secret)
    }
  }
  if tunnel_directory is Some(directory) &&
    diagnostic_workspace_environments.get(directory) is Some(environment) {
    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
      secrets.push(secret)
    }
  }
  if error_message is Some(message) {
    let message = diagnostic_text(
      message,
      environment=process_environment,
      protected_secrets=secrets,
    )
    set_field(event, "errorMessage", Json::string(message))
    set_field(
      event,
      "detailsTruncated",
      Json::boolean(
        details_truncated ||
        message == "[error details incomplete or truncated]" ||
        message.has_suffix("\n[error details incomplete or truncated]"),
      ),
    )
  }
  if tunnel_directory is Some(directory) {
    set_field(
      event,
      "tunnelDirectory",
      Json::string(
        diagnostic_text(
          directory,
          environment=process_environment,
          protected_secrets=secrets,
        ),
      ),
    )
  }
  for
    pair in [
      ("expectedWorkspaceUid", expected_workspace_uid),
      ("observedWorkspaceUid", observed_workspace_uid),
    ] {
    if pair.1 is Some(value) {
      set_field(
        event,
        pair.0,
        Json::string(
          diagnostic_text(
            value,
            environment=process_environment,
            protected_secrets=secrets,
          ),
        ),
      )
    }
  }
  let evidence_truncated : Ref[Bool] = { val: evidence_incomplete, }
  if source is Some(evidence) {
    let value = evidence.to_json()
    if value.stringify().length() <= 65536 {
      set_field(
        event,
        "source",
        diagnostic_json(
      },
    ),
  )
  let mut selection_reason = if task_build {
    "orca-input"
  } else {
    "configured-build-ref"
  }
  if task_build && hash != environment("ORCA_REPO_REF_HEAD") {
    selection_reason = "task-head-differs-from-ref"
    hash = environment("ORCA_REPO_REF_HEAD")
    resolved_branch = None
  }
  if pinned_commit is Some(commit) {
    selection_reason = "checkout-mismatch-retry"
    hash = commit
    resolved_branch = None
  }
  save_diagnostic(
    "build-selection",
    "success",
    source=Selection(
      build_ref, lookup_ref, resolved_branch, hash, selection_reason,
    ),
  )
  create_recording.phase = "build"
  set_field(state, "buildCommit", Json::string(hash))
  set_field(state, "buildRef", Json::string(build_ref))
  let creation_lock = workspace_creation_lock()
  let mut creation_reserved = true
  defer (if creation_reserved { creation_lock.close() })
  select_workspace_name(state, repository)
  for argument in config.up_args {
    guard ![
        "--id", "--uid", "--home", "--context", "--result-format", "--ide-launch",
        "--",
      ]
      .iter()
      .any(flag => argument == flag || argument.has_prefix(flag + "=")) else {
      raise AdapterError("upArgs cannot override adapter-owned options")
    }
  }
  let reservation = @fs.tmpdir(prefix="oe-create-")
  let uid = reservation.split("/").to_array().last().unwrap().to_owned() +
    "-" +
    @env.now().to_string()
  @fs.rmdir(reservation)
  set_field(state, "workspaceUid", Json::string(uid))
  if config.connection == Server {
    let volume = "orca-env-devsy-" + uid
    set_field(state, "orcaVolume", Json::string(volume))
    save_diagnostic("orca-volume", "selected", source=Storage(volume, ""))
  }
  errdefer discard_created_workspace(state)
  let create_args = fn(source : String, strategy : String) raise {
    [
      "--result-format",
      "json",
      "--uid",
      required(state, "workspaceUid"),
      "workspace",
      "up",
      source,
      "--id",
      required(state, "workspaceId"),
      "--ide-launch",
      "skip",
      "--git-clone-strategy=" + strategy,
    ] +
    config.up_args +
    orca_storage_args(state)
  }
  let pinned_args = create_args(repository + "@sha256:" + hash, "")
  let native_source = match resolved_branch {
    Some(branch) => {
      ignore(
        command(
          "git",
          ["check-ref-format", "refs/heads/" + branch],
          "validate-build-branch",
        ),
      )
      repository + "@" + branch
    }
    None => repository + "@sha256:" + hash
  }
  let automatic_shallow = resolved_branch is Some(branch) &&
    (task_build || default_ref == Some("refs/heads/" + branch))
  let overridden = config.up_args
    .iter()
    .any(arg => {
      continue
    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
      progress_message(self.stage + ": " + safe)
    } else if !debug && safe.has_prefix("[credential") {
      progress_message(self.stage + ": " + safe)
    }
  }
}

