  let mut workspace_env : Map[String, String]? = None
  let mut target : String? = None
  let mut attempt : Int32? = None
  let started = @env.now()
  let failure = try {
    @async.with_timeout(10000, async fn() {
      let peer = @json.parse(identity.stringify())
      set_field(peer, "connectionId", Json::string(connection))
      write_registration(socket, peer)
      phase = "request"
      let request = read_registration(socket, 4194304)
      let raw_environment = field(request, "environment").unwrap_or(
        Json::null(),
      )
      if field(raw_environment, "ORCA_ENV_DEVSY_RECORDING") ==
        Some(Json::string("0")) {
        recording = false
      }
      if field(request, "operationId") is Some(Json::String(id)) &&
        registration_id_valid(id) {
        set_field(context, "operationId", Json::string(id))
      }
      if field(request, "attempt") is Some(Json::Number(value, ..)) &&
        value > 0 &&
        value <= 1000 &&
        value == value.trunc() {
        attempt = Some(value.to_int())
      }
      phase = "environment"
      guard raw_environment is Json::Object(values) else {
        raise AdapterError("Missing workspace execution environment")
      }
      let environment : Map[String, String] = Map([])
      for (name, value) in values {
        guard value is Json::String(value) else {
          raise AdapterError("Invalid workspace execution environment")
        }
        environment.set(name, value)
      }
      workspace_env = Some(environment)
      recording = environment.get("ORCA_ENV_DEVSY_RECORDING") != Some("0")
      phase = "directory"
  let connection = match connection {
    Some("orca-server") => Server
    Some("ssh") => Ssh
    _ =>
      raise InvalidConfig(
        "devsy.connection must explicitly select orca-server or ssh",
      )
  }
  (
    {
      connection,
      command,
      home,
      context,
      build_ref,
      up_args: args,
      codex_auth,
      server_env,
      idle_timeout_ms,
      idle_timeout_source,
    },
    arg_sources,
  )
}

