///|
async fn write_registration(socket : @socket.Tcp, value : Json) -> Unit {
  let bytes = @utf8.encode(value.stringify())
  guard bytes.length() <= 4194304 else {
    raise AdapterError("Registration is too large")
  }
  socket.write(bytes.length().to_string() + "\n")
  socket.write(bytes)
}

///|
async fn register_workspace(directory : String, environment? : Json) -> Unit {
  let values = match environment {
    Some(Json::Object(items)) => {
      let result : Map[String, String] = Map([])
      for (name, value) in items {
        if value is Json::String(text) {
          result.set(name, text)
        }
      }
      result
    }
    _ => @env.get_env_vars()
  }
  let recording = @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0") &&
    values.get("ORCA_ENV_DEVSY_RECORDING") != Some("0")
  diagnostic_operation_counter.val += 1
  let operation = recording_run_id +
    ":" +
    diagnostic_operation_counter.val.to_string()
  let context : Json = { "operationId": operation }
  let phase : Ref[String] = { val: "supervisor", }
  let mut last_phase = "supervisor"
  let mut attempts = 0
  let mut detail = "Supervisor registration endpoint is not ready"
  let started = @env.now()
  save_diagnostic(
    "workspace-registration",
    "started",
    tunnel_directory=directory,
    evidence=context,
    evidence_stable_operation=true,
    environment=values,
    recording~,
  )
  let failure = try {
    @async.with_timeout(10000, async fn() {
      while true {
        attempts += 1
        phase.val = "supervisor"
        try {
          ensure_supervisor()
          register_workspace_inner(
            directory,
            operation,
            attempts,
            context,
            phase,
            environment?,
          )
          return
        } catch {
          error => {
            if @async.is_being_cancelled() {
              raise error
            }
            last_phase = phase.val
            detail = diagnostic_error(error, environment=values)
            if attempts <= 3 {
              save_diagnostic(
                "workspace-registration",
                "retry",
                error_type="registration_retry",
                phase=last_phase,
                attempt=attempts,
                retry_delay_ms=100,
                error_message=detail,
                tunnel_directory=directory,
                evidence=context,
                evidence_stable_operation=true,
                environment=values,
                recording~,
              )
            }
          }
        }
        @async.sleep(100)
      }
    })
    None
  } catch {
    error => Some(error)
  }
  if failure is Some(error) {
    let cancelled = @async.is_being_cancelled()
    @async.protect_from_cancel(async fn() {
      save_diagnostic(
        "workspace-registration",
        if cancelled {
          "cancelled"
        } else if error is @async.TimeoutError {
          "timeout"
        } else {
          "failed"
        },
        error_type=if cancelled {
          "cancelled"
        } else if error is @async.TimeoutError {
          "registration_timeout"
        } else {
          "registration_failed"
        },
        phase=phase.val,
        attempt=attempts,
        timeout_ms=10000,
        duration_ms=(@env.now() - started).to_double(),
        error_message="Last attempt (" + last_phase + "): " + detail,
        tunnel_directory=directory,
        evidence=context,
        evidence_stable_operation=true,
        environment=values,
        recording~,
      )
    })
    if error is @async.TimeoutError {
      raise AdapterError(
        "Workspace registration timed out at " +
        phase.val +
        "; last attempt (" +
        last_phase +
        "): " +
        detail,
      )
    }
    raise error
  }
  save_diagnostic(
    "workspace-registration",
    "success",
    phase=phase.val,
    attempt=attempts,
    duration_ms=(@env.now() - started).to_double(),
    tunnel_directory=directory,
    tunnel_directory=directory,
    evidence=context,
    evidence_stable_operation=true,
    environment=values,
    recording~,
  )
}

///|
async fn register_workspace_inner(
  directory : String,
  operation : String,
  attempt : Int32,
  context : Json,
  phase : Ref[String],
  environment? : Json,
) -> Unit {
  phase.val = "descriptor"
  let path = adapter_state_home() + "/supervisor.json"
  let descriptor = @json.parse(@fs.read_file(path).text())
  let pid = @string.parse_int(required(descriptor, "pid"))
  let start = @string.parse_int64(required(descriptor, "start"))
  guard pid > 1 && start > 0 && process_start(pid) == start else {
    raise AdapterError("Supervisor registration endpoint is stale")
  }
  let port = @string.parse_int(required(descriptor, "port"))
  guard port > 0 && port <= 65535 else {
    raise AdapterError("Invalid supervisor port")
  }
  phase.val = "connect"
  let socket = @socket.Tcp::connect(
    @socket.Addr::parse("127.0.0.1:" + port.to_string()),
  )
  defer socket.close()
  phase.val = "peer"
  let peer = read_registration(socket, 4096)
  guard field(peer, "protocol") == Some(Json::number(1)) &&
    field(peer, "pid") == field(descriptor, "pid") &&
    field(peer, "start") == field(descriptor, "start") else {
    raise AdapterError("Supervisor registration endpoint changed")
  }
  if field(peer, "connectionId") is Some(Json::String(id)) &&
    registration_id_valid(id) {
    set_field(context, "connectionId", Json::string(id))
  }
  let environment = environment.unwrap_or_else(() => {
    let values = Json::empty_object()
    for (name, value) in @env.get_env_vars() {
      set_field(values, name, Json::string(value))
    }
    values
  })
  phase.val = "request"
  write_registration(socket, {
    "directory": directory,
    "environment": environment,
    "operationId": operation,
    "attempt": attempt,
  })
  phase.val = "reply"
  let reply = read_registration(socket, 4096)
  guard field(reply, "accepted") == Some(Json::boolean(true)) else {
    raise AdapterError("Supervisor rejected workspace registration")
  }
  if field(field(reply, "diagnosticHealth").unwrap_or(Json::null()), "status") ==
    Some(Json::string("degraded")) {
    progress_write(
      "orca-env-devsy: warning: supervisor diagnostic recording is unavailable\n",
    )
  }
}

///|
fn registration_id_valid(id : String) -> Bool {
  id.length() > 0 &&
  id.length() <= 80 &&
  id.iter().all(c => (c >= '0' && c <= '9') || c == '_' || c == ':')
}

///|
async fn accept_registration(
  socket : @socket.Tcp,
  root : String,
  environments : Map[String, Map[String, String]],
  identity : Json,
) -> Unit {
  defer socket.close()
  diagnostic_operation_counter.val += 1
  let connection = recording_run_id +
    ":" +
    diagnostic_operation_counter.val.to_string()
  let context : Json = { "connectionId": connection }
  let mut phase = "peer"
  let mut recording = @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0")
  let mut workspace_env : Map[String, String]? = None
  let mut target : String? = None
  let mut attempt : Int32? = None
  let started = @env.now()
  let failure = try {
    @async.with_timeout(10000, async fn() {
      let peer = @json.parse(identity.stringify())
      set_field(peer, "connectionId", Json::string(connection))
      write_registration(socket, peer)
      phase = "request"
      let request = read_registration(socket, 4194304)
      let raw_environment = field(request, "environment").unwrap_or(
        Json::null(),
      )
      if field(raw_environment, "ORCA_ENV_DEVSY_RECORDING") ==
        Some(Json::string("0")) {
        recording = false
      }
      if field(request, "operationId") is Some(Json::String(id)) &&
        registration_id_valid(id) {
        set_field(context, "operationId", Json::string(id))
      }
      if field(request, "attempt") is Some(Json::Number(value, ..)) &&
        value > 0 &&
        value <= 1000 &&
        value == value.trunc() {
        attempt = Some(value.to_int())
      }
      phase = "environment"
      guard raw_environment is Json::Object(values) else {
        raise AdapterError("Missing workspace execution environment")
      }
      let environment : Map[String, String] = Map([])
      for (name, value) in values {
        guard value is Json::String(value) else {
          raise AdapterError("Invalid workspace execution environment")
        }
        environment.set(name, value)
      }
      workspace_env = Some(environment)
      recording = environment.get("ORCA_ENV_DEVSY_RECORDING") != Some("0")
      phase = "directory"
  let connection = match connection {
    Some("orca-server") => Server
    Some("ssh") => Ssh
    _ =>
      raise InvalidConfig(
        "devsy.connection must explicitly select orca-server or ssh",
      )
  }
  (
    {
      connection,
      command,
      home,
      context,
      build_ref,
      up_args: args,
      codex_auth,
      server_env,
      idle_timeout_ms,
      idle_timeout_source,
    },
    arg_sources,
  )
}

///|
fn field(value : Json, name : String) -> Json? {
  if value is Json::Object(object) {
    object.get(name)
  } else {
    None
  }
}

///|
fn observable_size(value : String) -> Bool {
  value.length() > 0 &&
  value.length() <= 64 &&
  value
  .iter()
  .all(c => {
    (c >= 'a' && c <= 'z') ||
    (c >= 'A' && c <= 'Z') ||
    (c >= '0' && c <= '9') ||
    c == '.' ||
    c == '-' ||
    c == '_'
  }) &&
  [
    "nano", "micro", "small", "medium", "large", "xlarge", "2xlarge", "4xlarge",
    "8xlarge", "12xlarge", "16xlarge", "24xlarge", "32xlarge",
  ]
  .iter()
  .any(size => {
    value == size ||
    value.has_suffix("." + size) ||
    value.has_suffix("-" + size)
  })
}

