///|
fn credential_field(name : String, for_diagnostics~ : Bool = false) -> Bool {
  let exact_names = [
    "auth", "authorization", "proxy_authorization", "cookie", "set_cookie", "password",
    "passwd", "token", "access_token", "accesstoken", "refresh_token", "refreshtoken",
    "id_token", "api_key", "apikey", "x_api_key", "credential", "credentials", "secret",
    "client_secret", "clientsecret", "private_key", "privatekey", "aws_secret_access_key",
    "azure_storage_key", "docker_auth_config", "signature", "sig", "x_amz_signature",
    "x_amz_security_token", "x_goog_signature",
  ]
  if !for_diagnostics {
    let original = name
      .trim_start(chars="-")
      .to_owned()
      .to_lower()
      .replace_all(old="-", new="_")
    return exact_names.contains(original) ||
      [
        "_auth", "_password", "_passwd", "_token", "_secret", "_api_key", "_private_key",
      ]
      .iter()
      .any(suffix => original.has_suffix(suffix))
  }
  let chars = name.trim_start(chars="-").iter().to_array()
  let normalized = @buffer.Buffer(size_hint=name.length())
  for i in 0..<chars.length() {
    let c = chars[i]
    if i > 0 &&
      c >= 'A' &&
      c <= 'Z' &&
      (
        (chars[i - 1] >= 'a' && chars[i - 1] <= 'z') ||
        (chars[i - 1] >= '0' && chars[i - 1] <= '9')
      ) {
      normalized.write_char_utf8('_')
    }
    normalized.write_char_utf8(if c == '-' { '_' } else { c })
  }
  let name = @utf8.decode_lossy(normalized.to_bytes()).to_lower()
  if ["_enabled", "_disabled", "_count", "_mode", "_method"]
    .iter()
    .any(suffix => name.has_suffix(suffix)) {
    return false
  }
  exact_names.contains(name) ||
  name
  .split("_")
  .iter()
  .any(part => {
    [
      "auth", "authorization", "cookie", "password", "passwd", "passphrase", "token",
      "secret", "apikey", "credential", "credentials", "signature", "pairingcode",
      "privatekey", "clientsecret", "accesstoken", "refreshtoken", "proxyauthorization",
      "setcookie",
    ].contains(part.to_owned())
  }) ||
  name.contains("_api_key_") ||
  name.has_prefix("api_key_") ||
  name.has_suffix("_api_key") ||
  (
    for_diagnostics &&
    (
      name == "access_key" ||
      name.contains("_access_key_") ||
      name.has_prefix("access_key_") ||
      name.has_suffix("_access_key") ||
      name == "storage_key" ||
      name.contains("_storage_key_") ||
      name.has_prefix("storage_key_") ||
      name.has_suffix("_storage_key")
    )
  ) ||
  name.contains("_private_key_") ||
  name.has_prefix("private_key_") ||
  name.has_suffix("_private_key") ||
  name == "pairing_code" ||
  name.contains("_pairing_code_") ||
  name.has_prefix("pairing_code_") ||
  name.has_suffix("_pairing_code")
}

///|
fn credential_word(c : Char) -> Bool {
  (c >= 'a' && c <= 'z') ||
  (c >= 'A' && c <= 'Z') ||
  (c >= '0' && c <= '9') ||
  c == '_' ||
  c == '-'
}

///|
fn credential_space(c : Char) -> Bool {
  c == ' ' || c == '\t'
}

///|
fn credential_end(c : Char) -> Bool {
  credential_space(c) ||
  [',', ';', '&', '#', '"', '\'', '}', ']', '<', '>'].contains(c)
}

///|
fn character_text(chars : Array[Char], start : Int32, end : Int32) -> String {
  let buffer = @buffer.Buffer(size_hint=end - start)
  for i in start..<end {
    buffer.write_char_utf8(chars[i])
  }
  @utf8.decode_lossy(buffer.to_bytes())
}

///|
fn credential_hex(c : Char) -> Int32? {
  match c {
    '0'..<='9' => Some(c.to_int() - '0'.to_int())
    'a'..<='f' => Some(c.to_int() - 'a'.to_int() + 10)
    'A'..<='F' => Some(c.to_int() - 'A'.to_int() + 10)
    _ => None
  }
}

///|
fn credential_parameter(name : String) -> String {
  let chars = name.iter().to_array()
  let buffer = @buffer.Buffer(size_hint=name.length())
  let mut i = 0
  while i < chars.length() {
    if chars[i] == '%' &&
      i + 2 < chars.length() &&
      credential_hex(chars[i + 1]) is Some(hi) &&
      credential_hex(chars[i + 2]) is Some(lo) {
      buffer.write_char_utf8((hi * 16 + lo).unsafe_to_char())
      i += 3
    } else {
      buffer.write_char_utf8(chars[i])
      i += 1
    }
  }
  @utf8.decode_lossy(buffer.to_bytes())
}

///|
fn redact_credentials(text : String, for_diagnostics~ : Bool = true) -> String {
  let chars = text.iter().to_array()
  let buffer = @buffer.Buffer(size_hint=text.length())
  let mut i = 0
  let mut url = false
  while i < chars.length() {
    if credential_space(chars[i]) || ['"', '\''].contains(chars[i]) {
      url = false
    }
    if chars[i] == ':' &&
      i + 2 < chars.length() &&
      chars[i + 1] == '/' &&
      chars[i + 2] == '/' {
      url = true
      buffer.write_string_utf8("://")
      i += 3
      let mut end = i
      let mut user_end = None
      while end < chars.length() &&
            !credential_end(chars[end]) &&
            !['/', '?'].contains(chars[end]) {
        if chars[end] == '@' {
          user_end = Some(end)
        }
        end += 1
      }
      if user_end is Some(end) {
        buffer.write_string_utf8("[redacted]@")
        i = end + 1
      }
      continue
    }
    if url && ['?', '&'].contains(chars[i]) {
      let start = i
      i += 1
      while i < chars.length() && !credential_end(chars[i]) && chars[i] != '=' {
        i += 1
      }
      let name = credential_parameter(character_text(chars, start + 1, i))
      if i < chars.length() && chars[i] == '=' {
        i += 1
        buffer.write_string_utf8(character_text(chars, start, i))
        if credential_field(name, for_diagnostics~) ||
          name.to_lower() == "key" ||
          (for_diagnostics && name.to_lower() == "code") {
          if i + 10 <= chars.length() &&
            character_text(chars, i, i + 10) == "[redacted]" {
            i += 10
          }
          while i < chars.length() && !credential_end(chars[i]) {
            i += 1
          }
          buffer.write_string_utf8("[redacted]")
        }
      } else {
        buffer.write_string_utf8(character_text(chars, start, i))
      }
      continue
    }
    if credential_word(chars[i]) && (i == 0 || !credential_word(chars[i - 1])) {
      let start = i
      let mut end = i
      while end < chars.length() && credential_word(chars[end]) {
        end += 1
      }
      let word = character_text(chars, start, end)
      let lower = word.to_lower()
      if [
          "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "sk-", "age-secret-key-",
        ]
        .iter()
        .any(prefix => lower.has_prefix(prefix)) ||
        (for_diagnostics && lower.has_prefix("glpat-")) ||
        (word.has_prefix("eyJ") && end < chars.length() && chars[end] == '.') {
        while end < chars.length() && !credential_end(chars[end]) {
          end += 1
        }
        buffer.write_string_utf8("[redacted]")
        i = end
        continue
      }
      let mut separator = end
      if separator < chars.length() && ['"', '\''].contains(chars[separator]) {
        separator += 1
      }
      while separator < chars.length() && credential_space(chars[separator]) {
        separator += 1
      }
      if for_diagnostics &&
        ["bearer", "basic"].contains(lower) &&
        separator > end &&
        separator < chars.length() {
        let mut value_end = separator
        if separator + 10 <= chars.length() &&
          character_text(chars, separator, separator + 10) == "[redacted]" {
          value_end = separator + 10
        }
        while value_end < chars.length() && !credential_end(chars[value_end]) {
          value_end += 1
        }
        let value = character_text(chars, separator, value_end).to_lower()
        if value_end > separator &&
          !["authentication", "auth", "token"].contains(value) {
          buffer.write_string_utf8(character_text(chars, start, separator))
          buffer.write_string_utf8("[redacted]")
          i = value_end
          continue
        }
      }
      let mut previous = start
      while previous > 0 && credential_space(chars[previous - 1]) {
        previous -= 1
      }
      let field_start = previous == 0 ||
        [';', ',', '{', '"', '\'', '?', '&'].contains(chars[previous - 1])
      let option = word.has_prefix("--")
      let prose_credential = (
          ["credential", "credentials"].contains(lower) && !field_start
        ) ||
        ) ||
        (for_diagnostics && lower == "ssh_inject_git_credentials")
      let assignment = separator < chars.length() &&
        (
          chars[separator] == '=' ||
          (chars[separator] == ':' && !prose_credential)
        )
      if credential_field(word, for_diagnostics~) &&
        (assignment || (option && separator > end)) {
        let mut value = if assignment { separator + 1 } else { separator }
        while value < chars.length() && credential_space(chars[value]) {
          value += 1
        }
        buffer.write_string_utf8(character_text(chars, start, value))
        let quoted_key = start > 0 &&
          end < chars.length() &&
          ['"', '\''].contains(chars[start - 1]) &&
          chars[start - 1] == chars[end]
        if ["cookie", "set-cookie", "--cookie"].contains(lower) && !quoted_key {
          buffer.write_string_utf8("[redacted]")
          i = chars.length()
        } else if value + 10 <= chars.length() &&
          character_text(chars, value, value + 10) == "[redacted]" {
          buffer.write_string_utf8("[redacted]")
          i = value + 10
          while i < chars.length() && !credential_end(chars[i]) {
            i += 1
          }
        } else if value < chars.length() && ['"', '\''].contains(chars[value]) {
          let quote = chars[value]
          buffer.write_char_utf8(quote)
          value += 1
          while value < chars.length() && chars[value] != quote {
            if chars[value] == '\\' && value + 1 < chars.length() {
              value += 1
            }
            value += 1
          }
          buffer.write_string_utf8("[redacted]")
          i = value
        } else {
          let mut value_end = value
          while value_end < chars.length() && !credential_end(chars[value_end]) {
            value_end += 1
          }
          let scheme = character_text(chars, value, value_end).to_lower()
          if scheme == "bearer" || scheme == "basic" {
            while value_end < chars.length() &&
                  credential_space(chars[value_end]) {
              value_end += 1
            }
            buffer.write_string_utf8(character_text(chars, value, value_end))
            value = value_end
            while value_end < chars.length() &&
                  !credential_end(chars[value_end]) {
              value_end += 1
            }
          }
          if value + 10 <= chars.length() &&
            character_text(chars, value, value + 10) == "[redacted]" {
            value_end = value + 10
          }
          if value_end > value {
            buffer.write_string_utf8("[redacted]")
          }
          i = value_end
        }
        continue
      }
      buffer.write_string_utf8(word)
      i = end
      continue
    }
    buffer.write_char_utf8(chars[i])
    i += 1
  }
  @utf8.decode_lossy(buffer.to_bytes())
}

///|
fn ascii_match_at(
  chars : Array[Char],
  offset : Int32,
  pattern : Array[Char],
) -> Bool {
  if offset + pattern.length() > chars.length() {
    return false
  }
  for index in 0..<pattern.length() {
    let value = chars[offset + index]
    let lower = if value >= 'A' && value <= 'Z' {
      (value.to_int() + 32).unsafe_to_char()
    } else {
      value
    }
    if lower != pattern[index] {
      return false
    }
  }
  true
}

///|
fn private_key_marker(
  chars : Array[Char],
  start : Int32,
  opening : Bool,
) -> (Int32, Int32)? {
  let prefix = (if opening { "-----begin " } else { "-----end " })
    .iter()
    .to_array()
  let ending = "private key-----".iter().to_array()
  for index in start..<chars.length() {
    if ascii_match_at(chars, index, prefix) {
      for end in (index + prefix.length())..<chars.length() {
        if ascii_match_at(chars, end, ending) {
          return Some((index, end + ending.length()))
        }
      }
      return None
    }
  }
  None
}

///|
fn Progress::safe_message(self : Progress, text : String) -> String? {
  guard terminal_text(text) is Some(text) else { return None }
  let chars = text.iter().to_array()
  if chars.is_empty() {
    return Some("")
  }
  let output = @buffer.Buffer(size_hint=text.length())
  let mut position = 0
  while position < chars.length() {
    if self.private_key {
      if private_key_marker(chars, position, false) is Some((_, end)) {
        self.private_key = false
        position = end
      } else {
        self.details_truncated = true
        position = chars.length()
      }
    } else if private_key_marker(chars, position, true) is Some((start, end)) {
      output.write_string_utf8(character_text(chars, position, start))
      output.write_string_utf8("[private key redacted]")
      self.private_key = true
      position = end
      if private_key_marker(chars, position, false) is None {
        self.details_truncated = true
      }
    } else {
      output.write_string_utf8(character_text(chars, position, chars.length()))
      position = chars.length()
    }
  }
  if output.length() == 0 {
    return None
  }
  let known = redact_known_values(
    @utf8.decode_lossy(output.to_bytes()),
    self.secrets,
  )
  let mut safe = redact_known_values(redact_credentials(known), self.secrets)
  if safe.length() > 1024 {
    safe = safe[:1024].to_owned() + "… [truncated]"
    self.details_truncated = true
  }
  Some(safe)
}

///|
fn redact_known_values(text : String, secrets : Array[String]) -> String {
  let chars = text.iter().to_array()
  let values : Array[Array[Char]] = []
  for secret in secrets {
    if secret.length() <= text.length() {
      values.push(secret.iter().to_array())
    }
  }
  let result = @buffer.Buffer(size_hint=text.length())
  let mut i = 0
  while i < chars.length() {
    let mut matched = 0
    for index in 0..<values.length() {
      let value = values[index]
      let mut matches = value.length() > 0 &&
        i + value.length() <= chars.length()
      if matches {
        for j in 0..<value.length() {
          if chars[i + j] != value[j] {
            matches = false
            break
          }
        }
      }
      if matches &&
        (
          value.length() > 10 ||
          i + 10 > chars.length() ||
          character_text(chars, i, i + 10) != "[redacted]"
        ) {
        matched = value.length()
        break
      }
    }
    if matched > 0 {
      result.write_string_utf8("[redacted]")
      i += matched
    } else if i + 10 <= chars.length() &&
      character_text(chars, i, i + 10) == "[redacted]" {
      result.write_string_utf8("[redacted]")
      i += 10
    } else {
      result.write_char_utf8(chars[i])
      i += 1
    }
  }
  @utf8.decode_lossy(result.to_bytes())
}

///|
let progress_started : UInt64 = @env.now()

///|
fn seconds(milliseconds : UInt64) -> String {
  let tenths = milliseconds / 100UL
  "\{tenths / 10UL}.\{tenths % 10UL}s"
}

///|
fn progress_timing(started : UInt64) -> String {
  let now = @env.now()
  seconds(now - started) + ", elapsed " + seconds(now - progress_started)
}

///|
priv struct ProgressSink {
  lock : @async.Mutex
  mut available : Bool
}

///|
let progress_sink : ProgressSink = {
  lock: @async.Mutex::Mutex(),
  available: true,
}

///|
async fn progress_write(message : String) -> Unit {
  progress_sink.lock.acquire()
  defer progress_sink.lock.release()
  if !progress_sink.available {
    return
  }
  @stdio.stderr.write(message) catch {
    _ => {
      progress_sink.available = false
      save_diagnostic("progress-output", "failed", error_type="progress_io")
    }
  }
}

///|
async fn progress_message(message : String) -> Unit {
  let clock = @env.now() / 1000UL % 86400UL
  let pad = fn(value : UInt64) {
    if value < 10UL {
      "0" + value.to_string()
    } else {
      value.to_string()
    }
  }
  progress_write(
    pad(clock / 3600UL) +
    ":" +
    pad(clock / 60UL % 60UL) +
    ":" +
    pad(clock % 60UL) +
    " " +
    message +
    "\n",
  )
}

///|
fn devsy_progress_stage(stage : String) -> Bool {
  [
    "workspace-create", "workspace-create-full", "workspace-resume", "workspace-stop",
    "workspace-delete", "create-cleanup",
  ].contains(stage)
}

///|
fn phase_label(phase : String) -> String? {
  match phase {
    "cloning_repository" => Some("Clone repository")
    "resolving_config" => Some("Resolve devcontainer config")
    "initialize_command" => Some("Initialize")
    "preparing_devcontainer" => Some("Prepare devcontainer")
    "building_image" => Some("Build image")
    "starting_container" => Some("Start container")
    "injecting_agent" => Some("Install Devsy agent")
    "running_lifecycle_hook" => Some("Run lifecycle hooks")
    "waiting_for" => Some("Wait for container")
    "running_command" => Some("Run command")
    "configuring_workspace" => Some("Configure workspace")
    "configuring_ssh" => Some("Configure SSH")
    "starting_ssh_tunnel" => Some("Start SSH tunnel")
    "launching_ide" => Some("Prepare IDE")
    "stopping_workspace" => Some("Stop workspace")
    "deleting_workspace" => Some("Delete workspace")
    "rebuilding_workspace" => Some("Rebuild workspace")
    "resetting_workspace" => Some("Reset workspace")
    "importing_workspace" => Some("Import workspace")
    "ready" => Some("Workspace ready")
    "failed" => Some("Workspace failed")
    "installing_provider" => Some("Install provider")
    "resolving_options" => Some("Resolve provider options")
    "running_init" => Some("Initialize provider")
    _ => None
  }
}

///|
priv struct Progress {
  stage : String
  operations : Map[String, UInt64]
  builds : Map[String, String]
  secrets : Array[String]
  mut protection_incomplete : Bool
  recording : Bool
  context : Json?
  mut phase_count : Int32
  mut private_key : Bool
  mut classic_build : Bool
  recent : Array[String]
  failures : Array[String]
  unrecognized : Array[String]
  mut details_truncated : Bool
}

///|
fn sensitive_name(name : String) -> Bool {
  let normalized = name.to_lower().replace_all(old="-", new="_")
  if ["_enabled", "_disabled", "_count", "_mode", "_method"]
    .iter()
    .any(suffix => normalized.has_suffix(suffix)) {
    return false
  }
  let credential = credential_field(name, for_diagnostics=true)
  let name = name.to_lower()
  credential ||
  [
    "password", "passwd", "passphrase", "token", "secret", "api_key", "apikey", "auth",
    "credential", "private_key", "access_key", "storage_key", "cookie", "fnox_age_key",
  ]
  .iter()
  .any(marker => name.contains(marker))
}

///|
fn add_protected_secret(secrets : Array[String], value : String) -> Unit {
  if value == "" {
    return
  }
  let values = [value]
  for part in value.split("\n") {
    if part.trim() != "" && part.length() < value.length() {
      values.push(part.to_owned())
    }
  }
  for item in values {
    if !secrets.contains(item) {
      secrets.push(item)
    }
    let encoded = Json::string(item).stringify()
    let escaped = encoded[1:encoded.length() - 1].to_owned()
    if escaped != item && !secrets.contains(escaped) {
      secrets.push(escaped)
    }
  }
}

///|
fn Progress::new(
  stage : String,
  environment? : Map[String, String],
  recording_override? : Bool,
  context? : Json,
  protected_secrets? : Array[String],
  protection_incomplete~ : Bool = false,
) -> Progress {
  let secrets = []
  for name, value in environment.unwrap_or(@env.get_env_vars()) {
    if sensitive_name(name) && value != "" {
      // Multiline credentials must also be masked in line-oriented output.
      add_protected_secret(secrets, value)
    }
  }
  if protected_secrets is Some(values) {
    for value in values {
      add_protected_secret(secrets, value)
    }
  }
  secrets.sort_by((a, b) => b.length().compare(a.length()))
  {
    stage,
    operations: {},
    builds: {},
    secrets,
    protection_incomplete,
    recording: recording_override.unwrap_or(
      environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
      Some("0"),
    ),
    context,
    phase_count: 0,
    private_key: false,
    classic_build: false,
    recent: [],
    failures: [],
    unrecognized: [],
    details_truncated: false,
  }
}

///|
fn terminal_text(text : String) -> String? {
  let output = @buffer.Buffer(size_hint=256)
  let mut state = 0
  for c in text.iter() {
    match state {
      0 =>
        if c == '\u001b' {
          state = 1
        } else if c.to_int() < 32 && c != '\t' {
          return None
        } else {
          output.write_char_utf8(c)
        }
      1 =>
        if c == '[' {
          state = 2
        } else if c == ']' {
          state = 3
        } else {
          return None
        }
      2 => if c >= '@' && c <= '~' { state = 0 }
      3 => if c == '\u0007' { state = 0 } else if c == '\u001b' { state = 4 }
      _ => if c == '\\' { state = 0 } else { state = 3 }
    }
  }
  if state != 0 {
    None
  } else {
    Some(@utf8.decode_lossy(output.to_bytes()))
  }
}

///|
fn Progress::remember(
  self : Progress,
  message : String,
  warning~ : Bool,
) -> Unit {
  let lines = if warning { self.failures } else { self.recent }
  if lines.last() == Some(message) {
    return
  }
  if lines.length() == 8 {
    ignore(lines.remove(0))
    self.details_truncated = true
  }
  lines.push(message)
}

///|
fn Progress::failure_detail(self : Progress) -> String {
  let lines = self.failures +
  let lines = self.failures +
    self.recent.filter(line => !self.failures.contains(line))
  let detail = if lines.is_empty() {
    "no readable error message from subprocess"
  } else {
    lines.join("\n")
  }
  detail +
  (if self.details_truncated {
    "\n[error details incomplete or truncated]"
  } else {
    ""
  })
}

///|
fn Progress::remember_unrecognized(self : Progress, text : String) -> Unit {
  guard self.safe_message(text) is Some(safe) else {
    self.details_truncated = true
    return
  }
  if self.unrecognized.length() == 8 {
    ignore(self.unrecognized.remove(0))
    self.details_truncated = true
  }
  self.unrecognized.push(safe)
}

///|
fn Progress::remember_unrecognized_json(self : Progress, event : Json) -> Unit {
  let truncated : Ref[Bool] = { val: false, }
  let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
  if truncated.val {
    self.details_truncated = true
  }
  self.remember_unrecognized(safe)
}

///|
async fn Progress::status(self : Progress, event : Json) -> Unit {
  guard field(event, "phase") is Some(Json::String(phase)) &&
    phase_label(phase) is Some(label) &&
    field(event, "state") is Some(Json::String(state)) &&
    ["started", "succeeded", "failed", "skipped"].contains(state) else {
    return
  }
  if self.phase_count < 128 {
    self.phase_count += 1
    save_diagnostic(
      self.stage,
      state,
      phase~,
      error_type?=if state == "failed" { Some("backend_phase") } else { None },
      evidence?=self.context,
      evidence_stable_operation=true,
      protected_secrets=self.secrets,
      recording=self.recording,
    )
  } else if self.phase_count == 128 {
    self.phase_count += 1
    self.details_truncated = true
    save_diagnostic(
      self.stage,
      "diagnostics-truncated",
      error_type="phase_limit",
      phase~,
      evidence?=self.context,
      evidence_incomplete=true,
      evidence_stable_operation=true,
      protected_secrets=self.secrets,
      recording=self.recording,
    )
  }
  let key = ["pipeline", "operationId", "phase", "step"]
    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
    .join(":")
  if state == "started" {
    if self.operations.length() >= 256 {
      self.operations.clear()
    }
    self.operations.set(key, @env.now())
    progress_message(label + ": running…")
  } else {
    let duration = match field(event, "durationMs") {
      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
        Some(seconds(value.to_uint64()))
      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
    }
    self.operations.remove(key)
    let timing = duration.map(value => value + ", ").unwrap_or("") +
      "elapsed " +
      seconds(@env.now() - progress_started)
    progress_message(
      label +
      ": " +
      (if state == "succeeded" { "done" } else { state }) +
      " (" +
      timing +
      ")",
    )
  }
}

///|
fn classic_build_step(text : String) -> Bool {
  guard text.has_prefix("Step ") &&
    text[5:].split_once("/") is Some((step, rest)) &&
    rest.split_once(" ") is Some((total, detail)) else {
    return false
  }
  step.length() > 0 &&
  total.length() > 0 &&
  step.iter().all(c => c >= '0' && c <= '9') &&
  total.iter().all(c => c >= '0' && c <= '9') &&
  detail.trim().has_prefix(":")
}

///|
async fn Progress::message(
  self : Progress,
  text : String,
  debug~ : Bool,
  warning~ : Bool,
  emit~ : Bool = true,
) -> Unit {
  if self.protection_incomplete {
    self.details_truncated = true
    self.remember(
      "error detail unavailable because workspace protection values could not be read",
      warning=true,
    )
    return
  }
  for line in text.split("\n") {
    let text = line.trim().to_owned()
    if text == "" {
      continue
    }
    guard self.safe_message(text) is Some(safe) else {
      self.details_truncated = true
      continue
    }
    if !debug || warning {
      self.remember(safe, warning~)
    }
    if !emit {
      continue
    }
    if safe.has_prefix("#") {
      guard safe.split_once(" ") is Some((id, rest)) &&
        id.length() > 1 &&
        id[1:].iter().all(c => c >= '0' && c <= '9') else {
        continue
      }
      let detail = rest.trim().to_owned()
      guard detail.has_prefix("[") ||
        detail.has_prefix("DONE") ||
        detail.has_prefix("ERROR") ||
        detail.has_prefix("CACHED") else {
        continue
      }
      if detail.has_prefix("ERROR") && debug && !warning {
        self.remember(safe, warning=true)
      }
      if self.builds.get(id.to_owned()) == Some(detail) {
        continue
      }
      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
        self.builds.set(id.to_owned(), detail)
      }
      progress_message("Build " + id.to_owned() + ": " + detail)
    } else if classic_build_step(safe) {
      // Classic RUN output has no prefix. Only its own completion marker
      // ends this mode; phase events on another pipe can arrive ahead of it.
      self.classic_build = true
      progress_message("Build " + safe)
    } else if safe.has_prefix("Successfully built ") ||
      safe.has_prefix("Successfully tagged ") {
      self.classic_build = false
      progress_message("Build: " + safe)
    } else if self.classic_build && !warning {
      continue
    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
      progress_message(self.stage + ": " + safe)
    } else if !debug && safe.has_prefix("[credential") {
      progress_message(self.stage + ": " + safe)
    }
  }
}

///|
async fn Progress::line(
  self : Progress,
  line : String,
  statuses~ : Bool,
  messages~ : Bool,
) -> Unit {
  if line.trim() == "" {
    return
  }
  let event = @json.parse(line) catch { _ => Json::null() }
  if event != Json::null() {
    let protected_values : DiagnosticProtectedValues = {
      secrets: [],
      visited: 0,
      incomplete: false,
    }
    diagnostic_protected_values(event, protected_values, line, false)
    if protected_values.incomplete ||
      self.secrets.length() + protected_values.secrets.length() > 1024 {
      self.protection_incomplete = true
      self.details_truncated = true
    } else {
      for secret in protected_values.secrets {
        add_protected_secret(self.secrets, secret)
      }
      self.secrets.sort_by((a, b) => b.length().compare(a.length()))
    }
  }
  if field(event, "kind") == Some(Json::string("status")) {
    if field(event, "state") == Some(Json::string("failed")) &&
      field(event, "error") is Some(error) {
      let mut described = false
      for name in ["message", "hint"] {
        if field(error, name) is Some(Json::String(text)) {
          described = true
          self.message(
            text,
            debug=false,
            warning=true,
            emit=messages || statuses,
          )
        }
      }
      if !described {
        self.remember_unrecognized_json(event)
      }
    }
    if statuses || messages {
      self.status(event)
    }
    return
  }
  // Result envelopes and arbitrary structured responses are never log text.
  if field(event, "kind") == Some(Json::string("result")) ||
    field(event, "kind") == Some(Json::string("orca-env-devsy-server-exit")) {
    return
  }
  if event is Json::Object(_) {
    let kind = field(event, "kind")
    guard kind == None ||
      kind == Some(Json::string("log")) ||
      kind == Some(Json::string("error")) else {
      self.remember_unrecognized_json(event)
      return
    }
    let message = match field(event, "msg") {
      Some(value) => Some(value)
      None =>
        match field(event, "message") {
          Some(value) => Some(value)
          None =>
            match field(event, "error") {
              Some(Json::Object(_) as value) => field(value, "message")
              value => value
            }
        }
    }
    guard message is Some(Json::String(text)) else {
      self.remember_unrecognized_json(event)
      return
    }
    let level = field(event, "level")
    self.message(
      text,
      debug=level == Some(Json::string("debug")) ||
        level == Some(Json::string("trace")),
      warning=kind == Some(Json::string("error")) ||
        level == Some(Json::string("warn")) ||
        level == Some(Json::string("error")),
      emit=messages || (statuses && kind != None),
    )
  } else {
    if event != Json::null() {
      self.remember_unrecognized_json(event)
      return
    }
    // Malformed JSON and binary output are not a safe free-text fallback.
    let text = line.trim().to_owned()
    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
      self.message(text, debug=false, warning=true, emit=messages)
      return
    }
    if text.has_prefix("{") || text.has_prefix("[") {
      self.details_truncated = true
      self.remember_unrecognized(text)
      return
    }
    self.message(
      text,
      debug=text.contains(" DEBUG ") ||
        text.contains(" TRACE ") ||
        text.has_prefix("DEBUG ") ||
        text.has_prefix("TRACE "),
      warning=text.contains(" WARN ") ||
        text.contains(" ERROR ") ||
        text.has_prefix("WARN ") ||
        text.has_prefix("ERROR "),
      emit=messages,
    )
  }
}

