///|
fn ascii_match_at(
  chars : Array[Char],
  offset : Int32,
  pattern : Array[Char],
) -> Bool {
  if offset + pattern.length() > chars.length() {
    return false
  }
  for index in 0..<pattern.length() {
    let value = chars[offset + index]
    let lower = if value >= 'A' && value <= 'Z' {
      (value.to_int() + 32).unsafe_to_char()
    } else {
      value
    }
    if lower != pattern[index] {
      return false
    }
  }
  true
}

///|
fn private_key_marker(
  chars : Array[Char],
  start : Int32,
  opening : Bool,
) -> (Int32, Int32)? {
  let prefix = (if opening { "-----begin " } else { "-----end " })
    .iter()
    .to_array()
  let ending = "private key-----".iter().to_array()
  for index in start..<chars.length() {
    if ascii_match_at(chars, index, prefix) {
      for end in (index + prefix.length())..<chars.length() {
        if ascii_match_at(chars, end, ending) {
          return Some((index, end + ending.length()))
        }
      }
      return None
    }
  }
  None
}

///|
fn Progress::safe_message(self : Progress, text : String) -> String? {
  guard terminal_text(text) is Some(text) else { return None }
  let chars = text.iter().to_array()
  if chars.is_empty() {
    return Some("")
  }
  let output = @buffer.Buffer(size_hint=text.length())
  let mut position = 0
  while position < chars.length() {
    if self.private_key {
      if private_key_marker(chars, position, false) is Some((_, end)) {
        self.private_key = false
        position = end
      } else {
        self.details_truncated = true
        position = chars.length()
      }
    } else if private_key_marker(chars, position, true) is Some((start, end)) {
      output.write_string_utf8(character_text(chars, position, start))
      output.write_string_utf8("[private key redacted]")
      self.private_key = true
      position = end
      if private_key_marker(chars, position, false) is None {
        self.details_truncated = true
      }
    } else {
      output.write_string_utf8(character_text(chars, position, chars.length()))
      position = chars.length()
    }
  }
  if output.length() == 0 {
    return None
  }
  let known = redact_known_values(
    @utf8.decode_lossy(output.to_bytes()),
    self.secrets,
  )
  let mut safe = redact_known_values(redact_credentials(known), self.secrets)
  if safe.length() > 1024 {
    safe = safe[:1024].to_owned() + "… [truncated]"
    self.details_truncated = true
  }
  Some(safe)
}

///|
fn redact_known_values(text : String, secrets : Array[String]) -> String {
  let chars = text.iter().to_array()
  let values : Array[Array[Char]] = []
  for secret in secrets {
    if secret.length() <= text.length() {
      values.push(secret.iter().to_array())
    }
  }
  let result = @buffer.Buffer(size_hint=text.length())
  let mut i = 0
  while i < chars.length() {
    let mut matched = 0
    for index in 0..<values.length() {
      let value = values[index]
      let mut matches = value.length() > 0 &&
        i + value.length() <= chars.length()
      if matches {
        for j in 0..<value.length() {
          if chars[i + j] != value[j] {
            matches = false
            break
          }
        }
      }
      if matches &&
        (
          value.length() > 10 ||
          i + 10 > chars.length() ||
          character_text(chars, i, i + 10) != "[redacted]"
        ) {
        matched = value.length()
        break
      }
    }
    if matched > 0 {
      result.write_string_utf8("[redacted]")
      i += matched
    } else if i + 10 <= chars.length() &&
      character_text(chars, i, i + 10) == "[redacted]" {
      result.write_string_utf8("[redacted]")
      i += 10
    } else {
      result.write_char_utf8(chars[i])
      i += 1
    }
  }
