///|
async fn Progress::stderr_line(
  self : Progress,
  line : String,
  statuses~ : Bool,
  messages~ : Bool,
) -> Unit {
  let event = @json.parse(line) catch { _ => Json::null() }
  if event != Json::null() {
    self.line(line, statuses~, messages~)
    let truncated : Ref[Bool] = { val: false, }
    let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
    if truncated.val {
      self.details_truncated = true
    }
    self.message(safe, debug=false, warning=true, emit=false)
    return
  } else if event == Json::null() &&
    (line.trim().has_prefix("[") || line.trim().has_prefix("{")) {
    self.details_truncated = true
    self.message(line, debug=false, warning=true, emit=false)
    return
  }
  self.line(line, statuses~, messages~)
}

///|
async fn Progress::read_output(
  self : Progress,
  reader : @process.ReadFromProcess,
  capture~ : Bool,
  statuses~ : Bool = false,
  messages~ : Bool = false,
  raw_messages~ : Bool = false,
) -> String {
  let output = @buffer.Buffer(size_hint=4096)
  let pending = @buffer.Buffer(size_hint=4096)
  let mut oversized = false
  let mut tail = ""
  while reader.read_some(max_len=4096) is Some(chunk) {
    if capture {
      output.write_bytes(chunk)
    } else {
      tail += @utf8.decode_lossy(chunk)
      if tail.length() > 8192 {
        tail = tail[tail.length() - 8192:].to_owned()
      }
    }
    for byte in chunk {
      if byte == b'\n' || byte == b'\r' {
        if !oversized && pending.length() > 0 {
          let line = @utf8.decode(pending.to_bytes()) catch {
            _ => {
              self.details_truncated = true
              ""
            }
          }
          if raw_messages {
            self.message(line, debug=false, warning=true, emit=false)
          } else if capture {
            self.line(line, statuses~, messages~)
          } else {
            self.stderr_line(line, statuses~, messages~)
          }
        }
        pending.reset()
        oversized = false
      } else if !oversized {
        if pending.length() == 65536 {
          pending.reset()
          oversized = true
          self.details_truncated = true
        } else {
          pending.write_byte(byte)
        }
      }
    }
  }
  if !oversized && pending.length() > 0 {
    let line = @utf8.decode(pending.to_bytes()) catch {
      _ => {
        self.details_truncated = true
        ""
      }
    }
    let masked = diagnostic_partial_secret(line, self.secrets)
    if masked != line {
      self.details_truncated = true
    }
    if raw_messages {
      self.message(masked, debug=false, warning=true, emit=false)
    } else if capture {
      self.line(masked, statuses~, messages~)
    } else {
      self.stderr_line(masked, statuses~, messages~)
    }
  }
  if capture {
    @utf8.decode(output.to_bytes())
  } else {
    tail
  }
}

///|
async fn workspace_program(state : Json, program : String) -> String {
  let cwd = workspace_directory(state).unwrap_or(
    @env.current_dir().unwrap_or("/"),
  )
  if program.has_prefix("/") {
    return program
  }
  if program.contains("/") {
    return cwd + "/" + program
  }
  let path = field(field(state, "devsyEnv").unwrap_or(Json::null()), "PATH")
  let path = match path {
    Some(Json::String(value)) => value
    _ => "/usr/bin:/bin"
  }
  let mut fallback = None
  for directory in path.split(":") {
    let directory = if directory.has_prefix("/") {
      directory.to_owned()
    } else {
      cwd + "/" + directory.to_owned()
    }
    let candidate = directory + "/" + program
    if fallback is None {
      fallback = Some(candidate)
    }
    if transport_access(@utf8.encode(candidate + "\u0000"), 1) == 0 &&
      @fs.kind(candidate) != @fs.FileKind::Directory {
      return candidate
    }
  }
  fallback.unwrap_or(cwd + "/" + program)
}

///|
async fn devsy_result(
  state : Json,
  args : Array[String],
  stage : String,
) -> (Int32, String, String) {
  let environment = workspace_environment(state)
  let protected_values = workspace_output_secrets(state)
  if protected_values is None {
    suppress_workspace_recording(state)
  }
  let invocation = saved_command(state)
  let logging = if devsy_progress_stage(stage) {
    ["--log-level", "debug", "--log-output", "json"]
  } else {
    []
  }
  let result = command_result(
    workspace_program(state, invocation[0]),
    invocation[1:].to_owned() + devsy_args(state) + logging + args,
    stage,
    environment~,
    recording_override=state_recording(state),
    protected_secrets?=protected_values,
    protection_incomplete=protected_values is None,
    cwd?=workspace_directory(state).map(path => path[:]),
    target?=field(state, "workspaceId").map(value => {
      if value is Json::String(name) {
        name
      } else {
        ""
      }
    }),
  )
  result
}

