///|
async fn initialize_orca_settings(state : Json) -> Unit {
  let mut phase = "host"
  save_diagnostic(
    "orca-settings",
    "started",
    recording=operation_recording(state),
  )
  progress_message("orca-settings: running…")
  @async.with_timeout(30000, async fn() {
    let payload = host_orca_settings()
    phase = "remote"
    let script = "unset NODE_OPTIONS NODE_REPL_EXTERNAL_MODULE; ORCA_USER_DATA_PATH=/worktrees/.orca ELECTRON_RUN_AS_NODE=1 \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" -e " +
      quote(orca_settings_script()) +
      " -- import \"$HOME/.local/share/orca-env-devsy/orca/current/resources\" /worktrees/.orca"
    let env = workspace_environment(state)
    let protected_values = workspace_output_secrets(state)
    if protected_values is None {
      suppress_workspace_recording(state)
    }
    ignore(
      settings_process(
        workspace_program(state, "ssh"),
        mux_ssh_args(state) + [script],
        environment=env,
        input=payload,
        protected_secrets?=protected_values,
        protection_incomplete=protected_values is None,
      ),
    )
  }) catch {
    SettingsProcessError(helper_phase, code, status, detail) => {
      save_diagnostic(
        "orca-settings",
        "failed",
        phase=phase + "/" + helper_phase,
        error_type=code,
        exit_code=status,
        error_message?=detail,
        recording=operation_recording(state),
      )
      raise AdapterError(
        "Orca settings transfer failed (exit \{status}, " +
        phase +
        "/" +
        helper_phase +
        ": " +
        code +
        ")",
      )
    }
    @async.TimeoutError as error => {
      save_diagnostic(
        "orca-settings",
        "timeout",
        phase~,
        error_type="timeout",
        recording=operation_recording(state),
      )
      raise error
    }
    error => {
      let detail = diagnostic_error(
        error,
        environment=workspace_environment(state),
      )
      save_diagnostic(
        "orca-settings",
        if @async.is_being_cancelled() {
          "cancelled"
        } else {
          "failed"
        },
        phase~,
        error_type=if error is AdapterError(_) {
          "settings_source"
        } else {
          "settings_transfer"
        },
        error_message=detail,
        recording=operation_recording(state),
      )
      raise error
    }
  }
  save_diagnostic(
    "orca-settings",
    "success",
    phase~,
    recording=operation_recording(state),
  )
