async fn devsy(
  state : Json,
  args : Array[String],
  stage : String,
  extra_secrets? : Array[String],
  extra_protection_incomplete~ : Bool = false,
) -> String {
  let (status, output, detail) = devsy_result(
    state,
    args,
    stage,
    extra_secrets?,
    extra_protection_incomplete~,
  )
  guard status == 0 else {
    raise AdapterError(command_failure(stage, status, detail))
  }
  output
  errdefer (if !attempt_complete {
    save_diagnostic(
      "create-attempt",
      "failed",
      error_type="create_stage_failed",
    )
  })
  let document = read_document(environment("ORCA_REPO_PATH") + "/orca.yaml")
  let id = environment("ORCA_RECIPE_ID")
  let (config, arg_sources, option_sources) = resolve_settings_with_sources(
    document,
    id,
    name => @env.get_env_var(name),
  )
  let (arguments, argument_secrets, arguments_incomplete) = up_arguments_evidence(
    config.up_args,
    arg_sources,
  )
  save_diagnostic(
    "create-arguments",
    "selected",
    evidence=arguments,
    evidence_incomplete=arguments_incomplete,
    protected_secrets=argument_secrets,
  )
  save_diagnostic(
    "create-options",
    "selected",
    evidence=if arguments_incomplete {
      { "reason": "protected_value_limit" }
    } else {
      option_sources
    },
    evidence_incomplete=arguments_incomplete,
    protected_secrets=argument_secrets,
  )
  save_diagnostic("idle-configuration", "selected", evidence={
    "enabled": config.idle_timeout_ms is Some(_),
    "timeoutMs": config.idle_timeout_ms
    .map(n => Json::number(n.to_double()))
    .unwrap_or(Json::null()),

