///|
async test "Codex delivery distinguishes protected existing auth from a symlink" {
  for mode in ["unmanaged", "symlink"] {
    let (directory, env) = fixture()
    defer cleanup_fixture(directory)
    @fs.mkdir(directory + "/.codex")
    let auth = synthetic_auth(4102444800)
    @fs.write_file(directory + "/.codex/auth.json", auth.stringify())
    @fs.mkdir(directory + "/remote-codex")
    if mode == "unmanaged" {
      @fs.write_file(directory + "/remote-codex/auth.json", "existing")
    } else {
      @fs.symlink(
        directory + "/remote-codex/auth.json",
        target=directory + "/remote-codex/target",
      )
    }
    env.set("OPENAI_API_KEY", "")
    env.set("CODEX_ACCESS_TOKEN", "")
    @fs.write_file(
      directory + "/orca.yaml",
      "devsy: {connection: ssh, buildRef: refs/heads/main, addons: {codexAuth: true}}\nenvironmentRecipes: [{id: test}]\n",
    )
    @fs.rename(directory + "/bin/ssh", directory + "/bin/ssh-original")
    let wrapper =
      #|#!/bin/sh
      #|case "$*" in
      #|  *'auth.XXXXXX'*) for arg in "$@"; do script=$arg; done; CODEX_HOME="$HOME/remote-codex" exec /bin/sh -c "$script" ;;
      #|esac
      #|exec "$HOME/bin/ssh-original" "$@"
    @fs.write_file(directory + "/bin/ssh", wrapper + "\n", permission=0o700)
    let (status, output, errors) = invoke("create", env, directory)
    assert_eq(status, 0, msg=errors)
    let warnings = fixture_events(directory).filter(event => {
      field(event, "stage") == Some(Json::string("codex-auth")) &&
      field(event, "status") == Some(Json::string("warning"))
    })
    assert_eq(warnings.length(), 1)
    let detail = required(warnings[0], "errorMessage")
    assert_true(
      detail.contains(
        if mode == "unmanaged" {
          "not managed"
        } else {
          "symbolic link"
        },
      ),
      msg=detail,
    )
    assert_false(detail.contains("fixture-refresh"))
    assert_false(
      detail.contains(required(field(auth, "tokens").unwrap(), "access_token")),
    )
    let payload : Json = {
      "schemaVersion": 1,
      "recipeResult": @json.parse(output),
    }
    let (destroyed, _, destroy_error) = invoke(
      "destroy",
      env,
      directory,
      payload~,
    )
    assert_eq(destroyed, 0, msg=destroy_error)
  }
}

