///|
test "credential terminology and ordinary URLs remain readable" {
  let progress = Progress::new("test")
  for
    message in [
      "get credentials: credential helper executable not found", "token exchange failed: authorization denied by provider",
      "secret store is locked; password authentication is disabled", "configure SSH_INJECT_GIT_CREDENTIALS: invalid option",
      "request failed: https://example.com/api?region=apne1&page=2", "SSH key discovery failed in /home/developer/.ssh",
      "日本語の認証エラー: credential helper not found",
    ] {
    assert_eq(progress.safe_message(message), Some(message))
  }
}

///|
test "credential values are masked without discarding surrounding causes" {
  let progress = Progress::new("test")
  for
    value in [
      "ERROR Authorization: Bearer fixture-value", "request failed: Authorization: Bearer fixture-value",
      "request failed with token: fixture-value", "error --token fixture-value",
      "error --api-key=REDACTED, "error --password 'fixture-value with spaces'",
      "Cookie=\"fixture-value\"; session=second-value", "https://example.com/path?access%5Ftoken=fixture-value&region=apne1",
      "https://example.com/path?%61ccess_token=fixture-value&region=apne1", "token=fixture-value",
      "token = fixture-value", "api-key:fixture-value", "X-API-Key: fixture-value",
      "Authorization: Bearer fixture-value", "Authorization: Basic fixture-value",
      "Bearer fixture-value", "Basic fixture-value", "https://example.com/callback?code=fixture-value&state=next",
      "credential: fixture-value", "Cookie=fixture-value; session=second-value",
      "REDACTED", "CUSTOM_ACCESS_KEY=fixture-value", "--secretAccessKey fixture-value",
      "secretAccessKey=REDACTED, "Set-Cookie: session=fixture-value", "REDACTED",
      "https://example.com/path?key=fixture-value&region=apne1", "key=sk-proj-fixture-value",
      "key:sk-proj-fixture-value", "key\tsk-proj-fixture-value", "github_pat_fixture-value",
      "ghp_fixture-value", "eyJhbGci.fixture-value.signature", "{\"access_token\":\"fixture-value\",\"cause\":\"connection refused\"}",
      "password='fixture-value with spaces'", "token=\"fixture-value \\\" escaped\"",
    ] {
    let message = "cause before; " + value + "; cause after"
    let safe = progress.safe_message(message).unwrap()
    assert_false(safe.contains("fixture-value"), msg=safe)
    assert_false(safe.contains("second-value"), msg=safe)
    assert_true(safe.has_prefix("cause before; "), msg=safe)
    if !value.has_prefix("Cookie") && !value.has_prefix("Set-Cookie") {
      assert_true(safe.has_suffix("; cause after"), msg=safe)
    }
    assert_eq(progress.safe_message(safe), Some(safe))
  }
}

///|
test "short secrets preserve existing redaction markers" {
  let progress = Progress::new("test", environment={ "ACCESS_TOKEN": "a" })
  let first = progress.safe_message("token=fixture-value and a").unwrap()
  assert_false(first.contains("[red[redacted]cted]"), msg=first)
  assert_eq(progress.safe_message(first), Some(first))
}

///|
test "known secrets that start with a redaction marker are fully masked" {
  let secret = "[redacted]fixture-credential"
  let progress = Progress::new("test", environment={
    "AZURE_STORAGE_KEY": secret,
  })
  for
    text in [
      "failure " + secret,
      "token=" + secret,
      "https://example.com/?token=" + secret,
    ] {
    let safe = progress.safe_message(text).unwrap()
    assert_false(safe.contains("fixture-credential"), msg=safe)
    assert_eq(progress.safe_message(safe), Some(safe))
  }
}

///|
test "private key redaction preserves surrounding causes across boundaries" {
  let progress = Progress::new("test")
  let line = "日本語 /workspace ENOSPC -----BEGIN " +
    "PRIVATE KEY-----fixture-key-body-----END " +
    "PRIVATE KEY----- while writing"
  let safe = progress.safe_message(line).unwrap()
  assert_true(safe.contains("日本語 /workspace ENOSPC"), msg=safe)
  assert_true(safe.contains("while writing"), msg=safe)
  assert_false(safe.contains("fixture-key-body"), msg=safe)
  assert_false(progress.details_truncated)
  let start = progress
    .safe_message(
      "permission denied -----BEGIN " + "OPENSSH PRIVATE KEY-----fixture-head",
    )
    .unwrap()
  assert_true(start.contains("permission denied"), msg=start)
  assert_false(start.contains("fixture-head"), msg=start)
  assert_true(progress.safe_message("fixture-middle") is None)
  let finish = progress
    .safe_message(
      "fixture-tail-----END " + "OPENSSH PRIVATE KEY----- at /fixture/path",
    )
    .unwrap()
  assert_true(finish.contains("at /fixture/path"), msg=finish)
  assert_false(finish.contains("fixture-tail"), msg=finish)
  assert_true(progress.details_truncated)
}

///|
test "input validation retains noncredential flags and ordinary callback values" {
  for name in ["AUTH_ENABLED", "TOKEN_COUNT", "ACCESS_KEY_MODE"] {
    assert_false(credential_field(name))
    assert_false(credential_field(name, for_diagnostics=true))
