///|
fn Progress::remember_unrecognized(self : Progress, text : String) -> Unit {
  if self.protection_incomplete {
    self.details_truncated = true
    let unavailable = "error detail unavailable because workspace protection values could not be read"
    if !self.unrecognized.contains(unavailable) {
      self.unrecognized.push(unavailable)
    }
    return
  }
  guard self.safe_message(text) is Some(safe) else {
    self.details_truncated = true
    return
  }
  if self.unrecognized.length() == 8 {
    ignore(self.unrecognized.remove(0))
    self.details_truncated = true
  }
  self.unrecognized.push(safe)
}

///|
fn Progress::remember_unrecognized_json(self : Progress, event : Json) -> Unit {
  if self.protection_incomplete {
    self.remember_unrecognized("")
    return
  }
  let truncated : Ref[Bool] = { val: false, }
  let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
  if truncated.val {
    self.details_truncated = true
  }
  self.remember_unrecognized(safe)
}

///|
async fn Progress::status(self : Progress, event : Json) -> Unit {
  guard field(event, "phase") is Some(Json::String(phase)) &&
    phase_label(phase) is Some(label) &&
    field(event, "state") is Some(Json::String(state)) &&
    ["started", "succeeded", "failed", "skipped"].contains(state) else {
    return
  }
  if self.phase_count < 128 {
    self.phase_count += 1
    save_diagnostic(
      self.stage,
      state,
      phase~,
      error_type?=if state == "failed" { Some("backend_phase") } else { None },
      evidence?=self.context,
      evidence_stable_operation=true,
      protected_secrets=self.secrets,
      recording=self.recording,
    )
  } else if self.phase_count == 128 {
    self.phase_count += 1
    self.details_truncated = true
    save_diagnostic(
      self.stage,
      "diagnostics-truncated",
      error_type="phase_limit",
      phase~,
      evidence?=self.context,
      evidence_incomplete=true,
      evidence_stable_operation=true,
      protected_secrets=self.secrets,
      recording=self.recording,
    )
  }
  let key = ["pipeline", "operationId", "phase", "step"]
    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
    .join(":")
  if state == "started" {
    if self.operations.length() >= 256 {
      self.operations.clear()
    }
    self.operations.set(key, @env.now())
    progress_message(label + ": running…")
  } else {
    let duration = match field(event, "durationMs") {
      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
        Some(seconds(value.to_uint64()))
      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
    }
    self.operations.remove(key)
    let timing = duration.map(value => value + ", ").unwrap_or("") +
      "elapsed " +
      seconds(@env.now() - progress_started)
    progress_message(
      label +
      ": " +
      (if state == "succeeded" { "done" } else { state }) +
      " (" +
      timing +
      ")",
    )
  }
}

///|
fn classic_build_step(text : String) -> Bool {
  guard text.has_prefix("Step ") &&
    text[5:].split_once("/") is Some((step, rest)) &&
    rest.split_once(" ") is Some((total, detail)) else {
    return false
  }
  step.length() > 0 &&
  total.length() > 0 &&
    if byte == b'\n' {
      let response = @json.parse(@utf8.decode(Bytes::from_array(bytes)))
      bytes.clear()
      if field(response, "id") == Some(Json::number(id.to_double())) {
        if field(response, "error") is Some(error) {
          let code = match field(error, "code") {
            Some(Json::Number(value, ..)) => " code " + value.to_string()
            _ => ""
          }
          let message = match field(error, "message") {
            Some(Json::String(value)) =>
              ": " + diagnostic_text(value, protected_secrets=secrets)
            _ => ""
          }
          raise AdapterError("Codex refresh RPC \{id} failed" + code + message)
        }
        guard field(response, "result") != None else {
          raise AdapterError("Codex refresh RPC \{id} returned no result")
        }
        return
      }
    } else {
      bytes.push(byte)
    }
  }
}

///|
async fn refresh_codex(home : String, secrets : Array[String]) -> Unit {
  let (reader, output) = @process.read_from_process()
  defer reader.close()
  let (input, writer) = @process.write_to_process()
  defer writer.close()
  let (errors, stderr) = @process.read_from_process()
  defer errors.close()
  let captured = @buffer.Buffer(size_hint=1024)
  let incomplete : Ref[Bool] = { val: false, }
  let finished : Ref[Bool] = { val: false, }
  let failure = try {
    @async.with_task_group(async fn(group) {
      ignore(
        @process.spawn(
          group,
          "codex",
          ["app-server", "--stdio"],
          extra_env={ "CODEX_HOME": home },
          stdin=input,
          stdout=output,
          stderr~,
          no_wait=true,
        ),
      )
      group.spawn_bg(no_wait=true, async fn() {
        while errors.read_some(max_len=4096) is Some(chunk) {
          let remaining = 8192 - captured.length()
          let count = if chunk.length() < remaining {
            chunk.length()
          } else {
            remaining
          }
          if count > 0 {
            captured.write_bytes(chunk[:count])
          }
          if count < chunk.length() {
            incomplete.val = true
          }
        }
        finished.val = true
      })
      let initialize : Json = {
        "id": 1,
        "method": "initialize",
        "params": {
          "clientInfo": { "name": "orca-env-devsy", "version": version },
        },
      }
      writer.write(initialize.stringify() + "\n")
      codex_rpc_response(reader, 1, secrets)
      writer.write("{\"method\":\"initialized\"}\n")
      writer.write(
        "{\"id\":2,\"method\":\"account/read\",\"params\":{\"refreshToken\":true}}\n",
      )
      codex_rpc_response(reader, 2, secrets)
    })
    None
  } catch {
    error => Some(error)
  }
  if failure is Some(error) {
    if @async.is_being_cancelled() {
      raise error
    }
    let protected_input : Json = { "access_token": secrets }
    let detail = diagnostic_output(
      captured.to_bytes(),
      @env.get_env_vars(),
      protected_input=protected_input.stringify(),
      omitted=incomplete.val || !finished.val,
    )
    raise AdapterError(
      diagnostic_error(error) +
      detail
      .map(value => "\nCodex app-server stderr: " + value)
      .unwrap_or(
        if finished.val {
          ""
        } else {
          "\n[Codex app-server stderr incomplete]"
        },
      ),
    )
  }
}

///|
async fn codex_credentials(home : String, recording~ : Bool) -> CodexAuth {
  let initial = read_codex_auth(home)
  if initial.expiry - @env.now().to_double() / 1000 >= 604800 {
    return initial
  }
  let lock = @fs.open(
    home + "/.orca-env-devsy-refresh.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  while !lock.try_lock(Exclusive) {
    @async.sleep(100)
  }
  let before = read_codex_auth(home)
  if before.expiry - @env.now().to_double() / 1000 >= 604800 {
    return before
  }
  let mut phase = "refresh"
  try {
    refresh_codex(home, before.secrets)
    phase = "verify"
    let after = read_codex_auth(home)
    guard after.access != before.access && after.expiry > before.expiry else {
      raise AdapterError("Codex refresh not persisted")
    }
    save_diagnostic("codex-refresh", "success", recording~)
  } catch {
    error => {
      progress_write(

          protected_secrets?=secrets,
          environment=workspace_environment(state),
          recording=state_recording(state) && secrets is Some(_),
        )
      }
      (
        in_scope,
        in_scope && field(value, "uid") == field(state, "workspaceUid"),
      )
    }
  }
}

