fn resolved_setting(value : String?, source : String?) -> Json {
  let result : Json = {
    "state": match value {
      None => "unset"
      Some("") => "empty"
      _ => "set"
    },
    "source": source.map(Json::string).unwrap_or(Json::string("unset")),
  }
  if value is Some(text) && text != "" {
    set_field(result, "value", Json::string(text))
  }
  result
}

