///|
async fn git_relay_status(
  directory : String,
  status : String,
  recording? : Bool,
) -> Unit {
  @fs.write_file(directory + "/git-status", status, permission=0o600) catch {
    _ =>
      save_diagnostic(
        "git-relay-recording",
        "degraded",
        tunnel_directory=directory,
        recording?,
      )
  }
  save_diagnostic(
    "git-relay",
    status,
    error_type?=if status == "unavailable" {
      Some("readiness_unavailable")
    } else {
      None
    },
    tunnel_directory=directory,
    recording?,
  )
}

///|
async fn git_forwarding_enabled(state : Json) -> Bool {
  let options = @json.parse(
    devsy(
      state,
      ["--result-format", "json", "context", "get"],
      "git-relay-options",
    ),
  )
  let option = field(options, "SSH_INJECT_GIT_CREDENTIALS").unwrap_or(
    Json::null(),
  )
  match field(option, "value") {
    Some(Json::String("false")) => false
    Some(Json::String("true")) => true
    _ => field(option, "default") != Some(Json::string("false"))
  }
}

///|
priv enum RelayReadiness {
  Ready
  WaitingForGitHelper
  Retry(String)
  Unsupported
}

///|
async fn relay_readiness(
  state : Json,
  directory : String,
  git_enabled : Bool,
  record_success~ : Bool,
) -> RelayReadiness {
  let script =
    #|# orca-relay-readiness
    #|set -eu
    #|curl --disable --noproxy '*' --silent --max-time 1 --max-filesize 4096 --write-out '\n%{http_code}' http://localhost:12049/ready
  let started = @env.now()
  let environment = workspace_environment(state)
  let pairing = if state_recording(state) {
    workspace_pairing_secrets(state)
  } else {
    Some([])
  }
  if pairing is None {
    suppress_workspace_recording(state)
  }
  let pairing_secrets = pairing.unwrap_or([])
  let evidence : Json = { "gitEnabled": git_enabled }
  let mut phase = "readiness"
  let mut exit_code = None
  let mut error_detail = None
  let mut cancelled = false
  let mut stderr_capture = DiagnosticCapture::new(8192)
  let result = @async.with_timeout(3000, async fn() {
    let (code, output, output_truncated, stderr, stderr_truncated) = diagnostic_process_output(
      workspace_program(state, "ssh"),
      ssh_mux_options(state, directory) + [script],
      environment~,
      cwd?=workspace_directory(state).map(path => path[:]),
      stdout_limit=8192,
      stderr_limit=8192,
      stderr_capture~,
    )
    exit_code = Some(code)
    if code != 0 {
      error_detail = diagnostic_output(
        stderr,
        environment,
        protected_secrets=pairing_secrets,
        omitted=stderr_truncated,
      )
      if output_truncated {
        error_detail = Some(incomplete_diagnostic_detail(error_detail))
      }
      return RelayReadiness::Retry(
        if code == 28 {
          "http_timeout"
        } else {
          "transport_error"
        },
      )
    }
    if output_truncated {
      error_detail = Some(
        "Readiness response exceeds the capture limit\n[error details incomplete or truncated]",
      )
      return RelayReadiness::Retry("response_too_large")
    }
    let text = @utf8.decode(output).trim().to_owned()
    let lines = text.split("\n").to_array()
    let status = lines.last().unwrap_or("").to_owned()
    if status.length() == 3 && status.iter().all(c => c >= '0' && c <= '9') {
      set_field(evidence, "httpStatus", Json::string(status))
    }
    if status == "404" {
      return RelayReadiness::Unsupported
    }
    if status != "200" {
      return RelayReadiness::Retry(
        if status == "503" {
          "http_503"
        } else {
          "http_error"
        },
      )
    }
    let body = text[:text.length() - status.length()]
      .to_owned()
      .trim()
      .to_owned()
    phase = "response"
    let value = @json.parse(body) catch {
      error => {
        error_detail = Some(diagnostic_error(error, environment~))
        return RelayReadiness::Retry("schema_invalid")
      }
    }
    let response_version : Json = match field(value, "version") {
      None => { "state": "missing" }
      Some(Json::Number(number, ..)) => { "state": "number", "value": number }
      Some(Json::String(_)) => { "state": "invalid_type", "type": "string" }
      Some(item) if item == Json::boolean(true) || item == Json::boolean(false) =>
        { "state": "invalid_type", "type": "boolean" }
      Some(Json::Null) => { "state": "invalid_type", "type": "null" }
      Some(Json::Array(_)) => { "state": "invalid_type", "type": "array" }
      Some(Json::Object(_)) => { "state": "invalid_type", "type": "object" }
      _ => { "state": "invalid_type", "type": "unknown" }
    }
    set_field(evidence, "responseVersion", response_version)
    if field(value, "version") != Some(Json::number(1)) {
      return RelayReadiness::Unsupported
    }
    if field(value, "owner") != field(state, "user") {
      let progress = Progress::new("relay-probe", environment~)
      for (name, source) in [("expectedOwner", state), ("observedOwner", value)] {
        let key = if name == "expectedOwner" { "user" } else { "owner" }
        if field(source, key) is Some(Json::String(owner)) {
          set_field(
            evidence,
            name,
            Json::string(
              progress.safe_message(owner).unwrap_or("[unavailable]"),
            ),
          )
        }
      }
      return RelayReadiness::Retry("owner_mismatch")
    }
    for name in ["host_owner", "instance"] {
      if field(value, name) is Some(Json::String(value)) && value != "" {
        continue
      }
      set_field(evidence, "invalidField", Json::string(name))
      return RelayReadiness::Retry("schema_invalid")
    }
    if git_enabled {
      phase = "git-helper"
      stderr_capture = DiagnosticCapture::new(8192)
      let helper = "git config --global --get credential.helper | grep -F 'internal agent git-credentials' >/dev/null"
      let (code, _, output_truncated, stderr, stderr_truncated) = diagnostic_process_output(
        workspace_program(state, "ssh"),
        ssh_mux_options(state, directory) + [helper],
        environment~,
        cwd?=workspace_directory(state).map(path => path[:]),
        stdout_limit=0,
        stderr_limit=8192,
        stderr_capture~,
      )
      exit_code = Some(code)
      if code == 1 {
        error_detail = diagnostic_output(
          stderr,
          environment,
          protected_secrets=pairing_secrets,
          omitted=stderr_truncated,
        )
        if output_truncated {
          error_detail = Some(incomplete_diagnostic_detail(error_detail))
        }
        return RelayReadiness::WaitingForGitHelper
      }
      if code != 0 {
        error_detail = diagnostic_output(
          stderr,
          environment,
          protected_secrets=pairing_secrets,
          omitted=stderr_truncated,
        )
        if output_truncated {
          error_detail = Some(incomplete_diagnostic_detail(error_detail))

///|
fn Progress::remember(
  self : Progress,
  message : String,
  warning~ : Bool,
) -> Unit {
  let lines = if warning { self.failures } else { self.recent }
  if lines.last() == Some(message) {
    return
  }
  if lines.length() == 8 {
    ignore(lines.remove(0))
    self.details_truncated = true
  }
  lines.push(message)
}

///|
fn Progress::failure_detail(self : Progress) -> String {
  let lines = self.failures +
    self.recent.filter(line => !self.failures.contains(line))
  let detail = if lines.is_empty() {
    "no readable error message from subprocess"
  } else {
    lines.join("\n")
  }
  detail +
  (if self.details_truncated {
    "\n[error details incomplete or truncated]"
  } else {
    ""
  })
}

///|
fn Progress::remember_unrecognized(self : Progress, text : String) -> Unit {
  if self.protection_incomplete {
    self.details_truncated = true
    let unavailable = "error detail unavailable because workspace protection values could not be read"
    if !self.unrecognized.contains(unavailable) {
      self.unrecognized.push(unavailable)
    }
    return
  }
  guard self.safe_message(text) is Some(safe) else {
    self.details_truncated = true
    return
  }
  if self.unrecognized.length() == 8 {
    ignore(self.unrecognized.remove(0))
    self.details_truncated = true
  }
  self.unrecognized.push(safe)
}

///|
fn Progress::remember_unrecognized_json(self : Progress, event : Json) -> Unit {
  if self.protection_incomplete {
    self.remember_unrecognized("")
    return
  }
  let truncated : Ref[Bool] = { val: false, }
  let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
  if truncated.val {
    self.details_truncated = true
  }
  self.remember_unrecognized(safe)
}

///|
fn Progress::remember_stderr(self : Progress, text : String) -> Unit {
  if !self.recording {
    return
  }
  let event = @json.parse(text) catch { _ => Json::null() }
  let normalized = if event != Json::null() {
    let truncated : Ref[Bool] = { val: false, }
    let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
    if truncated.val {
      self.details_truncated = true
    }
    safe
  } else {
    text
  }
  guard self.safe_message(normalized) is Some(safe) else {
    self.details_truncated = true
    return
  }
  if self.stderr_lines.length() == 8 {
    ignore(self.stderr_lines.remove(0))
    self.details_truncated = true
  }
  self.stderr_lines.push(safe)
}

///|
async fn Progress::status(self : Progress, event : Json) -> Unit {
  guard field(event, "phase") is Some(Json::String(phase)) &&
    field(event, "state") is Some(Json::String(state)) &&
    ["started", "succeeded", "failed", "skipped"].contains(state) else {
    return
  }
  let recorded_phase = self.safe_message(phase).unwrap_or("[unavailable]")
  if self.phase_count < 128 {
    self.phase_count += 1
    save_diagnostic(
      self.stage,
      state,
      phase=recorded_phase,
      error_type?=if state == "failed" { Some("backend_phase") } else { None },
      evidence?=self.context,
      evidence_stable_operation=true,
      protected_secrets=self.secrets,
      recording=self.recording,
    )
  } else if self.phase_count == 128 {
    self.phase_count += 1
    self.details_truncated = true
    save_diagnostic(
      self.stage,
      "diagnostics-truncated",
      error_type="phase_limit",
      phase=recorded_phase,
      evidence?=self.context,
      evidence_incomplete=true,
      evidence_stable_operation=true,
      protected_secrets=self.secrets,
      recording=self.recording,
    )
  }
  guard phase_label(phase) is Some(label) else { return }
  let key = ["pipeline", "operationId", "phase", "step"]
    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
    .join(":")
  if state == "started" {
    if self.operations.length() >= 256 {
      self.operations.clear()
    }
    self.operations.set(key, @env.now())
    progress_message(label + ": running…")
  } else {
    let duration = match field(event, "durationMs") {
      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
        Some(seconds(value.to_uint64()))
      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
    }
    self.operations.remove(key)
    let timing = duration.map(value => value + ", ").unwrap_or("") +
      "elapsed " +
      seconds(@env.now() - progress_started)
    progress_message(
      label +
      ": " +
      (if state == "succeeded" { "done" } else { state }) +
      " (" +
      timing +
      ")",
    )
  }
}

///|
fn classic_build_step(text : String) -> Bool {
  guard text.has_prefix("Step ") &&
    text[5:].split_once("/") is Some((step, rest)) &&
    rest.split_once(" ") is Some((total, detail)) else {
    return false
  }
  step.length() > 0 &&
  total.length() > 0 &&
  step.iter().all(c => c >= '0' && c <= '9') &&
  total.iter().all(c => c >= '0' && c <= '9') &&
  detail.trim().has_prefix(":")
}

///|
async fn Progress::message(
  self : Progress,
  text : String,
  debug~ : Bool,
  warning~ : Bool,
  emit~ : Bool = true,
) -> Unit {
  if self.protection_incomplete {
    self.details_truncated = true
    self.remember(
      "error detail unavailable because workspace protection values could not be read",
      warning=true,
    )
    return
  }
  for line in text.split("\n") {
    let text = line.trim().to_owned()
    if text == "" {
      continue
    }
    guard self.safe_message(text) is Some(safe) else {
      self.details_truncated = true
      continue
    }
    if !debug || warning {
      self.remember(safe, warning~)
    }
    if !emit {
      continue
    }
    if safe.has_prefix("#") {
      guard safe.split_once(" ") is Some((id, rest)) &&
        id.length() > 1 &&
        id[1:].iter().all(c => c >= '0' && c <= '9') else {
      @fs.file_size(path) <= 65536L else {
      return Json::null()
    }
    @json.parse(@fs.read_file(path).text())
  }) catch {
    error =>
      if @async.is_being_cancelled() {
        raise error
      } else {
        Json::null()
      }
  }
  if field(previous, "priorLoss") is Some(Json::Array(losses)) {
    for loss in losses {
      if diagnostic_previous_losses.length() >= 31 {
        break
      }
      diagnostic_previous_losses.push(diagnostic_previous_loss(loss))
    }
    if losses.length() > 31 {
      diagnostic_previous_losses.push(diagnostic_previous_loss(Json::null()))
    }
  }
  diagnostic_previous_losses.push(diagnostic_previous_loss(previous))
  for event in diagnostic_previous_losses {
    diagnostic_pending.push({ event, failed: true, time: @env.now(), })
  }
  diagnostic_recording_health.incident = true
  diagnostic_recording_health.reason = "previous_run_unflushed"
  diagnostic_recording_health.phase = "recovery"
}

///|
priv struct DiagnosticStructuredSecrets {
  values : Array[String]
  mut visited : Int32
  mut incomplete : Bool
}

///|
fn diagnostic_structured_secrets(
  value : Json,
  found : DiagnosticStructuredSecrets,
  secret~ : Bool = false,
  depth~ : Int32 = 0,
) -> Unit {
  if found.visited >= 65536 || depth >= 64 {
    found.incomplete = true
    return
  }
  found.visited += 1
  match value {
    Json::String(text) if secret && text != "" && text != "[redacted]" => {
      add_protected_secret(found.values, text)
      if found.values.length() > 512 {
        found.incomplete = true
      }
    }
    Json::Array(values) =>
      for item in values {
        if found.incomplete {
          break
        }
        diagnostic_structured_secrets(item, found, secret~, depth=depth + 1)
      }
    Json::Object(values) =>
      for name, item in values {
        if found.incomplete {
          break
        }
        let key = name.to_lower().replace_all(old="_", new="")
        diagnostic_structured_secrets(
          item,
          found,
          secret=secret ||
            credential_field(name, for_diagnostics=true) ||
            key == "pairingcode",
          depth=depth + 1,
        )
      }
    _ => ()
  }
}

///|
fn diagnostic_json(
  value : Json,
  environment : Map[String, String],
  protected_secrets : Array[String],
  truncated : Ref[Bool],
  depth : Int32,
  stable_activity~ : Bool = false,
  secret_states~ : Bool = false,
  stable_operation~ : Bool = false,
  stable_arguments~ : Bool = false,
  parent~ : String = "",
) -> Json {
  let protected_secrets = if depth == 0 {
    let found : DiagnosticStructuredSecrets = {
      values: [],
      visited: 0,
    let mut matched = 0
    for index in 1..<limit {
      while matched > 0 && value[matched] != value[index] {
        matched = prefixes[matched - 1]
      }
      if value[matched] == value[index] {
        matched += 1
      }
      prefixes[index] = matched
    }
    matched = 0
    for index in 0..<boundary {
      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
        matched = prefixes[matched - 1]
      }
      if matched < limit && value[matched] == chars[index] {
        matched += 1
      }
    }
    boundary -= matched
  }
  if boundary == chars.length() {
    text
  } else {
    character_text(chars, 0, boundary) + "[redacted]"
  }
}

///|
priv struct DiagnosticProtectedValues {
  secrets : Array[String]
  mut visited : Int32
  mut incomplete : Bool
}

///|
fn diagnostic_add_protected(
  value : String,
  output : String,
  uncertain : Bool,
  destination : Array[String],
  result : DiagnosticProtectedValues,
) -> Unit {
  if value == "" ||
    (
      !output.contains(value) &&
      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
    ) {
    return
  }
  if result.secrets.length() >= 512 {
    result.incomplete = true
    return
  }
  destination.push(value)
}

///|
fn diagnostic_protected_values(
  value : Json,
  result : DiagnosticProtectedValues,
  output : String,
  uncertain : Bool,
  secret~ : Bool = false,
  depth~ : Int32 = 0,
) -> Unit {
  if result.visited >= 65536 || depth >= 64 {
    result.incomplete = true
    return
  }
  result.visited += 1
  match value {
    Json::String(text) if text != "" && secret => {
      let destination = result.secrets
      diagnostic_add_protected(text, output, uncertain, destination, result)
      for line in text.replace_all(old="\r", new="\n").split("\n") {
        if line != "" && line.length() < text.length() {
          diagnostic_add_protected(
            line.to_owned(),
            output,
            uncertain,
            destination,
            result,
          )
        }
        for word in line.split(" ") {
          for part in word.split("=") {
            if part != "" && part.length() < text.length() {
              diagnostic_add_protected(
                part.to_owned(),
                output,
                uncertain,
                destination,
                result,
              )
            }
          }
        }
      }
      let escaped = Json::string(text).stringify()
      if escaped.length() > 2 {
        let encoded = escaped[1:escaped.length() - 1].to_owned()
        if encoded != text {
          diagnostic_add_protected(
            encoded, output, uncertain, destination, result,
          )
    }
  }
}

///|
// A recording grammar, never a replacement for checkout validation. Excludes
// URLs, credential forms, control characters and Git's invalid ref syntax.
fn diagnostic_ref(text : String) -> Bool {
  text.length() <= 1024 &&
  !text.has_prefix("-") &&
  !text.contains("..") &&
  !text.contains("@{") &&
  text != "@" &&
  text
  .split("/")
  .iter()
  .all(part => {
    part != "" &&
    !part.has_prefix(".") &&
    !part.has_suffix(".") &&
    !part.has_suffix(".lock")
  }) &&
  text
  .iter()
  .all(c => {
    c > ' ' &&
    c != '\u007f' &&
    !['~', '^', ':', '?', '*', '[', '\\'].contains(c)
  })
}

