          )
          validate_state(state)
          set_field(state, "tunnelDirectory", Json::string(directory))
          target = workspace_text(state, required(state, "workspaceId"))
          progress_message(
            target +
            ": " +
            (if restart { "restart" } else { "recover" }) +
            " running…",
          )
          target_state = Some(state)
          recover_connection(state, restart~, saved_environment=true)
          progress_message(
            target +
            ": " +
            (if restart { "restart" } else { "recover" }) +
            " done",
          )
        } catch {
          error =>
            if @fs.exists(directory) {
              failures += 1
              let environment = target_state.map(state => {
                workspace_environment(state)
              })
              let message = diagnostic_error(error, environment?)
              let ssh_detail = if message.contains(
                  "SSH and relay readiness timed out",
                ) &&
                !message.contains("last connection failure:") {
                connection_failure(directory, [
                  "worker-error.json", "ssh-error.json",
                ]).unwrap_or("SSH failure details unavailable")
              } else {
                ""
              }
              let combined = message +
                (if ssh_detail == "" {
                  ""
                } else {
                  "\nlast connection failure: " + ssh_detail
                })
              let detail = if target_state is Some(state) {
                workspace_error_detail(state, AdapterError(combined))
              } else {
                diagnostic_text(combined, environment?)
              }
              if target == "[unavailable]" && target_state is Some(state) {
                target = workspace_text(state, name)
              }
              progress_message(target + ": failed: " + detail)
              save_diagnostic(
                "recover",
                "failed",
                tunnel_directory=directory,
                error_type="target_failed",
                error_message=detail,
                recording?=target_state.map(state => operation_recording(state)),
              )
            } else {
              save_diagnostic("recover", "target-removed")
            }
        }
      })
    }
  })
  guard failures == 0 else {
    raise AdapterError(
      "Some connections could not be recovered; other targets were attempted",
    )
  }
