///|
priv struct DiagnosticStructuredSecrets {
  values : Array[String]
  mut visited : Int32
  mut incomplete : Bool
}

///|
fn diagnostic_structured_secrets(
  value : Json,
  found : DiagnosticStructuredSecrets,
  secret~ : Bool = false,
  depth~ : Int32 = 0,
) -> Unit {
  if found.visited >= 65536 || depth >= 64 {
    found.incomplete = true
    return
  }
  found.visited += 1
  match value {
    Json::String(text) if secret && text != "" && text != "[redacted]" => {
      add_protected_secret(found.values, text)
      if found.values.length() > 512 {
        found.incomplete = true
      }
    }
    Json::Array(values) =>
      for item in values {
        if found.incomplete {
          break
        }
        diagnostic_structured_secrets(item, found, secret~, depth=depth + 1)
      }
    Json::Object(values) =>
      for name, item in values {
        if found.incomplete {
          break
        }
        let key = name.to_lower().replace_all(old="_", new="")
        diagnostic_structured_secrets(
          item,
          found,
          secret=secret ||
            credential_field(name, for_diagnostics=true) ||
  secrets : Array[String]
  mut visited : Int32
  mut incomplete : Bool
}

///|
fn diagnostic_add_protected(
  value : String,
  output : String,
  uncertain : Bool,
  destination : Array[String],
  result : DiagnosticProtectedValues,
) -> Unit {
  if value == "" ||
    (
      !output.contains(value) &&
      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
