///|
async fn flush_diagnostic_recording() -> Unit {
  if diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0 {
    return
  }
  @async.with_timeout(1000, async fn() {
    while !diagnostic_pending.is_empty() ||
          diagnostic_recording_health.dropped > 0 {
      try_flush_diagnostic_recording()
      if !diagnostic_pending.is_empty() ||
        diagnostic_recording_health.dropped > 0 {
        @async.sleep(25)
      }
    }
  }) catch {
    error => if @async.is_being_cancelled() { raise error }
  }
}

///|
async fn finish_diagnostic_recording() -> Unit {
  flush_diagnostic_recording()
  if !diagnostic_pending.is_empty() || diagnostic_recording_health.dropped > 0 {
    diagnostic_recording_health.run_partial = true
    publish_diagnostic_health()
    return
  }
  if diagnostic_run_has_events.val {
    save_diagnostic(
      "diagnostic-run",
      "finished",
      run_completeness=if diagnostic_recording_health.run_partial {
        "partial"
      } else {
        "complete"
      },
      recording=true,
    )
    flush_diagnostic_recording()
    if !diagnostic_pending.is_empty() || diagnostic_recording_health.dropped > 0 {
      diagnostic_recording_health.run_partial = true
      publish_diagnostic_health()
    }
  }
}

///|
let recording_run_id : String = @env.now().to_string() +
  "_" +
  proxy_pid().to_string()

///|
fn diagnostic_error(
  error : Error,
  environment? : Map[String, String],
) -> String {
  let (message, omitted) = match error {
    AdapterError(detail) => (detail, false)
    InvalidConfig(detail) => (detail, false)
    SettingsProcessError(phase, code, status, detail) =>
      (
        "Orca settings process failed (exit \{status}, \{phase}: \{code})" +
        detail.map(value => ":\n" + value).unwrap_or(""),
        false,
      )
    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
    @json.InvalidNumber(position, _) =>
      (
        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
        true,
      )
    _ => (error.to_string(), false)
  }
  diagnostic_text(message, environment?, omitted~)
}

///|
fn diagnostic_text(
  message : String,
  environment? : Map[String, String],
  omitted~ : Bool = false,
  protected_secrets? : Array[String],
  incomplete_final_line~ : Bool = false,
) -> String {
  let progress = Progress::new("diagnostic-error", environment?)
