async test "recovery progress protects saved credential values in workspace identifiers" {
  let (directory, env, state) = idle_fixture(3600000)
  defer cleanup_fixture(directory)
  let worker = required(state, "tunnelDirectory")
  set_field(
    state,
    "workspaceId",
    Json::string("prefixfixture-known-valuesuffix"),
  )
  @fs.write_file(worker + "/state.json", state.stringify())
  env.set("WORKSPACE_PRIVATE_TOKEN", "fixture-known-value")
  save_fixture_environment(worker, env)
  env.remove("WORKSPACE_PRIVATE_TOKEN")
  @fs.remove(directory + "/created")
  let (status, _, errors) = invoke("recover", env, directory)
  assert_true(status != 0)
  assert_true(errors.contains("prefix[redacted]suffix"), msg=errors)
  assert_false(errors.contains("fixture-known-value"), msg=errors)
  assert_false(
    Json::array(fixture_events(directory))
    .stringify()
    .contains("fixture-known-value"),
  )
}

///|
async test "readiness timeout retains stderr captured before cancellation" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  env.set("ORCA_ENV_DEVSY_CONNECTION_TIMEOUT_MS", "6000")
  env.set("WORKSPACE_PRIVATE_TOKEN", "fixture-readiness-timeout-secret")
  @fs.write_file(
    directory + "/orca.yaml",
    "devsy: {connection: ssh, buildRef: refs/heads/main}\nenvironmentRecipes: [{id: test}]\n",
  )
  let (status, output, errors) = invoke("create", env, directory)
  assert_eq(status, 0, msg=errors)
  let result = @json.parse(output)
  let payload : Json = { "schemaVersion": 1, "recipeResult": result }
  defer ignore(invoke("destroy", env, directory, payload~))
  @fs.rename(directory + "/bin/ssh", directory + "/bin/ssh-original")
  let wrapper =
    #|#!/bin/sh
    #|case "$*" in *'orca-relay-readiness'*) printf 'readiness transport connection refused %s\n' "$WORKSPACE_PRIVATE_TOKEN" >&2; exec sleep 20 ;; esac
    #|exec "$HOME/bin/ssh-original" "$@"
  @fs.write_file(directory + "/bin/ssh", wrapper + "\n", permission=0o700)
  let (recovered, _, _) = invoke("recover", env, directory, payload~)
  assert_true(recovered != 0)
  let events = fixture_events(directory)
  let timeouts = events.filter(event => {
    field(event, "stage") == Some(Json::string("relay-probe")) &&
    field(event, "errorType") == Some(Json::string("ssh_timeout"))
  })
  assert_true(timeouts.length() > 0)
  let timeout = timeouts[0]
  assert_true(
    required(timeout, "errorMessage").contains(
      "readiness transport connection refused",
    ),
  )
  assert_eq(field(timeout, "detailsTruncated"), Some(Json::boolean(true)))
  assert_false(
    Json::array(events).stringify().contains("fixture-readiness-timeout-secret"),
  )
  @fs.remove(directory + "/bin/ssh")
  @fs.rename(directory + "/bin/ssh-original", directory + "/bin/ssh")
}

///|
async test "unsupported readiness records the observed schema version" {
  for version in ["2", "3", "\"invalid\"", "null"] {
    let (directory, env) = fixture()
    defer cleanup_fixture(directory)
    @fs.write_file(
      directory + "/orca.yaml",
      "devsy: {connection: ssh, buildRef: refs/heads/main}\nenvironmentRecipes: [{id: test}]\n",
    )
    env.set("FAKE_READY_VERSION", version)
    @fs.rename(directory + "/bin/ssh", directory + "/bin/ssh-original")
    let wrapper =
      #|#!/bin/sh
      #|case "$*" in *'orca-relay-readiness'*) printf '{"version":%s}\n200' "$FAKE_READY_VERSION"; exit 0 ;; esac
      #|exec "$HOME/bin/ssh-original" "$@"
    @fs.write_file(directory + "/bin/ssh", wrapper + "\n", permission=0o700)
    let (status, _, _) = invoke("create", env, directory)
    assert_true(status != 0)
    let events = fixture_events(directory).filter(event => {
      field(event, "stage") == Some(Json::string("relay-probe")) &&
      field(event, "status") == Some(Json::string("unsupported"))
    })
    assert_true(events.length() > 0)
    let observed = field(
      field(events[0], "evidence").unwrap(),
      "responseVersion",
    ).unwrap()
    if version == "2" || version == "3" {
      assert_eq(field(observed, "state"), Some(Json::string("number")))
      assert_eq(field(observed, "value"), Some(@json.parse(version)))
    } else {
      assert_eq(field(observed, "state"), Some(Json::string("invalid_type")))
      assert_eq(
        field(observed, "type"),
        Some(Json::string(if version == "null" { "null" } else { "string" })),
      )
    }
  }
}

