///|
async test "readiness timeout retains stderr captured before cancellation" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  env.set("ORCA_ENV_DEVSY_CONNECTION_TIMEOUT_MS", "6000")
  env.set("WORKSPACE_PRIVATE_TOKEN", "fixture-readiness-timeout-secret")
  @fs.write_file(
    directory + "/orca.yaml",
    "devsy: {connection: ssh, buildRef: refs/heads/main}\nenvironmentRecipes: [{id: test}]\n",
  )
  let (status, output, errors) = invoke("create", env, directory)
  assert_eq(status, 0, msg=errors)
  let result = @json.parse(output)
  let payload : Json = { "schemaVersion": 1, "recipeResult": result }
  defer ignore(invoke("destroy", env, directory, payload~))
  @fs.rename(directory + "/bin/ssh", directory + "/bin/ssh-original")
  let wrapper =
    #|#!/bin/sh
    #|case "$*" in *'orca-relay-readiness'*) printf 'readiness transport connection refused %s\n' "$WORKSPACE_PRIVATE_TOKEN" >&2; exec sleep 20 ;; esac
    #|exec "$HOME/bin/ssh-original" "$@"
  @fs.write_file(directory + "/bin/ssh", wrapper + "\n", permission=0o700)
  let (recovered, _, _) = invoke("recover", env, directory, payload~)
  assert_true(recovered != 0)
  let events = fixture_events(directory)
  let timeouts = events.filter(event => {
    field(event, "stage") == Some(Json::string("relay-probe")) &&
    field(event, "errorType") == Some(Json::string("ssh_timeout"))
  })
  assert_true(timeouts.length() > 0)
  let timeout = timeouts[0]
  assert_true(
    required(timeout, "errorMessage").contains(
      "readiness transport connection refused",
    ),
  )
  assert_eq(field(timeout, "detailsTruncated"), Some(Json::boolean(true)))
  assert_false(
    Json::array(events).stringify().contains("fixture-readiness-timeout-secret"),
  )
  @fs.remove(directory + "/bin/ssh")
  @fs.rename(directory + "/bin/ssh-original", directory + "/bin/ssh")
}

