///|
priv enum RelayReadiness {
  Ready
  WaitingForGitHelper
  Retry(String)
  Unsupported
}

///|
async fn relay_readiness(
  state : Json,
  directory : String,
  git_enabled : Bool,
) -> RelayReadiness {
  let script =
    #|# orca-relay-readiness
    #|set -eu
    #|curl --disable --noproxy '*' --silent --max-time 1 --max-filesize 4096 --write-out '\n%{http_code}' http://localhost:12049/ready
  let started = @env.now()
  let result = @async.with_timeout(3000, async fn() {
    let (code, output, _) = @process.collect_output(
      workspace_program(state, "ssh"),
      extra_env=workspace_environment(state),
      cwd?=workspace_directory(state).map(path => path[:]),
      inherit_env=false,
      ssh_mux_options(state, directory) + [script],
    )
    if code != 0 {
      return RelayReadiness::Retry(
        if code == 28 {
          "http_timeout"
        } else {
          "transport_error"
        },
      )
    }
    let text = output.text().trim().to_owned()
    let lines = text.split("\n").to_array()
    let status = lines.last().unwrap_or("").to_owned()
    if status == "404" {
      return RelayReadiness::Unsupported
    }
    if status != "200" {
      return RelayReadiness::Retry(
        if status == "503" {
          "http_503"
        } else {
          "http_error"
        },
      )
    }
    let body = text[:text.length() - status.length()]
      .to_owned()
      .trim()
      .to_owned()
    let value = @json.parse(body) catch {
      _ => return RelayReadiness::Retry("schema_invalid")
    }
    if field(value, "version") != Some(Json::number(1)) {
      return RelayReadiness::Unsupported
    }
    if field(value, "owner") != field(state, "user") {
      return RelayReadiness::Retry("owner_mismatch")
    }
    for name in ["host_owner", "instance"] {
      if field(value, name) is Some(Json::String(value)) && value != "" {
        continue
      }
      return RelayReadiness::Retry("schema_invalid")
    }
    if git_enabled {
      let helper = "git config --global --get credential.helper | grep -F 'internal agent git-credentials' >/dev/null"
      let (code, _, _) = @process.collect_output(
        workspace_program(state, "ssh"),
        extra_env=workspace_environment(state),
        cwd?=workspace_directory(state).map(path => path[:]),
        inherit_env=false,
        ssh_mux_options(state, directory) + [helper],
      )
      if code == 1 {
        return RelayReadiness::WaitingForGitHelper
      }
      if code != 0 {
        return RelayReadiness::Retry("transport_error")
      }
    }
    RelayReadiness::Ready
  }) catch {
    @async.TimeoutError => RelayReadiness::Retry("ssh_timeout")
    _ => RelayReadiness::Retry("transport_error")
  }
  match result {
    Ready => ()
    WaitingForGitHelper =>
      save_diagnostic(
        "relay-probe",
        "pending",
        error_type="git_helper_unavailable",
        duration_ms=(@env.now() - started).to_double(),
        tunnel_directory=directory,
        recording=workspace_recording(state),
      )
    Retry(reason) =>
      save_diagnostic(
        "relay-probe",
        "failed",
        error_type=reason,
        duration_ms=(@env.now() - started).to_double(),
        tunnel_directory=directory,
        recording=workspace_recording(state),
      )
    Unsupported =>
      save_diagnostic(

///|
async fn execute_inner(mode : String) -> Unit {
  notify(mode)
  if mode == "create" ||
    mode == "resume" ||
    mode == "recover" ||
    mode == "restart" {
    save_diagnostic(
      "connection-budget",
      "selected",
      timeout_ms=connection_timeout_ms(),
    )
  }
  let started = @env.now()
  let (state, previous, deadline) = if mode == "create" {
    let (state, expires) = create_state()
    (state, Json::null(), Some(expires))
  } else {
    let (state, previous) = if mode == "recover" || mode == "restart" {
      connection_timeout(started + connection_timeout_ms().to_uint64(), async fn() {
        lifecycle_state(mode)
      })
    } else {
      lifecycle_state(mode)
    }
    (
      state,
      previous,
      if mode == "recover" || mode == "restart" {
        Some(started + connection_timeout_ms().to_uint64())
      } else {
        None
      },
    )
  }
  let operation = if mode == "resume" || mode == "suspend" || mode == "destroy" {
    Some(connection_operation_lock(state))
  } else {
    None
  }
  defer (if operation is Some(lock) { lock.close() })
  if mode == "resume" {
    guard workspace(state) is Some(current) &&
      field(current, "uid") == field(state, "workspaceUid") else {
      raise AdapterError("Workspace missing or replaced before resume")
    }
    unpause_tunnel(state)
  }
  match mode {
    "create" => {
      create_recording.phase = "connection"
      errdefer discard_created_workspace(state)
      connection_timeout(deadline.unwrap(), async fn() {
        codex_addon(state)
        emit_connection(state, true, deadline?)
      })
    }
    "resume" => {
      ignore(
        devsy(
          state,
          [
            "--result-format",
            "json",
            "workspace",
            "up",
            required(state, "workspaceId"),
            "--ide-launch",
            "skip",
          ] +
          orca_storage_args(state),
          "workspace-resume",
        ),
      )
      let expires = connection_deadline()
    }
    _ => raise AdapterError("Unknown command")
  }
  save_diagnostic(mode, "success")
  progress_message(mode + ": done (" + progress_timing(progress_started) + ")")
}

///|
fn set_field(value : Json, key : String, item : Json) -> Unit {
  if value is Json::Object(map) {
    map.set(key, item)
  }
}

///|
pub extend AdapterError with @debug.Debug::{to_repr}

///|
pub async fn execute(mode : String) -> Unit {
  execute_inner(mode) catch {
    InvalidConfig(message) => {
      progress_message(message + " (" + progress_timing(progress_started) + ")")
      save_diagnostic(mode, "failed")
      raise InvalidConfig(message)
    }
    AdapterError(message) => {
      progress_message(message + " (" + progress_timing(progress_started) + ")")
      save_diagnostic(mode, "failed")
      raise AdapterError(message)
    }
    _ => {
      progress_message(
        mode + ": failed (" + progress_timing(progress_started) + ")",
      )
      save_diagnostic(mode, "failed")
      raise AdapterError(
        mode +
        " failed: unexpected runtime error; diagnostic run " +
        recording_run_id,
      )
    }
  }
}

///|
fn validate_state(state : Json) -> Unit raise {
  ignore(saved_command(state))
  guard valid_workspace_id(required(state, "workspaceId")) &&
    valid_user(required(state, "user")) else {
    raise AdapterError("Invalid workspace identity")
  }

