///|
extern "C" fn proxy_exit(code : Int32) -> Unit = "exit"

///|
fn init {
  let args = @env.args()
  if args.length() > 1 &&
    (args[1] == "--supervisor" || args[1] == "--ssh-proxy") &&
    !@adapter.prepare_ssh_proxy() {
    proxy_exit(127)
  }
}

///|
async fn main {
  let args = @env.args()
  match args {
    [_, "--ssh-proxy", lease, .. command] =>
      proxy_exit(@adapter.ssh_proxy(command.to_owned(), lease~))
    [_, "--supervisor", directory, workspace] =>
      @adapter.supervisor(directory, initial_workspace=workspace)
    [_, "--supervisor", directory] => @adapter.supervisor(directory)
    [_, "--version"] =>
      @stdio.stdout.write("orca-env-devsy " + @adapter.version + "\n")
    [_, "recover"] => @adapter.recover_all()
    [_, "restart"] => @adapter.recover_all(restart=true)
    [
      _,
      "recipe",
      "create"
      | "resume"
      | "suspend"
      | "destroy"
      | "recover"
      | "restart" as mode,
    ] => @adapter.execute(mode)
    [_, "update", .. options] => @adapter.update_server(options.to_owned())
    [_, "status" | "stop" | "resume" as mode, .. options] =>
      @adapter.bulk(mode, options.to_owned())
    [_, "--help"] => @stdio.stdout.write(@adapter.usage)
    _ => @adapter.usage_error()
  }
}
///|
let progress_started : UInt64 = @env.now()

///|
fn seconds(milliseconds : UInt64) -> String {
  let tenths = milliseconds / 100UL
  "\{tenths / 10UL}.\{tenths % 10UL}s"
}

///|
fn progress_timing(started : UInt64) -> String {
  let now = @env.now()
  seconds(now - started) + ", elapsed " + seconds(now - progress_started)
}

///|
priv struct ProgressSink {
  lock : @async.Mutex
  mut available : Bool
}

///|
let progress_sink : ProgressSink = {
  lock: @async.Mutex::Mutex(),
  available: true,
}

///|
async fn progress_message(message : String) -> Unit {
  progress_sink.lock.acquire()
  defer progress_sink.lock.release()
  if !progress_sink.available {
    return
  }
  let clock = @env.now() / 1000UL % 86400UL
  let pad = fn(value : UInt64) {
    if value < 10UL {
      "0" + value.to_string()
    } else {
      value.to_string()
    }
  }
  @stdio.stderr.write(
    pad(clock / 3600UL) +
    ":" +
    pad(clock / 60UL % 60UL) +
    ":" +
    pad(clock % 60UL) +
    " " +
    message +
    "\n",
  ) catch {
    _ => {
      progress_sink.available = false
      save_diagnostic("progress-output", "failed", error_type="progress_io")
    }
  }
}

