const errorFields = ["message", "name", "code", "exitCode", "signal", "reason", "error", "cause"] as const;
const errorSignals = new Set(["SIGHUP", "SIGINT", "SIGTERM", "SIGKILL", "SIGABRT", "SIGSEGV", "SIGPIPE"]);
