///|
async fn relay_readiness(
  state : Json,
  directory : String,
  git_enabled : Bool,
) -> RelayReadiness {
  let script =
    #|# orca-relay-readiness
    #|set -eu
    #|curl --disable --noproxy '*' --silent --max-time 1 --max-filesize 4096 --write-out '\n%{http_code}' http://localhost:12049/ready
  let started = @env.now()
  let environment = workspace_environment(state)
  let mut phase = "readiness"
  let mut exit_code = None
  let mut detail = None
  let result = @async.with_timeout(3000, async fn() {
    let (code, output, stderr) = @process.collect_output(
      workspace_program(state, "ssh"),
      extra_env=environment,
      cwd?=workspace_directory(state).map(path => path[:]),
      inherit_env=false,
      ssh_mux_options(state, directory) + [script],
    )
    exit_code = Some(code)
    if code != 0 {
      if stderr.binary().length() > 0 {
        detail = Some(
          diagnostic_error(AdapterError(stderr.text()), environment~),
        )
      }
      return RelayReadiness::Retry(
        if code == 28 {
          "http_timeout"
        } else {
          "transport_error"
        },
      )
    }
    let text = output.text().trim().to_owned()
    let lines = text.split("\n").to_array()
    let status = lines.last().unwrap_or("").to_owned()
    let body = text[:text.length() - status.length()]
      .to_owned()
      .trim()
      .to_owned()
    if status == "404" {
      return RelayReadiness::Unsupported
    }
    if status != "200" {
      if body != "" {
        detail = Some(diagnostic_error(AdapterError(body), environment~))
      }
      return RelayReadiness::Retry(
        if status == "503" {
          "http_503"
        } else {
          "http_error"
        },
      )
    }
    let value = @json.parse(body) catch {
      error => {
        detail = Some(diagnostic_error(error, environment~))
        return RelayReadiness::Retry("schema_invalid")
      }
    }
    if field(value, "version") != Some(Json::number(1)) {
      return RelayReadiness::Unsupported
    }
    if field(value, "owner") != field(state, "user") {
      return RelayReadiness::Retry("owner_mismatch")
    }
    for name in ["host_owner", "instance"] {
      if field(value, name) is Some(Json::String(value)) && value != "" {
        continue
      }
      return RelayReadiness::Retry("schema_invalid")
    }
    if git_enabled {
      phase = "git-helper"
      let helper = "git config --global --get credential.helper | grep -F 'internal agent git-credentials' >/dev/null"
      let (code, _, stderr) = @process.collect_output(
        workspace_program(state, "ssh"),
        extra_env=environment,
        cwd?=workspace_directory(state).map(path => path[:]),
        inherit_env=false,
        ssh_mux_options(state, directory) + [helper],
      )
      exit_code = Some(code)
      if code != 0 && stderr.binary().length() > 0 {
        detail = Some(
          diagnostic_error(AdapterError(stderr.text()), environment~),
        )
      }
      if code == 1 {
        return RelayReadiness::WaitingForGitHelper
      }
      if code != 0 {
        return RelayReadiness::Retry("transport_error")
      }
    }
    RelayReadiness::Ready
  }) catch {
    @async.TimeoutError => RelayReadiness::Retry("ssh_timeout")
    error => {
      detail = Some(diagnostic_error(error, environment~))
      RelayReadiness::Retry("transport_error")
    }
  }
  match result {
    Ready => ()
    WaitingForGitHelper =>
      save_diagnostic(
        "relay-probe",
        "pending",
        error_type="git_helper_unavailable",
        phase~,
        exit_code?,
        error_message?=detail,
        duration_ms=(@env.now() - started).to_double(),
        tunnel_directory=directory,
        recording=workspace_recording(state),
      )
    Retry(reason) =>
      save_diagnostic(
  create_recording.phase = "ref-resolution"
  let contexts = @json.parse(
    devsy(
      state,
      ["--result-format", "json", "context", "list"],
      "resolve-context",
    ),
  )
  guard contexts is Json::Array(context_items) else {
    raise AdapterError("Invalid Devsy context list")
  }
  let defaults = context_items.filter(item => {
    field(item, "default") == Some(Json::boolean(true))
  })
  guard defaults.length() == 1 else {
    raise AdapterError("No unique effective Devsy context")
  }
  set_field(state, "context", Json::string(required(defaults[0], "name")))
  let repository = match @env.get_env_var("ORCA_REPO_URL") {
    Some(url) if url != "" => url
    _ =>
      command(
        "git",
        ["-C", environment("ORCA_REPO_PATH"), "remote", "get-url", "origin"],
        "repository-remote",
      )
      .trim()
      .to_owned()
  }
  guard !repository.contains("?") && !repository.contains("#") else {
    raise AdapterError(
      "Repository URL must not contain credentials or query parameters",
    )
  }
  if repository.has_prefix("ssh://") {
    let authority = repository.split("/").to_array()[2]
    if authority.split_once("@") is Some((userinfo, _)) {
      guard !userinfo.contains(":") else {
        raise AdapterError("Repository URL must not contain credentials")
      }
    }
  }
  if repository.has_prefix("https://") || repository.has_prefix("http://") {
    guard !repository.split("/").to_array()[2].contains("@") else {
      raise AdapterError("Repository URL must not contain credentials")
    }
  }
  save_diagnostic("repository-source", "selected", evidence={
    "url": repository,
    "source": if @env.get_env_var("ORCA_REPO_URL") is Some(url) && url != "" {
      "environment"
    } else {
      "git-origin"
    },
    "path": environment("ORCA_REPO_PATH"),
  })
  let default_output = command(
    "git",
    ["ls-remote", "--symref", "--", repository, "HEAD"],
    "resolve-default-branch",
  )
  let mut default_ref = None
  for line in default_output.split("\n") {
    if line.split_once("\t") is Some((reference, "HEAD")) &&
      reference.has_prefix("ref: refs/heads/") {
      default_ref = Some(reference[5:].to_owned())
    }
  }
  let lookup_ref = if build_ref.has_prefix("refs/remotes/origin/") {
    "refs/heads/" + build_ref[20:].to_owned()
  } else if build_ref.has_prefix("origin/") {
      buffer.write_char_utf8(chars[i])
      i += 1
    }
  }
  @utf8.decode_lossy(buffer.to_bytes())
}

///|
fn redact_credentials(text : String) -> String {
  let chars = text.iter().to_array()
  let buffer = @buffer.Buffer(size_hint=text.length())
  let mut i = 0
  let mut url = false
  while i < chars.length() {
    if credential_space(chars[i]) || ['"', '\''].contains(chars[i]) {
      url = false
    }
    if chars[i] == ':' &&
      i + 2 < chars.length() &&
      chars[i + 1] == '/' &&
      chars[i + 2] == '/' {
      url = true
      buffer.write_string_utf8("://")
      i += 3
      let mut end = i
      let mut user_end = None
      while end < chars.length() &&
            !credential_end(chars[end]) &&
            !['/', '?'].contains(chars[end]) {
        if chars[end] == '@' {
          user_end = Some(end)
        }
        end += 1
      }
      if user_end is Some(end) {
