///|
async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  timeout_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
  error_message? : String,
  details_truncated~ : Bool = false,
  tunnel_directory? : String,
  expected_workspace_uid? : String,
  observed_workspace_uid? : String,
  evidence? : Json,
  recording? : Bool,
) -> Unit {
  if !recording.unwrap_or(
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
    ) {
    return
  }
  try {
    let dir = adapter_state_home()
    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
    @fs.chmod(dir, 0o700)
    let path = dir + "/events.jsonl"
    if @fs.exists(path) &&
      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
      return
    }
    if @fs.exists(path) && @fs.file_size(path) > 262144L {
      @fs.remove(path)
    }
    let event : Json = {
      "stage": stage,
      "status": status,
      "time": @env.now().to_string(),
      "runId": recording_run_id,
      "adapterVersion": version,
    }
    if create_recording.attempt > 0 {
      set_field(
        event,
        "createAttempt",
        Json::number(create_recording.attempt.to_double()),
      )
      set_field(event, "createPhase", Json::string(create_recording.phase))
    }
    if error_message is Some(message) {
      set_field(event, "errorMessage", Json::string(message))
      set_field(event, "detailsTruncated", Json::boolean(details_truncated))
    }
    if tunnel_directory is Some(directory) {
      set_field(event, "tunnelDirectory", Json::string(directory))
    }
    for
      pair in [
        ("expectedWorkspaceUid", expected_workspace_uid),
        ("observedWorkspaceUid", observed_workspace_uid),
      ] {
      if pair.1 is Some(value) {
        set_field(event, pair.0, Json::string(redact_credentials(value)))
      }
    }
    if source is Some(evidence) {
      set_field(event, "source", evidence.to_json())
    }
    if evidence is Some(value) {
      if value.stringify().length() <= 65536 {
        set_field(event, "evidence", value)
      } else {
        set_field(event, "evidenceTruncated", Json::boolean(true))
        set_field(event, "completeness", Json::string("partial"))
      }
    }
    if os_errno is Some(code) && code > 0 && code < 4096 {
      set_field(event, "osErrno", Json::number(code.to_double()))
    }
    if exit_code is Some(code) {
      set_field(event, "exitCode", Json::number(code.to_double()))
    }
    for pair in [("errorType", error_type), ("phase", phase)] {
      if pair.1 is Some(text) {
        set_field(event, pair.0, Json::string(text))
      }
    }
    if duration_ms is Some(value) {
      set_field(event, "durationMs", Json::number(value))
    }
    if attempt is Some(value) {
      set_field(event, "attempt", Json::number(value.to_double()))
    }
    if timeout_ms is Some(value) {
      set_field(event, "timeoutMs", Json::number(value.to_double()))
    }
  await Orca.settleLaunches(cleanup.signal).catch(() => cleanupErrors.push("orca-launch"));
  const cleanDevsy = (args: string[], timeout: number) => cleanupRun([devsy, "--home", dhome, ...args], { env, timeout, signal: cleanup.signal });
  const orcaObservations = await orca?.observations.snapshot();
  const diagnostics = await adapterDiagnostics(env.XDG_STATE_HOME!).catch(() => ({ available: false, readFailed: true, events: [] }));
  for (const provisionId of pending) await orca?.call("ephemeralVm", "cancelProvision", { provisionId }, cleanup.signal).catch(() => cleanupErrors.push("cancel-provision"));
  if (shared) {
    gitStats = await shared.stats(cleanup.signal).catch(() => { cleanupErrors.push("git-server-metrics"); return undefined; });
    console.log("Authenticated Git requests:", JSON.stringify(gitStats && { accepted: gitStats.accepted, rejected: gitStats.rejected }));
  }
  await Promise.all(workspaces.map(active => active.close(cleanup.signal).catch(() => cleanupErrors.push("ssh-sessions"))));
  const remainingRuntimes = orca ? await orca.call<Runtime[]>("ephemeralVm", "listRuntimes", undefined, cleanup.signal).catch(() => runtimes) : [];
  await Promise.all(remainingRuntimes.filter(runtime => runtime.status !== "cleaned").map(async runtime => {
    try {
      const cleaned = await orca!.call<Runtime>("ephemeralVm", "cleanup", { runtimeId: runtime.id }, cleanup.signal);
      assert.equal(cleaned.status, "cleaned");
    } catch { cleanupErrors.push("orca-runtime"); }
  }));
  await orca?.close().catch(() => cleanupErrors.push("orca-client"));
  await shared?.close(cleanup.signal).catch(() => cleanupErrors.push("git-server-cleanup"));
  // This Devsy home was created for this run and contained no user workspaces.
  // Reap creations that failed before Orca could persist their receipts as well.
  try {
    const remaining = source ? JSON.parse(await cleanDevsy(["--result-format", "json", "workspace", "list", "--skip-pro"], budgets.operation)) as { id: string }[] : [];
    for (const item of remaining) assert(/^[a-z0-9-]+-[a-z]+-[a-z0-9]{2}$/.test(item.id));
    await Promise.all(remaining.map(async item => {
      await cleanDevsy(["workspace", "delete", item.id, "--force", "--ignore-not-found"], budgets.lifecycle).catch(() => cleanupErrors.push("devsy-cleanup"));
      cleanupErrors.push("unreleased-workspace");
    }));
  } catch { cleanupErrors.push("devsy-cleanup"); }
  if (provider === "apple" || provider === "docker" || provider === "podman") {
    const volumes = new Set(runtimes.map(runtime => runtime.recipeResult.userData.orcaVolume).filter((value): value is string => typeof value === "string"));
    const rawEvents = await Bun.file(env.XDG_STATE_HOME + "/orca-env-devsy/events.jsonl").text().catch(() => "");
    for (const line of rawEvents.split("\n").filter(Boolean)) {
      try { const event = JSON.parse(line); if (typeof event.source?.volume === "string") volumes.add(event.source.volume); } catch {}
    }
    for (const volume of volumes) {
      if (!/^orca-env-devsy-oe-create-[a-zA-Z0-9.-]+$/.test(volume)) { cleanupErrors.push("orca-volume-ownership"); continue; }
      try {
        const listed = await cleanupRun([provider === "apple" ? "container" : provider, "volume", "ls", "--format", "json"], { env, timeout: budgets.operation, signal: cleanup.signal });
        if (volumeNames(listed).includes(volume)) {
          cleanupErrors.push("unreleased-orca-volume");
          await cleanupRun([provider === "apple" ? "container" : provider, "volume", "rm", volume], { env, timeout: budgets.operation, signal: cleanup.signal });
        }
      } catch { cleanupErrors.push("orca-volume"); }
    }
  }
  if (podmanStoreOwned) {
    // Both stores were verified inside this disposable run before provisioning.
    // Reset also reaps the daemonless runtime's pause process and storage mounts.
    await cleanupRun(["podman", "system", "reset", "--force"], { env, timeout: budgets.lifecycle, signal: cleanup.signal }).catch(() => cleanupErrors.push("podman-runtime"));
  }

}

const runOrdinals = new Map<string, number>();
export function diagnosticRun(id: unknown): number | undefined {
  if (typeof id !== "string" || id.length > 64) return undefined;
  if (!runOrdinals.has(id)) runOrdinals.set(id, runOrdinals.size);
  return runOrdinals.get(id);
}

export async function adapterDiagnostics(state: string) {
  const file = Bun.file(state + "/orca-env-devsy/events.jsonl");
  if (!await file.exists()) return { available: false, events: [] };
  if (file.size > 300_000) return { available: false, oversized: true, events: [] };
  const stages = new Set("supervisor-registration supervisor supervisor-launch supervisor-workspace supervisor-transport idle-configuration idle-observation idle-reset idle-connection idle-stop idle-monitor bulk bulk-context bulk-observation bulk-workspace create resume suspend destroy recover restart recover-workspace recover-worker recover-server workspace-create workspace-create-full workspace-delete workspace-list workspace-resume workspace-stop workspace-status resolve-root resolve-context resolve-build-ref resolve-default-branch clone-shallow clone-full clone-override git-object-storage verify-build-source verify-build-commit task-commit-presence validate-branch validate-build-branch checkout-workspace clone-fallback orca-install orca-serve orca-server-probe orca-tunnel ssh-proxy relay-probe relay-recovery connection-readiness ssh-tunnel-restart git-relay git-relay-options git-relay-recording codex-auth codex-refresh create-cleanup".split(" "));
  const statuses = new Set("stop_failed selected monitoring observation_unknown awaiting_idle_confirmation observer_reconnecting tunnel_reconnecting workspace_stopped workspace_resumed Running Stopped Busy NotFound reuse reused restore restart start adopted started succeeded skipped diagnostics-truncated success failed warning degraded stopped retry process-error exit-error connected connecting disconnected ready checking unsupported disabled pending timeout unavailable cancelled ownership-error workspace-stopped target-removed".split(" "));
  const errors = new Set("registration_failed workspace_registration_failed workspace_task_failed transport_cleanup_failed restart_failed process_signal observer_unavailable monitor_failed timer_unavailable workspace_stop_failed address_in_use authentication_failed host_key_failed connection_refused connection_timeout name_resolution control_socket missing_resource permission_denied process_exit database_locked file_limit vm_boot vm_network vm_mount memory_exhausted disk_exhausted vm_image vm_create vm_start process_api process_os process_utf8 readiness_unavailable readiness_timeout readiness_unsupported http_timeout http_error http_503 ssh_timeout transport_error owner_mismatch schema_invalid git_helper_unavailable progress_io backend_phase phase_limit".split(" "));
  const phases = new Set("read cloning_repository resolving_config initialize_command preparing_devcontainer building_image starting_container injecting_agent running_lifecycle_hook waiting_for running_command configuring_workspace configuring_ssh starting_ssh_tunnel launching_ide stopping_workspace deleting_workspace rebuilding_workspace resetting_workspace importing_workspace ready failed installing_provider resolving_options running_init".split(" "));
  const events: { stage: string; status: string; run?: number; elapsedMs?: number; phase?: string; errorType?: string; exitCode?: number; osErrno?: number }[] = [];
  let origin: number | undefined;
  let omitted = 0;
  for (const line of (await file.text()).split("\n").filter(Boolean)) {
    try {
      const event = JSON.parse(line);
      if (!stages.has(event.stage) || !statuses.has(event.status)) { omitted++; continue; }
      const run = diagnosticRun(event.runId);
      const time = typeof event.time === "string" ? Number(event.time) : NaN;
      if (Number.isFinite(time) && origin === undefined) origin = time;
      const elapsedMs = origin === undefined ? NaN : time - origin;
      events.push({ stage: event.stage, status: event.status, ...(run === undefined ? {} : { run }), ...(Number.isFinite(elapsedMs) && Math.abs(elapsedMs) <= 86_400_000 ? { elapsedMs: Math.round(elapsedMs) } : {}), ...(phases.has(event.phase) ? { phase: event.phase } : {}), ...(errors.has(event.errorType) ? { errorType: event.errorType } : {}), ...(Number.isInteger(event.osErrno) && event.osErrno > 0 && event.osErrno < 4096 ? { osErrno: event.osErrno } : {}), ...(Number.isInteger(event.exitCode) && Math.abs(event.exitCode) <= 255 ? { exitCode: event.exitCode } : {}) });
    } catch { omitted++; }
  }
  return { available: true, omitted, truncated: events.length > 100, events: [...events.slice(0, -100).filter(event => ["failed", "exit-error", "process-error", "warning"].includes(event.status)), ...events.slice(-100)] };
}
///|
let progress_started : UInt64 = @env.now()

///|
fn seconds(milliseconds : UInt64) -> String {
  let tenths = milliseconds / 100UL
  "\{tenths / 10UL}.\{tenths % 10UL}s"
}

///|
fn progress_timing(started : UInt64) -> String {
  let now = @env.now()
  seconds(now - started) + ", elapsed " + seconds(now - progress_started)
}

///|
priv struct ProgressSink {
  lock : @async.Mutex
  mut available : Bool
}

///|
let progress_sink : ProgressSink = {
  lock: @async.Mutex::Mutex(),
  available: true,
}

///|
async fn progress_message(message : String) -> Unit {
  progress_sink.lock.acquire()
  defer progress_sink.lock.release()
  if !progress_sink.available {
    return
  }
  let clock = @env.now() / 1000UL % 86400UL
  let pad = fn(value : UInt64) {
    if value < 10UL {
      "0" + value.to_string()
    } else {
      value.to_string()
    }
  }
  @stdio.stderr.write(
    pad(clock / 3600UL) +
    ":" +
    pad(clock / 60UL % 60UL) +
    ":" +
    pad(clock % 60UL) +
    " " +
    message +
    "\n",
  ) catch {
    _ => {
      progress_sink.available = false
      save_diagnostic("progress-output", "failed", error_type="progress_io")
    }
  }
}

///|
fn devsy_progress_stage(stage : String) -> Bool {
  [
    "workspace-create", "workspace-create-full", "workspace-resume", "workspace-stop",
    "workspace-delete", "create-cleanup",
  ].contains(stage)
}

///|
fn phase_label(phase : String) -> String? {
  match phase {
    "cloning_repository" => Some("Clone repository")
    "resolving_config" => Some("Resolve devcontainer config")
    "initialize_command" => Some("Initialize")
    "preparing_devcontainer" => Some("Prepare devcontainer")
    "building_image" => Some("Build image")
    "starting_container" => Some("Start container")
    "injecting_agent" => Some("Install Devsy agent")
    "running_lifecycle_hook" => Some("Run lifecycle hooks")
    "waiting_for" => Some("Wait for container")
    "running_command" => Some("Run command")
    "configuring_workspace" => Some("Configure workspace")
    "configuring_ssh" => Some("Configure SSH")
    "starting_ssh_tunnel" => Some("Start SSH tunnel")
    "launching_ide" => Some("Prepare IDE")
    "stopping_workspace" => Some("Stop workspace")
    "deleting_workspace" => Some("Delete workspace")
    "rebuilding_workspace" => Some("Rebuild workspace")
    "resetting_workspace" => Some("Reset workspace")
    "importing_workspace" => Some("Import workspace")
    "ready" => Some("Workspace ready")
    "failed" => Some("Workspace failed")
    "installing_provider" => Some("Install provider")
    "resolving_options" => Some("Resolve provider options")
    "running_init" => Some("Initialize provider")
    _ => None
  }
}

///|
priv struct Progress {
  stage : String
  operations : Map[String, UInt64]
  builds : Map[String, String]
  secrets : Array[String]
  recording : Bool
