export async function adapterDiagnostics(state: string) {
  const file = Bun.file(state + "/orca-env-devsy/events.jsonl");
  if (!await file.exists()) return { available: false, events: [] };
  if (file.size > 300_000) return { available: false, oversized: true, events: [] };
  const stages = new Set("supervisor-registration supervisor supervisor-launch supervisor-workspace supervisor-transport idle-configuration idle-observation idle-reset idle-connection idle-stop idle-monitor bulk bulk-context bulk-observation bulk-workspace create resume suspend destroy recover restart recover-workspace recover-worker recover-server workspace-create workspace-create-full workspace-delete workspace-list workspace-resume workspace-stop workspace-status resolve-root resolve-context resolve-build-ref resolve-default-branch repository-source clone-shallow clone-full clone-override git-object-storage verify-build-source verify-build-commit task-commit-presence validate-branch validate-build-branch checkout-workspace clone-fallback orca-install orca-serve desktop-orca-version orca-server-probe orca-tunnel ssh-proxy relay-probe relay-recovery connection-readiness ssh-tunnel-restart git-relay git-relay-options git-relay-recording codex-auth codex-refresh create-cleanup".split(" "));
  const statuses = new Set("stop_failed selected monitoring observation_unknown awaiting_idle_confirmation observer_reconnecting tunnel_reconnecting workspace_stopped workspace_resumed Running Stopped Busy NotFound reuse reused restore restart start adopted started succeeded skipped diagnostics-truncated success failed warning degraded stopped retry process-error exit-error connected connecting disconnected ready checking unsupported disabled pending timeout unavailable cancelled ownership-error workspace-stopped target-removed".split(" "));
  const errors = new Set("registration_failed workspace_registration_failed workspace_task_failed transport_cleanup_failed restart_failed process_signal observer_unavailable monitor_failed timer_unavailable workspace_stop_failed address_in_use authentication_failed host_key_failed connection_refused connection_timeout name_resolution control_socket missing_resource permission_denied process_exit database_locked file_limit vm_boot vm_network vm_mount memory_exhausted disk_exhausted vm_image vm_create vm_start process_api process_os process_utf8 readiness_unavailable readiness_timeout readiness_unsupported http_timeout http_error http_503 ssh_timeout transport_error owner_mismatch schema_invalid git_helper_unavailable progress_io backend_phase phase_limit unexpected".split(" "));
  const phases = new Set("read cloning_repository resolving_config initialize_command preparing_devcontainer building_image starting_container injecting_agent running_lifecycle_hook waiting_for running_command configuring_workspace configuring_ssh starting_ssh_tunnel launching_ide stopping_workspace deleting_workspace rebuilding_workspace resetting_workspace importing_workspace ready failed installing_provider resolving_options running_init readiness git-helper".split(" "));
  const events: { stage: string; status: string; run?: number; elapsedMs?: number; phase?: string; errorType?: string; errorMessage?: string; exitCode?: number; osErrno?: number }[] = [];
  let origin: number | undefined;
  let omitted = 0;
  for (const line of (await file.text()).split("\n").filter(Boolean)) {
    try {
      const event = JSON.parse(line);
      if (!stages.has(event.stage) || !statuses.has(event.status)) { omitted++; continue; }
      const run = diagnosticRun(event.runId);
      const time = typeof event.time === "string" ? Number(event.time) : NaN;
      if (Number.isFinite(time) && origin === undefined) origin = time;
      const elapsedMs = origin === undefined ? NaN : time - origin;
      events.push({ stage: event.stage, status: event.status, ...(run === undefined ? {} : { run }), ...(Number.isFinite(elapsedMs) && Math.abs(elapsedMs) <= 86_400_000 ? { elapsedMs: Math.round(elapsedMs) } : {}), ...(phases.has(event.phase) ? { phase: event.phase } : {}), ...(errors.has(event.errorType) ? { errorType: event.errorType } : {}), ...(typeof event.errorMessage === "string" ? { errorMessage: event.errorMessage } : {}), ...(Number.isInteger(event.osErrno) && event.osErrno > 0 && event.osErrno < 4096 ? { osErrno: event.osErrno } : {}), ...(Number.isInteger(event.exitCode) && Math.abs(event.exitCode) <= 255 ? { exitCode: event.exitCode } : {}) });
    } catch { omitted++; }
  }
  return { available: true, omitted, truncated: events.length > 100, events: [...events.slice(0, -100).filter(event => ["failed", "exit-error", "process-error", "warning"].includes(event.status)), ...events.slice(-100)] };
}
